/* 平成18年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h18.committeeSessions.push(...[{"id":"h18-20060627-6","meetingId":"h18-cm06","date":"2006年6月27日","dateIso":"2006-06-27","committee":"区民委員会","time":"午後２時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件整理しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"まず一つ目に伺いたいのは、品川区はどういうふうにお考えになって、方針転換をされたのか。１４ページですけれども、これは年１回の調査なんだろうと思うんですけれども、この辺の確認です。","respondent":"中山資源循環推進課長","answer":"２３区の方針、変更の考え方ということですけれども、今回の説明でもありましたように。ですから、原点としてのごみの発生抑制であるとか、区においても、リサイクルの可能なものについては進めていくという中での方針決定です。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"その点についての見解を、１点目のところでは伺いたいと思います。ですから、私はそうですか、改めて伺います。","respondent":"中山資源循環推進課長、岩崎環境清掃事業部長","answer":"それはモデル実施以降も、説明をやっていかなければいけない、そういう意味で分別の後退になってはならないという認識です。区民への理解、説明という声にこたえていくべきであるということで… 平成２２年度の東京都の計画の期間内には、全部やめるように、区や市町村に支援をしていきますというような答申です。収集、区分については、国も今年度中に取りまとめが行われる見込みであると。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"いずれ１０年、２０年先には、こういう関係が必ず出てくるわけです。ですから、やっぱり燃やして有害物質になるようなものを排出させるという選択は絶対にやめるべきだと思うので、とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"本田委員","kind":"意見","question":"理事者の説明の中で、よく理解できないところがありましたので、お尋ねします。ちょっとその辺が、先ほどの説明では、よく理解できないところがありましたので、もう一度、数字を含めてご説明を願いますとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"したがいまして、平成１６年度の最終処分量の実績としては、年間約９０万ｔ。この表にありますように、平成２２年度以降、分別変更されますと、４０万ｔになっていく、もしくはそれ以下の数値になっていくです。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"可燃ごみの中で現実に燃やされている廃プラスチックは約６％弱という、この６％弱というのは、どのぐらいまで上がるのか。別の資料では、１０％ぐらいと言っているのを見たことがあるんですけれども、どのぐらいを推定しているのか、その辺はどうか尋ねました。","respondent":"中山資源循環推進課長","answer":"２３区で、今、ワーキンググループを使って、その辺の検討を進めております。今、本田委員からもございましたように、可燃ごみの中のプラスチックが約１０％に増えると見込んでおります。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"２３区で、今１０％ぐらいと言われましたけれども、ちょっと見込みが少ないんじゃないかとも思うんです。１０％というのは、見込みが低いんじゃないでしょうか、そこはどうとらえているんか尋ねました。","respondent":"中山資源循環推進課長","answer":"品川区の場合は、拠点回収で白色トレーの回収もあるわけですけれども、一部の区では廃プラスチックのモデル実施をもう始めている。福岡市の１９％というのは、１０％前後と申しますか、これは現状の測定の中でのものです。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから、全部開示するということをやりながら、もったいないという思想を徹底していくということを図っていただきたいと思うんです。そういう点を施策の中でしっかりと押さえてやっていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"土井委員","kind":"質問・要望","question":"石油と全く同じものですから、これはやっぱりそういう回収の仕方も含めて、しっかりやるべきものだと思うんです。あんなものはマテリアルしてめちゃくちゃにしてしまったら、またつくるのに金がかかるんですから、非常にもったいない話なんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"堺委員","kind":"確認","question":"確認しておきたいのは、下から４行目のところで、昼の時間帯で１度だけの説明会で」と書いてあるんです。関係するお宅のポストに案内の文書を投げ入れたというんですか、決してそういうようなことではいかんのではないかという気がするんです。","respondent":"中山資源循環推進課長","answer":"それから、現在、７月２０日、２６日と予定しておりますけれども、該当地域で実施して以降、実際に区民の方も含めて、再度ご説明を考えております。地域ごとの説明をしていきたいと考えておりますけれども、丁寧な説明を期間中も行い、そういうものを公開していきたい。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問・要望","question":"念のためちょっと確認をしておきたいのは、請願第７号の要旨の１のところには、生活や健康面で大きな不安があります。それから重ねて、品川区としては、今回、このモデル実施については、品川清掃工場で燃やすんか尋ねました。","respondent":"中山資源循環推進課長","answer":"お話のあった数値については、これはモデル期間中にきちんと検証し、公表していくことを考えております。今までのこういう対応を含めて、区民にご安心をいただくように、清掃工場のほうにも伝えていきたいと考えております。","id":"exchange-010"},{"speaker":"堺委員","kind":"質問・要望","question":"実証確認の基本的な考え方の中にもいろいろ、こういうところを確認し、解析をしていくんだと出ております。この辺については、重ねてきちっと公表、公開していただきたいと要望しておきたいと思います。","respondent":"中山資源循環推進課長","answer":"２３区のサーマルリサイクルによる延命効果はどうかということで、新海面処分場が３０年もつであろうというのが、４０年を超えるとの見解が出ました。","id":"exchange-011"},{"speaker":"堺委員","kind":"確認","question":"ちょっと経費の面で確認をしておきたいんですが、これは平成２１年度の、この金額が経費削減につながってくるということの理解でいいんですか。その辺をちょっと説明を求めました。","respondent":"中山資源循環推進課長","answer":"毎年、この変更による継続的な比較効果が出てくるという数字です。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"皆さんのいろいろなご意見を伺いながら、私は質問を１点だけしたいんですけれども、ちょっと知りたいんです。どういうふうな形で行って、どこまで、今到達しているのかというところを教えていただきたいと思うんです。","respondent":"中山資源循環推進課長","answer":"このほかにも、法律の関係で申しますと、そもそも事業系ごみというのは、事業者による自己処理責任と廃棄物処理法にうたわれております。特に平成１２年度、循環型社会形成推進基本法ができて以降、具体化しているです。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"自治権拡充と言いながら、なぜ国や東京都の方針が出ると、そこにぱっと入り込まざるを得ないのかなというのが全然わからないところなんです。やっぱり声を大にして言っていただきたいということを、あわせてお願いしておきながら、そういう意見を述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"４０年ぐらい先に延びたら、その後はわからないということで説明を伺いましたけれども、区民はどれだけの問題意識を持っているのか。そこら辺の説明というのか、どこら辺まで区民に説明をされているのか、ちょっと伺いたいと思います。","respondent":"中山資源循環推進課長","answer":"先ほど申し上げたような処分場の関係を考えますと、それについてはわかりやすく、ご理解いただける説明にかえていくという必要性を感じてあります。今回のごみの分別変更を含め、できるだけわかりやすく説明し、きっかけにしていきたいと考えております。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"お伺いしたように、区民は持たれていないと、今は考えてよろしいのか。","respondent":"中山資源循環推進課長","answer":"再度、説明の仕方を工夫しながら、ご理解を得られるようにしていきたい。ごみ量として反応している部分については、認識は浸透したと思いますけれども、いま一歩のところについての工夫をしていく必要があると考えています。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"要望を取り入れてくださいということで、ごみを分別するという、分別収集ということに関しては非常に意識を持つようになりました。なくなったらどうなるか、最終的に処分できる場所が確保できなくなってしまうということの説明を、十分にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"大沢委員","kind":"意見","question":"今、皆様、さまざまなご意見をいただきましたが、私ども、本日、結論を出すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"本田委員","kind":"質問・要望","question":"要望というか、リサイクルに対してどういうご認識で、プランが発表になっているんです。なかなかこういう実態というのはわからないものが多いものですから、要望と同時に、お願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"本田委員","kind":"質問・要望","question":"そういう要望についても、ぜひ行政サイドは取り組んでいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"堺委員","kind":"意見","question":"私も、きょう、結論を出すということをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"堺委員","kind":"質問","question":"今、委員長は請願第７号とおっしゃっているんですけれども、請願第７号と９号と別々にするんですか。質疑は一緒にして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"堺委員","kind":"確認","question":"説明も一緒にして、質疑も一緒にやったので、取り扱いも一緒でもいいかなと思ったんですが、ちょっと確認をしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"私は、全部採択をしていきたいと思っているんです。２点目の拡大生産者責任については、そういう状況もぜひオープンにしていただきたいという要望もおっしゃっていましたけれども、趣旨的に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"堺委員","kind":"質問・要望","question":"請願第７号の件についてですよね。私も何点か要望した点もありますし、私は、願意に沿いがたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"２、３の要旨でありますが、理事者との質疑応答の中でも十分に留意されて運ばれているという思いも感じられました。質問させていただいたように、この事業を進めてほしいと求めましたが、願意に沿いがたいということで意見を表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"土井委員","kind":"質問・要望","question":"この大願意のところには、とてもとても沿いがたいと考えています。皆さんのほうからもいろいろな要望、その意味では、願意に沿いがたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"本田委員","kind":"質問・要望","question":"環境行政をしっかりと進めていただきたい。特別区長会の決定については、このことを真摯に受けとめておりますので、しっかりと環境行政を進めていただきたいという立場です。","respondent":"川西委員長","answer":"本件については、挙手により採決を行います。","id":"exchange-028"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、プラスチックごみの焼却は中止をしてくださいという、非常に強いご要望がありますが、まさにそれに関してはいろいろと議論の余地があると思われますので、願意には沿いがたいという判断をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"堺委員","kind":"質問","question":"私も、先ほどの質疑の中で、住民に説明し、それについては、先ほどの出た結果については公表し、公開してほしいと申し上げました。プラスチックごみの焼却の中止ですから、請願第７号と同じように、私としては願意に沿いがたいと判断しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"排出者責任、事業者責任がまだまだ不十分な中で、こういうことをやっていくべきではないと思います。リサイクル等々のさまざまな策を、ほんとうに講じていかなきゃいけないと思いますので、私としてはぜひ採択していただきたいと考えています。","respondent":"川西委員長","answer":"今、ご意見をいただきました中で、採択、あるいは不採択と両方に分かれておりますので、本件について、挙手により採決を行います。","id":"exchange-031"},{"speaker":"南委員","kind":"意見","question":"今、委員長が質疑終了後に諮るというお話だったので、前段に受けたほうがいいんじゃないかなという意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"申し上げましたこととそんなに差はないんですけれども、かなり青年の現状が厳しいと聞いておりますし、社会問題になっていると認識しているんです。ですから、具体的な話を伺いたいと思いますので、私はお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"土井委員","kind":"質問","question":"いろいろな状況があるということで質問があれば皆さんやっていただければ結構なんだろうと思うんですけれども、少なくともその種のご意見をいつも発表されているところですから、いらないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"委員会として真摯に受けとめて議論していく、あるいは議論に必要なさまざまな情報を集めて審査をしていくという姿勢が望ましいと思います。そういう点で、受けていただけるように、皆さんにお願いをしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"堺委員","kind":"質問","question":"今回の請願の紹介議員になっている３人のうちのお１人が、去る６月２２日の本会議の一般質問の中でも、その本会議の中で一般質問をお聞きしました。十分、発言者が意を尽くして発言されていると理解をしますので、きょうの段階では、意見陳述はいいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"青年の雇用状況が、今どういう事態になっているのか、区が承知しているところがあれば、教えてほしいと求めました。やっぱり伝えていく必要があるんじゃないかなと思うんですけれども、そのあたりの認識はどういうふうに考えておられるのか、伺いたいと思います。","respondent":"金子産業振興課長","answer":"もう一方で、２００７年問題に象徴されるように、団塊世代の大量の退職が見込まれる。不安定要素も幾つかありますが、基本的な基調として、雇用状況は改善していくだろうというふうな認識をもってあります。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の形態をちょっと伺いたいのと、ぜひ問い合わせをして確認をしていただきたいと思うんです。どうしようかということで、こういう機会を通じてポケット労働法を配ったらどうかということで、増刷をして配っているんだというお話だったんです。","respondent":"金子産業振興課長","answer":"雇用の改善に伴って、賃金が緩やかに増加している等々の、こういう認識があるわけで、私どもも、同じ認識を持っているわけです。他区の対応ですけれども、支援機関なり、問題ある方により広く周知できるのではないかと考えているところです。","id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"版権も無料ということになっているわけですから、すぐさま調査をしていただいて、検討していただきたいと強く要請しておきたいと思います。支援をしていくという立場を貫いていただくことが大事なんじゃないかなと思いますので、その点の見解を聞いて終わりにしたいと思います。","respondent":"金子産業振興課長","answer":"今年も引き続き希望調査がありましたので、申し込みましたところ、今年については、該当しますというお返事を、５月になってからいただいたものです。区としての考え方ですけれども、労働法制の変更によりまして、そういった情報収集の一環を主眼としてやっているところです。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"終わりますが、最後に要望だけ。そういう形で、他区も含めての情報収集もしていただきながら検討をしていただきたいということを、強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"土井委員","kind":"質問・要望","question":"それを行政に求めるのではなく、みずから高めていくという行動こそが必要なのではないでしょうかということで、ご説明をしたところです。ですから、そのような形で運動されるべきだろうと、かえって若い人たちの芽をつむことになりかねないという気持ちでおるんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"堺委員","kind":"確認","question":"そこに行けば、そういうことに関してのあらゆる情報があるわけですから、そこで情報を得ることは可能だろうという気がするんです。たしか、東京都のホームページで見れますということをどこかで聞いたような気がするんですけれども、その辺を確認で教えていただけますか。","respondent":"金子産業振興課長","answer":"ですので、私どもは今年度が１年目ですが、特に国のほうの事業等の変更がなければ、今年度に加えて来年度も可能ではあるという仕組みです。何とか６月１日の「広報しながわ」には載せましたけれども、それが出来次第、早急に区内各地域に配布しようと考えているところです。","id":"exchange-042"},{"speaker":"堺委員","kind":"質問・要望","question":"相談に乗ってくださるということですから、大いに利用してくださいという周知徹底というんでしょうか、一部つながるんじゃないかなという気もします。それについてはいかがでしょうか、ご見解があれば、教えていただきたい。","respondent":"金子産業振興課長","answer":"せっかくの事業ですから、さまざまな媒体を通じて周知をして、希望の方にはご利用していただきたいと思っているところです。そういう意味では、来年度に関しても、今のところ希望する考えです。","id":"exchange-043"},{"speaker":"本田委員","kind":"質問","question":"一つお聞きしたいのは、この請願者のところから、区のほうに同様の申し入れ等はあったんですか、これまでに。この請願が議会に出て、初めてこのことを知ったということなんか尋ねました。","respondent":"金子産業振興課長","answer":"私の承知している範囲では、こういうような要望については、この請願で初めて知ったところです。","id":"exchange-044"},{"speaker":"本田委員","kind":"質問","question":"弁護士を立てて裁判にまでいくような問題ですから、権限をどこまで持たせるかというところに、問題があるわけなんですよ。ですから、その辺の対応も十分に主張すべきところは、一般相談としてはいくらでも受け付けていただくということですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"大沢委員","kind":"質問","question":"就業する自由というものは確保されているわけですから、行政がそこまで手を差し伸べるものなのか、どうか。雇用情勢に応じた施策が行われているわけですから、行政がそこまでやる必要があるのか、どうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"先ほども質問のところで述べたんですけれども、若い青年の方たちが就職に非常に苦労しておられるというのは、社会的な現象として言われていますよね。ですからぜひ、できるだけ視野を広く持ってやっていってあげたいなと思うので、ぜひ採択をしていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"本田委員","kind":"質問・要望","question":"区のほうに要望しておきたいのは、ある意味では要望に沿ってできているというか、ぜひ話を出していただく。つまり、区内の青年層雇用促進についても、行政としては機会を生かして図っていかれますように、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"あまり聞き取れなかったんですけれども、今、委員長がおっしゃった２項目を、１年間かけて中心的に審査、調査をしていきましょうという項目に挙げたということでいいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"堺委員","kind":"意見","question":"伊勢志摩地域のきらり千選、あるいは京都の京は自転車でおまわりやす、その中に幾つかの事例があるんです。そういったところも参考にどうかなと、そんなところもどうかなと、こんな気がしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"堺委員","kind":"質問","question":"第３回定例会が終わって、連休前、その間でよろしいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247239?Template=document&Id=2462#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":46333,"voices":139}},{"id":"h18-20060627-7","meetingId":"h18-cm06","date":"2006年6月27日","dateIso":"2006-06-27","committee":"厚生委員会","time":"午前１０時０４分～午後２時０５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"三上委員","kind":"質問・要望","question":"果たして今日までも、昨年の７月２６日に起きたことですから、ほぼ１年前の話ですよね。即お見舞いに行くのかと、そういったことがどういう体制になっているのか、そこらあたりをちょっとお教えいただきたい。","respondent":"諸岡児童課長、古川児童保健事業部長","answer":"直ちに職員、そしてまた児童センターの館長、そしてまた児童課の課長、前任の課長ですが、直ちに保護者に連絡するとともに病院のほうに出向いたです。そのほか、何回かまたその後もお見舞いを兼ねてお伺いをしているです。 私もさまざまな事業を実施していく中で、中でも事故の対応と申しましょうか、ここまで１年待たずにという意味で。今後とも事故の対応につきまして、このように考えてありますので、よろしくどうぞお願いいたします。","id":"exchange-001"},{"speaker":"三上委員","kind":"意見","question":"全庁的にどう取り組むかというようなことが、１回きちっと話し合われていてもいいのかなと思いますので、横の連携できちっと取り組んでいっていただくようにお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"１点だけちょっと、実は私ども、児童センターに行くケースがちょこちょこあります。再度これを機会に、報告いただいたことを機会にちょっと徹底してみたらいかがかなと思いましたので、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"後遺症とかはなくて済んだのかということを一つお聞きしたいのと、それがなぜ今回こういう重傷なけがに結びついてしまったのかということをどう考えられているのかということと、どのように考えられているのかということを説明するよう求めました。","respondent":"諸岡児童課長","answer":"それから、転倒等で危険性のある遊具の出し入れにつきましても、職員が対応するということを徹底するです。保管場所および保管状況、これの安全性が十分確保されているかというようなことを再確認するようにということで徹底をしてきているところです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"職員がしっかりと管理するということがすごく大事だと思うんですけれども、そういうところで、児童センターの体制上でそういうふうなのができにくいというふうな状況というのはないんか尋ねました。","respondent":"諸岡児童課長","answer":"この卓球台につきましても多少時間はかかりますが、１人で片づけることは可能でございました。したがいまして、職員の手が足りなかったというようなことではございません。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"はい、わかりました。改めて総括をして、これを教訓にこういう事故が二度と起きないようにということで、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認したいと思うんですが、一つは一応和解という形になっているんですが、親御さんとのやりとりの中で、どういう形で和解に至ったのか。そういうことはあったのかどうかという点と、それから損害賠償金が９３万６,１１０円ということですが、算定の方法か何かあるんか尋ねました。","respondent":"諸岡児童課長","answer":"事後の対応も館長、また当時の児童課長が誠意をもって対応させていただいたということでございまして、冷静な対応をいただきまして。２倍になるということで、４,２００円×５０日×２ということで４２万円と、このような内訳です。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ子どもたちの遊びといいますか、午後の生活を保障する形で対処していただきたいなというふうに思っております。それから和解というとちょっと大げさになっちゃうかもしれませんけれども、納得いくような形の対処をお願いして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"改正内容のところの平成１８年３月３１日以前の内容の「麻しん・風しんの単抗原ワクチン」というのは、この言葉と平成１８年４月１日のところに出てくる下の内容の「麻しんあるいは風しんの予防接種をすでに受けたもの」、単抗原ワクチンをやっているという意味でよろしいんか尋ねました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"しかし、４月１日以降は原則としてＭＲの麻しんと風しんの二つのワクチンをあわせたものを使うという制度に変わったわけです。たまたま２回針を刺したけれども、こういう分類になる、こういう意味です。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ああそうなんだなと理解する部分はあるんですけど、もうちょっと何か出すときにわかりやすくお願いしたいなという、それの希望です。中身の問題では全然ないですとの意見を述べました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"その点は、区報の案も実は十分に考えまして、表現がわかりやすいように対応してまいっております。今後の広報等の周知につきましても、わかりやすい表現を心がけて周知を徹底させていきたいと考えております。","id":"exchange-010"},{"speaker":"木下委員","kind":"質問・要望","question":"すみません、私も専門家じゃないんで、ちょっとわからないところを二、三質問させていただきたいなと思うんですけれども。もし、どういう部分をもって確認ができるのかですとか、ちょっと専門家じゃないのでわからないところを教えていただければありがたいんですが。","respondent":"倉橋品川区保健所保健サービス課長","answer":"弱毒された、継続的に病気に対する免疫をつけることができるということで、実は基本的には１回で免疫がつくとされております。過去において集積していたデータを大急ぎで集めたということで、安全性が確認できたという厚生労働省の担当課長の説明でございました。","id":"exchange-011"},{"speaker":"木下委員","kind":"確認","question":"安全性を確認されたものは可とするということだったんで、まだその辺がはっきりしていないかなと思って、私のちょっと聞き違いなのかしら。要するに厚生労働省は、安全確認されたということで、２回目の接種も大丈夫だということの理解でよろしいんか尋ねました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"はい、そのとおりです。今度６月の改正ではその間に今ご説明しましたように、疫学的にもデータによりまして安全性が確認されたという説明です。","id":"exchange-012"},{"speaker":"西本委員","kind":"確認","question":"だから、先ほどちょっと臨床試験の中で安全性が確認できたということですが、おそらく２カ月で臨床試験というのは難しいと思うんですよね。ですから、新たにやった形跡があるのかという確認をしたいと思うんですが、副作用とあわせてお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"最近、春になるんですかね、麻しんがはやったりとかすると、話題に上がるんですね。ですから、安心して相談できることがあるのかなというふうに思いますが、そういう形まで告知の場合にしていただけるものなんか尋ねました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"それは十分に説明することになっておりますが、委員おっしゃるように保護者の方々のご不安に対応しなければならないというふうに考えております。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"今は副作用とかいろんな状況があるんだというふうになると、余計に心配事が多くなってしまっている状況があるようなんですよ。ですから、相談いただけるところはきちんと明記していただいて、自由にご心配なことがあったらどうぞという形でよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと単純なところがわからないところがあったので教えていただきたいんですけど、このハートページを見ると、３カ所しか書かれていないんですね。どこら辺のところから、どういうところからサービスを受けているのかということをひとつ教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"全体では２５施設と表示されておりますが、区民の利用があり介護報酬が給付されている、そういうことを示しております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２点お伺いします。今後施設運営事業者、あるいは施設の利用者がどうなるのか、区として今後どう対応していくことになるのか尋ねました。","respondent":"蓼沼高齢福祉課長、木下福祉高齢事業部長","answer":"老健の利用について、利用できない方がいるかどうかという質問ですけど、今のところ、特段利用できない人がいるということは聞いてございません。これは国の医療制度も含めた全体の見直しの中で検討されていることでございまして、やはり、介護保険系と医療保険系と両方ありますけれども。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"療養病床については、ぜひ受け皿の部分も含めて区としてもご検討いただきたいというふうに思います。とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけ確認させてください。日数と人数の、そこのどういう計算をしているのか、ちょっとそこら辺だけ。","respondent":"蓼沼高齢福祉課長","answer":"ですから、ご利用いただいた延べの年間利用日数を１２カ月で割ったものが、この３,２９８日という数字になっております。ちょっとわかりにくいかもしれませんが。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。ここで見ると９５.５％と、この枠というのは、まだある程度余裕は持っているというふうに判断していいんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"今現在、区内と区外を含めて４３施設で、定期的なご利用については、ほぼ問題なくご利用されているという状況です。来年度になりますが、成幸ホームのほうもショートステイを増設する予定になっておりますので、満員に近いような状況で推移しているという状況です。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"やはり我々もお聞きするのは、緊急にお願いしたいなというケースのときに、そういうところで入れないというケースがときどきお聞きするんですよ。ある面、そういう緊急の方の受け入れる余地が区の中にないのかな、つくれないのかなという思いが一つあるんですけど。","respondent":"蓼沼高齢福祉課長","answer":"今ご指摘のあった点につきまして、やはり緊急切迫したときのご利用というのはあろうかと思います。基本的に予定してありますショートステイのほかに、なるべく調整をするようにやっておりますので、そのほかのことも勘案して。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これで最後にしますけど、ご相談に皆さんが行くと思うので、その辺をうまく調整していただいて、できるだけ無理のない範囲でそういうご要望にこたえていただきたいなと思いますので、よろしくこれからもご検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この辺の中身をちょっと教えていただきたいのと、対応しきれているのかどうか、その辺を教えていただきたい。この平均というのがどういう意味なのか教えていただきたいのと、希望に対しての充足がどうなのかなというところも教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"８ページの水中運動ですけれども、週１回、１回２時間というような利用のサービスの提供状況です。それから２０ページ、ちょっとすみません、後ほどお答えします。","id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"これは前にも１回お話ししたことがあるんですが、ぜひこれは要望なので、よろしくお願いいたします。この点は、今後の見通しとしていかがか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"いろんな区立施設のプール等、あるいは戸越台の学校のプール等を介護予防事業として活用するなどしながら、リハビリ予防効果に適切なサービスを必要な方になるべく提供できるように検討してまいりたいというふうに考えております。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"というのも、要介護１の方は８割くらいの方になるんでしょうか、要支援になっていきますよね。これも平成１６年のころからすると若干減ってきていますけども、多い方では何人くらい立てているのかということも教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"それから５ページのケアプランの作成数の関係ですけれども、在宅介護支援センター、７５.２％という割合で作成をしているという状況です。今のところ、そういう意味では区の在宅介護支援センターが７割、８割を占めているような状況でございまして。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"要支援になる方で、何人くらいの方が電動ベッドや車いすを使われているのかというふうなことがわかったら教えてほしいと求めました。現在は１人当たりどれぐらい立てていて、大変な実態というのはないのか、そこら辺のところをちょっとお聞かせいただけないか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"そういう点で言いますと、今のところそういうケアプランの作成に困っているというような状況にはないというふうに考えてあります。それから、１人当たり具体的に何件かというのは、ちょっと今数字が手元にございませんので申しわけございません。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして今度はまた在宅でも４月からは予防介護というふうなところでいろいろ矛盾も出てくると思うんですけれども、ぜひ必要な方には必要なサービスをというふうなところでご検討ほしいと求めましたし、ぜひ十分な体制がつくれるようによろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"広域連合のこの範囲というのが２３区なのか、それとも東京都市区町村まで全部入るのか、そこら辺の範囲についてひとつ教えてほしいと求めました。ここの中で、これはちょっと具体的にどれぐらいになるのかということと、どういう形で選んでいくのかというところを教えていただけないか尋ねました。","respondent":"冨岡高齢事業課長","answer":"今その前提の検討委員会というのを立ち上げておりますが、都が２名、これが３名入っております。３番目の広域連合の議員選挙はどういう形で行われるかですが、詳しくはこれから準備委員会で進めてまいります規約に基づいて決めるわけですけれども。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"準備委員会というのはどういう構成になっていくのかということをひとつ教えていただきたいのと、介護保険と同じような形になるんでしょうか。現在保険料を払っていないという方は品川区内では何パーセントぐらいいらっしゃるのかということについても教えてほしいと求めました。","respondent":"冨岡高齢事業課長","answer":"検討会で決めます準備委員会の構成ですけれども、実は今まだ合同検討会で詰めておるところでございまして、今の段階ではお答えできません。最後の７５歳以上の方で払っていない方ですが、ちょっとこの数字は申しわけありません、把握してございません。","id":"exchange-029"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"三上委員","kind":"質問・要望","question":"その他のところで結構なんですけども、今社会的に非常に問題になっているうつ病でしょうか、そういった精神の問題についてもちょっと加えていただければと要望したいと思います。","respondent":"須藤委員長","answer":"そういったこともこの中に取り入れていこうというような、調査研究していこうというようなことでありますので、それも含めてです。よろしくご理解のほど、お願いいたします。","id":"exchange-030"},{"speaker":"三村委員","kind":"質問","question":"私どもの会派としては、少子化対策ということで意見を出させていただいたんですけれども、そういったことで他の会派からのご意見とか、調査項目としてご意見等出なかったのか、また、今回調査項目の項に入らなかった理由について教えていただけますか。","respondent":"須藤委員長","answer":"今回特に少子化云々ということだけでなく、もう少し広い視野で対応しようというような考えで、こういった調査項目にしました。その中の取っかかりで一つでも二つでも対応ができればなというようなことで、こういったようなテーマをチョイスしたわけです。","id":"exchange-031"},{"speaker":"三村委員","kind":"質問","question":"先ほども質問させていただいたんですけれども、他の会派からはそういった少子化対策について、今回の所管事務調査について取り上げるべきという意見は出なかったんですかということだったんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"三村委員","kind":"質問・要望","question":"今特殊合計出生率も１.２５と大変低い状況にある中で、区としてもぜひきちんと検討していただきたいなということで、検討に加えていただくことはできないか尋ねました。","respondent":"須藤委員長","answer":"今お話ししましたように、時間がね、閉会中の時間で、いろんな報告事項が厚生委員会は非常に多岐にわたって種々出てきます。少子化対策のほうにまた議会として考え方の整理、その中で、ご提案を言っていただければいいかなというふうな正副で判断をさせていただきました。","id":"exchange-033"},{"speaker":"三村委員","kind":"提案","question":"私どもの会派としては、当然多岐にわたって重要な項目であるので、特別委員会の設置も提案をさせていただいたんですね。提案のところにつなげていただくためには、特別委員会の設置だとか、そういったところできちんと総合的に議論していく必要があるかと思うんですねとの意見を述べました。","respondent":"須藤委員長","answer":"昨年度次世代育成の話が、これは総務委員会で報告があったんですけども、それが少子化対策の一つの一環であろうというふうに認識しております。少子化対策になると、そのことも子育ての支援の一つになる、少子化対策の一つのお母さん方の考えになってもらえるんじゃないかなと。","id":"exchange-034"},{"speaker":"三村委員","kind":"意見","question":"先進的にやっているところを入れるとか、そういったところで多少なりともぜひなるべく多くそういった調査の対象を、そういった視点も含めて検討してほしいと求めました。","respondent":"須藤委員長","answer":"先ほど来お答えしていますように、いろんな要望があった中に障害者の問題もあるし、それから神経的な精神障害、そういう問題も出てきています。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"先ほど三村委員のほうからもありましたけれども、次世代育成のことについては、去年の厚生委員会の中でもほとんど報告がなかったんですよね。１年間やってどうだったかというふうなことも含めて、ぜひご報告をしていただくようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"西本委員","kind":"確認","question":"確認をちょっとさせてください。ただ、食全体を考えたときには関連するのかなというふうに思ったりしている部分はあるんですが、そこら辺の仕切りはどういうふうにして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問","question":"所管事務調査について、議長に提言という言葉が先ほど出たんですけど、これは委員長会でそのような形で出たんですか、それとも委員長としてという、今まで所管事務調査は提言事項まで持っていっていなかったというのがあったので、その辺はどうかなと思って。","respondent":"須藤委員長","answer":"厚生委員会としては１年間議論しながら、とても１年ではある程度結論、こういう考え方がまとまったよということが出ればいいかなと思っています。","id":"exchange-038"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"三村委員","kind":"質問・要望","question":"先ほども申し述べたとおり、今回調査項目としてぜひ視察の際の項目として、少子化対策ということで、いろいろ先進的な事例ですとか、出生率の上がっている自治体等をぜひ視察対象にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"意見","question":"やはり参考にするべきものはあると思うんですが、５段階が６段階になった、そこら辺もありますよね。予防面という面でも、ちょっと何か参考事例があればと思い、その辺も委員長のほうでご検討をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"一体的な運営をしている、それから地域のそういう福祉施設みたいなもの、開放的にやっているようなところがあったらぜひ勉強させていただきたいなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"三上委員","kind":"質問","question":"せっかくですから厚生委員会で所管になったということで、そういった面で幼保一元、先駆的な事例としてあるようなところについてぜひ調査したいなと。特に、ちょっと伺ってみるところによると、佐賀市あたりというのは、品川区の校長先生であったわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私たちとしても、少子化対策、子育て支援のところにぜひ出生率の対策をとって上がっているという自治体に行って、参考にできたらいいなというふうに思っているんですけれども、具体的なところも申し上げていいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"出生率が１.９７まで上がっていまして、子育てサークルとか、それから中学校３年までの医療費の無料化もしているということなんですね。さまざまそういうＮＨＫや朝日新聞でも取り上げられているというところで、ぜひここに行って視察をしたいなというふうな希望ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"木下委員","kind":"質問","question":"武内議員も一般質問でされていたんですけれども、私もちょっとそういうところに興味があって、視察で見てみたいなというような思いがあります。生活習慣病の予防ですか、できましたらひとつご検討のほう、。","respondent":"須藤委員長","answer":"今お手元に１０月の予定表、議会のほうの予定表を配らせていただいておりますけども、１０月３０日から１１月２日の４日間のうちから選ぶ。その２点が、この前もお話ししましたように、そのあたりの日程的なものをご提示いただければと思いますが。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"意見","question":"日程的には、例えば１０月３１日から１日、２日、３日間ぐらいでというパターンを考えたとき、３１日、１日、２日という形がとれればなと。翌週になると、会派としてちょっとつらい状況が入っているのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"はい、３１日から１日、２日ぐらいという形で考えていただければというのが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"三村委員","kind":"質問・要望","question":"要望として富山、ぜひそこを場所として検討していただきたいなというのだけ、１点だけ。","respondent":"須藤委員長","answer":"我々も理事者にまたこれから聞かなきゃいけませんので、それより先にいい資料がありましたら、書記のほうに出していただければ検討します。ほかになければ、以上をもちまして、本日の予定はすべて終了いたしました。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285470?Template=document&Id=3150#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":42271,"voices":124}},{"id":"h18-20060627-8","meetingId":"h18-cm06","date":"2006年6月27日","dateIso":"2006-06-27","committee":"建設委員会","time":"午後１０時０３分～午後４時１２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件整理しています。","topics":[{"id":"topic-01","title":"の東品川海上公園新設工事（南側：第５期）","agenda":"の東品川海上公園新設工事（南側：第５期）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ここのところとか、こういう水に親しむというか、どこかにそういうようなセッティングがされているところがあるのかどうか。そういうところがあるよということじゃなくて、水に親しめる空間というのは、噴水とかというところだけか尋ねました。","respondent":"松代管理工事課長","answer":"「水とみどりのネットワーク」の中では水辺に親しむと、なるべく水辺の近くにまで近寄ってごらんいただくというようなところまで、今行っております。そこに桟橋をつくるとか、そういう中で、少し触れていただけるようなものを考えていければと思っているところです。","id":"exchange-001"},{"speaker":"井上委員","kind":"意見","question":"構造上、今のお話だと検討していくということが方針として残っているということで、どういう感じで進められていこうとするか。考え方でいいんですけど、もう一度お願いしますとの意見を述べました。","respondent":"松代管理工事課長","answer":"そういったことも含めまして、「新・水とみどりのネットワーク」という構想を今、検討に入ってあります。今の動きを含めまして、我々の今の計画もそこに盛り込みまして、新たな構想として打ち出そうと考えているところです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"どうしても音だったり、仕事帰りに気軽にスポーツができるようなスペースというのが考えられなかったのかなと感じているんです。なかなかそういう気軽さというのがどうしてもそこにはなくて、そういう検討も含めて、計画を少し教えてほしいと求めました。","respondent":"松代管理工事課長","answer":"そういった施設としての整備が望ましいだろうということで、基本的には計画を進めてまいりました。地域の方々の説明会等でのご要望等を少しでも取り入れる形をとったのが、今回、ちょっと設置はできなかったという状況です。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのはこの１点だけなんですけれども、隣にマンションもありますので、この公園の形はすごく魅力的だと思いました。とにかくぜひ生かす形で、ポンプ所の壁もいろいろな使い方もあるでしょうけれども、ぜひそういうところをいろいろご検討いただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"今、この公園が野球場を含めると、５ｈａということですが、これは区民の利用状況をどのように人数的に見込んでいるんか尋ねました。","respondent":"松代管理工事課長","answer":"少なくとも天王洲野球場は土日は大体８０％、９０％の利用率となっていまして、平日でも大体６割ぐらい利用すると承知しています。散歩される方、また土日に当たりましては、近隣等からお見えになるといったご利用も非常に高いというふうに承知しています。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"当然、ここは夜間も開放するんでしょうけれども、ポンプ所の上部にエレベーターをつけている部分も夜間開放するんですか。あれは夜間は開放しないという方針なんか尋ねました。","respondent":"松代管理工事課長","answer":"こちらも一応夜間も、時間を決めて閉鎖をしたいと思っています。今のところ考えていますのは、朝の７時から夜の９時ぐらいまで開放し、詰めてあります。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"あるいは近隣のマンションにしても夜９時、１０時過ぎに区民がそこで遊んでいるというのは、迷惑ですよね。これは有料の形をとるんですか、それとも無料ですか、あるいは今はやりのコインパーキングか尋ねました。","respondent":"松代管理工事課長","answer":"天王洲野球場に今現在５６台ほどの駐車場を管理しておりますが、ここは今、民間委託をしています。双方が使えるようなことで、少しでも利用者にご利用いただけるようなものを考えて、そういう趣旨で管理をしたいと考えているところです。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"すると当然、野球場の利用者も来るということで、減免措置ということも考えているということか尋ねました。","respondent":"松代管理工事課長","answer":"残念ながら減免等は現在もございません。１時間３００円ということで、これは都内一律公共施設、私どもが管理しています駐車場の利用単価をお示ししてご利用いただいているところです。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"その辺をちょっと教えていただきたいのと、有料ですから、当然ニーズがあって使うわけですから。今すぐにどうのこうのと、実態的にはそんな状態になっているということで、考えてほしいと求めました。","respondent":"松代管理工事課長","answer":"地域からもそういった要望が出ましたので、そういったことを取り入れながら、当時の駐車場の活用というものをいろいろと検討してまいりました。","id":"exchange-009"},{"speaker":"藤田委員","kind":"提案","question":"１つ提案なんですが、そうした何かコンセプトというのを、視点を当てていくというのは大事じゃないかと思うんです。そうした学べるというような視点で、どのように今後取り組んでいかれるのか、お伺いしたいと思いますとの意見を述べました。","respondent":"松代管理工事課長","answer":"最近、これも今後の検討になっていくと思いますけれども、そういったことでの関連性を持たれるかといったことも少し考えていきたいと思っています。そういったものを引き続き、今後もお見えになる方に喜んでいただけるように努めていきたいと考えています。","id":"exchange-010"},{"speaker":"藤田委員","kind":"質問・要望","question":"例えば表示板に今月はどういうお話があるんだろうと、楽しみに来れるような工夫といいますか、ぜひお願いしたいと思います。何かそういう工夫もぜひお願いしたいと要望してまいります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"大西委員","kind":"質問","question":"南側に２０台というところで、果たしてこの２０台が必要とされるかどうかということと、中に自転車をとめられないという問題もいずれ発生しようかと。駐輪場の部分に設けることによって、中途半端にならないかと思うんですが、どうか尋ねました。","respondent":"松代管理工事課長","answer":"そういったことでいろいろと私ども検討しまして、平成１８年度、既に取り組んでいるところです。台数がそれで十分かどうかは別にしまして、南側と西側と、また一方で違う場所にもそういった駐輪場を今回設けたものです。","id":"exchange-012"},{"speaker":"大西委員","kind":"質問・要望","question":"理解できました。１点だけ、あちらからの入場に際しても、バリアフリーとしての配慮をいただけることを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"井上委員","kind":"確認","question":"今のバリアフリーという視点でお伺いしますけれども、その辺が必要だと思うので、これからどうされるのかということが１点。駐車場があるかないかの確認ではなく、ここに入れるような障害者の駐車場にしてほしいと思いますけれども、そこのところは検討されているのかどうか。","respondent":"松代管理工事課長、岩田まちづくり事業部次長","answer":"しかし、一定の駐車場をつくる際には身障者の方への対応ということでスペースを設けてあります。１つには天王洲野球場のところに管理事務所がありまして、相談という形をとらせていただければ… 道路においても点字ブロックというのは、必要最小限の場所に設置することになっておりまして、連続設置というのがなかなかできない。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"それからあと、障害者の駐車場なんですが、これからつくるのであれば、きちんとスペースを確保した駐車場にしてほしいと思うんです。本当に大きな５０人乗りのバスの団体駐車場をつくってほしいと言っているわけではなくて、１台分を１台半にしてつくるとか、いかがか尋ねました。","respondent":"松代管理工事課長","answer":"駐車場の身障者への対応ですけれども、基本的には一定の基準があります。かつ身障者対応のところは少し広めになっておりますので、乗ったりするスペースがありますので、そういったものをご利用いただければと考えています。","id":"exchange-015"},{"speaker":"井上委員","kind":"意見","question":"ここのケースではどうなのかというところを、そこに次の車がとまっていたら、おろすスペースがない。おろして、乗せて、基準どおりつくっているから問題ないでしょうという体制ではないところで取り組んでいただくことをぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]},{"id":"topic-02","title":"のしながわ水族館「アザラシ館」オープンと入館料の改定","agenda":"のしながわ水族館「アザラシ館」オープンと入館料の改定","exchanges":[{"speaker":"井上委員","kind":"質問","question":"そういうものとか、どういうふうにリピーターを増やすのかということについての議論の中に、そういうものを導入しようかという検討はないんか尋ねました。","respondent":"藤田道路公園課長","answer":"こうしたことから、私どものしながわ水族館はリピーターとして来られる方が非常に多いのかなと考えています。こうしたことが非常に人気がありまして、そういったことで何回か来て、そういった体験を楽しんでおられる方もあります。","id":"exchange-017"},{"speaker":"井上委員","kind":"提案","question":"じゃ、そういう回数券制度みたいなものも検討していったらいかがかなという提案、私たちもいろいろな方から声を聞いて届けたいと思うんです。平日に利用がないんじゃないかと、私は思うんですが、その実態はどうか尋ねました。","respondent":"藤田道路公園課長","answer":"水族館の送迎バスの関係ですけれども、平成１７年度までは区の方が委託発注をして、バスの運行事業者の方で実施をしていたという形になってあります。","id":"exchange-018"},{"speaker":"井上委員","kind":"意見","question":"じゃ、平成１８年度から直営になったということで、今度バスを買い替えるときの費用負担の問題とか、あとサンシャインシティとの契約で、バスのことはすべて契約の中に含まれてしまうのか、その費用の負担の部分について、区との関係がどうなのかとの意見を述べました。","respondent":"藤田道路公園課長","answer":"今回、バスについては今、水族館で検討していますのは、バスの購入ということではなくて、リースという形でのバスの手当をするということで、トータル的な費用については、水族館の運営費の中から支出をしていくという考えです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"意見","question":"６億５,０００万円かけて「アザラシ館」をオープンなさって、今、現状どういう経営の状況なのか。今回の一般料金が２００円上げて、区民割引は限定から通年の変更ですけれども、料金変更の理由をもう少し詳しくご説明いただけますかとの意見を述べました。","respondent":"藤田道路公園課長","answer":"１つはお客様に対するサービスが、「アザラシ館」ができることで、満足度がアップするというようなことでのサービスアップが１つあるかなです。そうしたことを考えながら、周辺の水族館の動向も踏まえ、料金の設定を今回変更するというふうに考えたものです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"本来、区民割引はある意味通年ですから、広がるわけですね。今の説明ですと、まだなぜここに至って料金の改定なのかというところが見えてこないので、もう少しご説明ほしいと求めました。","respondent":"藤田道路公園課長","answer":"これはちょっと古いデータなんですけれども、大体１割にも満たないぐらいというのがデータとしています。区民の皆様にはこれまで以上にもう少し来ていただきたいと思う部分と、料金の設定の中で与える影響はそんなに大きくはないと考えているものです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、何でこの改定なのか、そこがよくわからないんですね。そこをちょっと伺いたいんですけれども。","respondent":"藤田道路公園課長","answer":"近隣の動向と合わせて考えたときに、おおむね近郊の水族館施設は１,８００円ぐらいから、２,０００円台の料金設定になってあります。考えたときに、私どものしながわ水族館が安いんだという料金設定にするべきだと考えてございまして、今回の料金改定の値段を設定したものです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"意見","question":"周辺の状況を見て、ちょっと安いから２００円上げるという発想も、どうも私には理解しがたいと思っています。お考えを聞かせてくださいとの意見を述べました。","respondent":"岩田まちづくり事業部次長","answer":"６０万人ちょっと切ると、いわゆる見かけ上の黒字が赤字に転換してまいりますので、この段階で料金の改定を図らざるを得ない。そのときに料金を上げないと、これはお客さんから苦情が来ますので、こういう機会に品川区の場合は料金改定をしてきたです。","id":"exchange-023"}]},{"id":"topic-03","title":"の「目黒川右岸低地部排水施設整備工事その２」の着手","agenda":"の「目黒川右岸低地部排水施設整備工事その２」の着手","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この近隣の方が、台風なりが来ると心配な中で、近隣の説明会やそういう状況は今までどういう感じだったのか、経過を教えていただけますか。","respondent":"原田下水道河川課長","answer":"その後、平成１８年３月に工事契約をした後、施工業者が決まりましたから、施工計画を立てまして、今年の４月に工事説明会を実施したということです。多くの方を集めての工事説明会はその２回ということで、あとは個別に町会長等にもご説明しながら、周知を図っているところです。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"説明会ではどんな声が寄せられたのかなと、そこだけ説明を求めました。","respondent":"原田下水道河川課長","answer":"最初の事業説明会の中では、非常に大きな雨が降っていますから、もっと大きな施設の方がいいんじゃないかというご意見もございました。それから工事説明会での質疑につきましては、そういうときには工事をやめてもらえるかといったことで、ご質問がありました。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問","question":"これは全体の中で、当然大きなものですから、貯留能力というのか、貯留管としての役割ということなんですけど、何トンぐらいたまるものになっているんか尋ねました。","respondent":"原田下水道河川課長","answer":"これは内径２,６００ミリの円形管で、延長分を掛ければ出てくるんですけど、ちょっとそこまでは数字は記憶していないです。","id":"exchange-026"},{"speaker":"松澤委員","kind":"質問","question":"当然何トン貯留できるのかと考えていますけれども、ここは貯留能力というものがもともと計算されていないということなんですか。それとも今回、ここの委員会に来る資料としては、調べてこなかったということなのか。","respondent":"原田下水道河川課長","answer":"そういうところで貯留能力、貯留量については、いつもはあまり意識しないところです。","id":"exchange-027"},{"speaker":"松澤委員","kind":"質問","question":"当然、地上の方が高いですから、それは大丈夫なんですね。理論上はそうだけど、実際には水が上がらなかった、そんなことは絶対ないんか尋ねました。","respondent":"原田下水道河川課長","answer":"水そのものはどんどん降ればたまっていきますから、たまっていったら、あとは空間のある方向に流れるというので、既設の鮫洲幹線の方が位置的には低くなっていますから、低いところに流れるという意味で、大丈夫と考えております。","id":"exchange-028"}]},{"id":"topic-04","title":"の中原街道の沿道地区計画","agenda":"の中原街道の沿道地区計画","exchanges":[{"speaker":"藤田委員","kind":"質問","question":"この対象になる基礎調査というんですか、本当にそれぐらいしか、私はないんじゃないかなと思うんです。その辺ちょっとお伺いしたい。","respondent":"伊勢住環境整備担当課長","answer":"説明が足りなくて、申しわけございません。それから３月２３日の木曜日、基礎調査の内容まではあまり詳しくご説明できなかったんですけど、全般的な説明をしたところです。","id":"exchange-029"},{"speaker":"藤田委員","kind":"質問","question":"それは大体何人ぐらい対象になると考えていらっしゃるんですか。それしか私はわかりませんけれども、件数として、今、ほとんどがマンションですから。","respondent":"伊勢住環境整備担当課長","answer":"コンサルタントに委託して調査したわけですけれども、５メートル以下の建物についてはほとんどなかったというところで聞いてあります。ほとんどないと。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"間口率を１０分の７が最低と、音を防ぐようですが、この辺のデータというのはどんなデータがあるんでしょうか。あえて、５メートル以上としなければいけないというのを、説明を求めました。","respondent":"伊勢住環境整備担当課長","answer":"その中で５メートルという数字が出てくるわけなんですが、そういう実験データに基づきまして５メートル、それから間口率１０分７を定めています。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問・要望","question":"騒音の低減とあわせて、幹線道路沿道にふさわしい土地利用の誘導を図るということなんですけれども、このところがどういう意味なのか。もうちょっとわかりやすく教えていただきたい。","respondent":"伊勢住環境整備担当課長","answer":"段階があるわけですけれども、これぐらいのところまではいいですよとかどうだとか、この辺は説明会等でご説明したいと思います。これはある一定規模以上になりますと、緑化をしてくださいというようなルールを定めてはどうかということをご案内しております。","id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問・要望","question":"こういうところであまり高層化させないでほしいという声もかなり多くありますけれども、そういう高さを高層化しないでほしいという要望は実際上、これには何かご回答されたんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"今、検討案の段階でございまして、これから７月に説明会を開きまして、他区の情報等を皆さんにお知らせしていく中で、そういうご意見があれば、それを取り入れるかどうか判断したいと考えています。","id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問・要望","question":"隣との間がぐっと狭くなるだろうということになりますけれども、一般的に環境がこれによって、通風がどうなるのか。どういうふうに盛り込まれていくのか、どういうことが心配されているのか、そのことについてご説明ほしいと求めました。","respondent":"伊勢住環境整備担当課長","answer":"予定にも書いてありますように、かなり厳しい規制とかそういうことになりますと、かなりの回数を重ねていかないと難しいのかなと感じております。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"地区計画ですから、どうも現実に、そういう影響が出てくるわけです。ところが、その影響はやっぱりほかのところが広範に受けるというわけですから、非常に無責任な感じがしてしようがないんですよね。","respondent":"伊勢住環境整備担当課長","answer":"なかなかこちらを立てると、こちらに影響が出るというような、二律背反のころもあります。ただ、この辺については、どのようなご意見が出てくるのか、その経過を見ながら検討していきたいと思います。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"これはそういう流れの地区計画ですよねということも確認の答弁をいただきたいことと、どういうことになるのでしょうかという、そこら辺をちょっと確認させていただきたい。","respondent":"伊勢住環境整備担当課長、岩田まちづくり事業部次長","answer":"今ご紹介したのは４つですけれども、そういうものも紹介しながら盛り込めるかどうか、これから検討していきたいと思います。すみません。いろいろな建築制限もやろうということが高まってくれば、そのときに地区計画の変更等で規制を変えていけばよろしいかと思います。… 全体としましては１階建てが２％、９８％が２階建て以上になっていますので、それらは５メートルを超えるということはほとんどないと思います。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問","question":"地区計画の３番のところで行くと、例えば３番のケースで言うと、地区計画ができました。ピロティに壁を設けていないところにはやってくださいねということになるのか、建て替えのときにそうなのかということの関係はどういうことか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"建てるとき、修繕は入っていないと、東京都のパンフレットでは読めます。要するに、これから建てるときに助成ができるです。","id":"exchange-037"}]},{"id":"topic-05","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"状況を説明していただきたいというような要望をしたときに、そこに載せていただきたいと思うんですけれども、そのことについて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"宮崎委員","kind":"提案","question":"正副で、設置してやるというのが前提なんですけれども、うちの方も大きな開発のところは、議運のときに提案した際に、これは建設委員会だという意識を受けておりますので、ぜひそういうことも取り計らってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"井上委員","kind":"提案","question":"地域の中で平屋あるいは２階建てのようなまちづくりの中に、関心があると思われておりましたので、協議をぜひ入れてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"伊藤委員長","kind":"質問・要望","question":"ほかにご指摘、それからご要望等ありますでしょうか。場合によってはできるかどうかは別としても、まちづくりの専門家の方に意見を求めていくとか、そういうことで進めていこうと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"そうでない場合に、そのことについて、委員会としてぜひ資料請求をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"井上委員","kind":"意見","question":"どういうふうに出していただけるか、それをどう利用するかというのはメンバーそれぞれかもしれませんので、本来は委員会として資料請求ということができれば一番いいかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"宮崎委員","kind":"質問・要望","question":"どういう中身が報告されたのかということをつかんでいないか、お知らせいただきたいということだったんですけど、実際にとまらないと。それは以前からそういう計画であったんですけれども、あそこの地域住民の方は駅の高架化というのは、長い間の要望なんですね。","respondent":"阿部都市計画課長","answer":"ただ東急としては、その場でこういう内容で答えたというふうに聞いています。あるいは東急としても計画的に事業を進めているという段階ですので、そういうのは、当面はかなり難しいという話をしたというふうに聞いております。","id":"exchange-044"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、ぜひ住民の方々の要望なんかもつかみながら、必要な対応をしてほしいと求めました。今日はこれで終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"藤田委員","kind":"質問","question":"いかがでしょうか。３０日だと大変だと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"松澤委員","kind":"質問","question":"そのことから考えると、実際に視察ですから、どういうところでどんなものを視察したいかで、違うと思うんです。委員会の中で自由に決められるわけですから、何もこの時期に行くのではなくて、早い時期に行ってもいいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"藤田委員","kind":"意見","question":"ただし、時期がちょっと制限されます。例えばの話との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"中塚委員","kind":"意見","question":"まだ今の時点で、ここが今、みんなで研究すべきテーマなのか、まだ私の中で見え切れていない部分があるので。それは十分に１０月までに限らずに、ここというのがまだ私の中では、というのが率直なところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"さっき若干、所管事務調査のところで議論、要望が出て、その延長にあるものがあれば非常にいいのかなと。それに必要な時期を調整した上で、相手の関係もあるでしょうから、そういうのがいいのかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"大西委員","kind":"意見","question":"ちなみに、私もどうしてそんなに旭山動物園が人気なのか、利用料なんか大人が５８０円です。旭山動物園というのは、ちょうどいい形にリンクするのではないかなと、ふと思うところがございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"中塚委員","kind":"確認","question":"もちろん幅広いですから、区民等の関心の中で、そういうふうに進めていった方がいいのではないかと。もちろん建設の確認業務、先ほど井上委員から話があった高さのこと一つとっても、まだまだ整理し切れていないと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"松澤委員","kind":"意見","question":"区民委員会のときかな、うだつも見たいということで、うだつに電車を乗り継いで、電車の中でお弁当を食べながら行ったんです。昔の藍の問屋のまちがあって、それがこうなっているわけで、防火壁でとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"松澤委員","kind":"質問","question":"旭山動物園が休みじゃ、しようがないじゃない。いつまで休みなんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/965541?Template=document&Id=3854#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":43650,"voices":159}},{"id":"h18-20060627-9","meetingId":"h18-cm06","date":"2006年6月27日","dateIso":"2006-06-27","committee":"文教委員会","time":"午前１０時０３分～午前１１時３８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"原副委員長","kind":"質問","question":"平成１３年以降ずっと、行政視察一覧表からいくと平成１１年以降の話もそうなんですが、その辺の話も一つの材料になるのかなと。そんなところはいかがでしょうかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"沢田委員","kind":"意見","question":"そこでよい教育実践をやっていますので、できればそこに行きたいと思っています。私は二度ほど行ってきたんですが、実際の授業の現場はなかなか見られなかったので、できれば見たいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"築舘委員","kind":"意見","question":"平成１７年度は北海道の三笠市に行っているので、もしできれば行ってみたいなと、今思っています。それは単なる希望で、皆さんのとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"品川区のすまいるスクールのあり方というのは、学校の延長みたいな形になっているよね。何かに取り組んでいるところがあったらと思っているんですけれども、どこというところがないから、抽象的なんだけれどもとの意見を述べました。","respondent":"中島委員長","answer":"今の林委員のように、こういう内容で、というものもございましたら、ご提案いただければ、それでこちらで探すということもできるかと思います。そのとおりいくかどうかはわかりませんけれども。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"平成１６年度に中島委員長で、金沢で５番目の、教育プラザ富樫というところは非常に勉強になったんです。同じところに行くわけにいかないから、何か同じような感じのものが、ほかでも取り組んでいるところがあればとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"その原因と、区としてはそのことをどう見るのかということも合わせて、お考えを示していただければありがたいと思います。その前にきょうは、時間的にはいつぐらいまで余裕があるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"そうですか、じゃああまりないんですね。できるところまでで結構ですので、特に、どういうことでそこに至ったのかという経過を中心に、とりあえず言ってもらえればありがたいんですが。","respondent":"古里学務課長","answer":"３１日の説明会ですが、八潮地区小中一貫校を平成２０年４月に設置をするということをご報告、説明を申し上げました。なお、説明会以降、現在でも、八潮の５校では、ＰＴＡによる今後の教育環境の問題についての論議を進めているということを聞いてあります。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"私は、一貫校に集約してくださいということで一致しているのか、そこはちょっとそんな簡単なものではないのではないかという気がするんです。３０日と３１日にやったＰＴＡの説明会の参加者と、そのときの議事録みたいなものは何か取ってあるんか尋ねました。","respondent":"古里学務課長","answer":"それから、地元関係者による説明会出席者は２７名です。こうした説明会につきましては、２７日というふうな形で、それぞれ各学校でこの件に関して論議をいただいていると聞いております。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問・要望","question":"現地の状況もわからないものですから、私が聞いたところによると、諸手を挙げて賛成したという人はそんなにいなかったと。きょうはちょっと時間がないところなので、一応一たんこれで打ち切って、また別の機会に質問させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/670410?Template=document&Id=4576#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":8485,"voices":33}},{"id":"h18-20060627-5","meetingId":"h18-cm06","date":"2006年6月27日","dateIso":"2006-06-27","committee":"総務委員会","time":"午前１０時０２分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"平成１８年請願第８号 国際人道法に則り、国民保護協議会に自衛隊員を採用しない等の請願","agenda":"平成１８年請願第８号 国際人道法に則り、国民保護協議会に自衛隊員を採用しない等の請願","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"その後の３番目と４番目、５番目、現状どうなっているのかをまずお聞かせを願いたいというのと。お聞きをしたんですけれども、１０年前ぐらいの数字だったものですから、現状での昼間人口についても教えてほしいと求めました。","respondent":"桑村危機管理室長","answer":"つくる上では検討する必要があるだろうと思ってあります。４７万８,０００人です。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"この辺も１つ教えていただきたい。その辺を教えていただきたいのと、それとも犯罪なのか、この辺もちょっと教えてほしいと求めました。","respondent":"桑村危機管理室長","answer":"１つは、市町村の場合は、いわゆる自衛隊に所属している者の知識経験を得る必要があるというような考え方があります。それからもう一つは、１つは都道府県知事が、いわゆるそういう措置を円滑に実施するために自衛隊を要請することができることになっております。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"これは１つの区民がどうやって命を守っていくかという話ですから、これは決して別物ではないんではないかなというふうに思うんです。戦争かどうかではなくて、それだと災害対策のほうが自治体として判断ができるわけですから、ちょっとその辺も教えてほしいと求めました。","respondent":"桑村危機管理室長","answer":"委員ご指摘のような考え方が多数を占めれば、逆にそうではなくて、それは実際上の会議体の中で判断というふうに思ってあります。区を中心に区の職員が動くというのはこれは当たり前の考え方ですので、一定の各必要な部署が集まって対応をしていくということなんだろうと思います。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問・要望","question":"先ほど自衛隊が実際の避難の中でどういう役割を持つのかというところで、もう一度その辺を教えていただきたいんですけれども、自衛隊が実際の避難の中で果たす役割のところをお伝えいただけますか尋ねました。","respondent":"桑村危機管理室長","answer":"国民の保護のための措置を円滑に実施するために、いわゆる救援ということもあるでしょうし、復旧ということもあろうかと思います。そういう意味では、どうしても自衛隊の力をかりなければ何らかの対応はできないというふうに判断すれば、これは要請するわけですから。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"先ほど言いましたけれども、軍事作戦は後回しになるということはまず考えられないわけですよね。私たちの国自身がわずか６０年前に一般国民と軍隊との関係で悲惨な状況を沖縄で味わってきたわけですから、この辺での見解はちょっとどうか尋ねました。","respondent":"桑村危機管理室長","answer":"私どもの区がその上で自衛隊に何の要請をするかということがない状態で、なかなかお答えするのは難しいお話なんだろうと思います。そういう必要があれば、その中で必要があれば、こういう行為がとれるということなんだというふうに思います。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"仮定の論議だから答えようがないというのは、どう考えてもちょっと納得ができないんですね。何というんでしょう、これは仮定の論議だとすると計画そのものが必要ないのではないのかというふうに思うんですけれども、この辺はどうか尋ねました。","respondent":"桑村危機管理室長","answer":"それで、それをこれから国民保護協議会の中で検討していこうです。その意味では一定の考え方、それをどんなときにどういう想定をするかというのはこれから計画の中で検討するべきことでありますでしょうし。","id":"exchange-006"},{"speaker":"山村委員","kind":"質問・要望","question":"何というんですか、そこら辺はどういうに思っているのか、教えてほしいと求めました。","respondent":"桑村危機管理室長","answer":"いわゆるこういった計画をつくるに当たって自衛隊の方がどういうことを考えられているかという意味での委員の構成ですので、むしろその意味でいえば、普通の協議会委員の形にはなると思います。","id":"exchange-007"},{"speaker":"山村委員","kind":"意見","question":"必ず公開ということだと思うんですけれども、逆にこれは公開すると、どういう経路で区民が逃げるのかわかったほうがテロはやりやすいと僕は思います。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、協議会を開催する中で、今回、自衛隊の方たちが保護協議会の構成員に入られておりますけど、そのときに何か自衛隊が入ることに対して協議会から何か意見が出たのかと思うんですけれども、それはまだ全然話はまるっきり出ていない状態か尋ねました。","respondent":"桑村危機管理室長","answer":"１つは、その分を落とすという考え方というものですが、基本的には必要な委員構成なんだろうということはここで予定されているんだろうと思うんです。","id":"exchange-009"},{"speaker":"須貝委員","kind":"確認","question":"もう一つお聞きしたいんですけれども、というか、そこで言えるということですよね。そこら辺、ちょっと確認だけお願いします。","respondent":"桑村危機管理室長","answer":"その意味で、有識者にどういう方たちを選ぶかということで、いわゆる自主防災組織の長というようなものがある。それぞれの町会長の地域がやるわけですけれども、その中で区民の意見が、そこで得られるんだろうというふうに思ってあります。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、請願等出ておりますけれども、協議会の中で活発な議論をされて、区民にとってよりよいものになるように、ぜひいろんな関係機関と協力していいものをつくり上げてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"塚本委員","kind":"意見","question":"予定では５月ということなんですね。その経緯を、それからこのスケジュール、この表でいいのかどうかとの意見を述べました。","respondent":"桑村危機管理室長","answer":"それから５月に予定したものが７月５日を予定しております。それから、２月というのはなかなか難しいかなと思いますが、３月ぐらいになるかと思いますけれども、策定する予定というものです。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"これは、この案というのは国がまとめるひな形というのがまずあるんだろうと思いますけれども、これは公表されているものなのか。それぞれいろんな要素があるわけですけれども、どの程度そういうものを勘案するという状況や考え方になっているのか、それを説明するよう求めました。","respondent":"桑村危機管理室長","answer":"１つ、区市町村の国民保護協議会の考え方ですが、これは都道府県の国民保護計画に基づくというのが当然入ってあります。その意味で、あるいは防災上に弱い地域があるといったものについてどういう検討をしていくかというようなことがあろうかと思います。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"ガイドラインをつくってこうしてください、これで、かくかくしかじかの権力のところでこうしてほしいよというふうにやるのか。どういう役割を協議会というのは担うのかということをお聞きしたいと思います。","respondent":"桑村危機管理室長","answer":"そういう意味では実施隊ではございません。その意味では、どういう役割をお互いに突きつけ合わせるかというのは保護協議会を用い、また検討していくことになろうかと思ってあります。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"そうしますと、協議会のメンバーに自衛隊が入っているということは、この専門的な知識をその協議会の場で生かしてください、現場に出て何かあったときに直ちにその人が誘導するとか、そういうことを想定しているということではないということか尋ねました。","respondent":"桑村危機管理室長","answer":"そのとおりです。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"第１回目の協議会を招集をする際に、協議会を原則公開をするという文言というのは、これから付け加えていけるんですか。その辺、ちょっとお聞かせ願えますか。","respondent":"桑村危機管理室長","answer":"７月５日のいわゆる国民保護協議会の中で、いわゆる会議の公開等について議論をさせていただいて、その中で決めさせていただきたいと思うものです。その意味で、前に何らかの公開をするとかいうような規則をつくるような考え方は持ってございません。","id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"１回１回について、１回１回かどうかは別ですけれども、案の段階で議会へ報告をするということは可能なのかどうか。その辺をちょっと説明を求めました。","respondent":"桑村危機管理室長","answer":"原案をつくった段階で本会議等にかけさせていただいてご意見を伺うというつもりでおりますし、区民への基本的な公表もさせていただきたいというふうに思ってありますので、そういう意味では原案の段階でご意見を伺うということを考えているところです。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"審議を伺っておりまして、指導的役割を担うということではないんだと、委員会に入ってプロの意見を聞くということだと。ですから、陸上自衛隊だけでいいのかという不安が今出てまいりましたので、その辺についてはいかがか尋ねました。","respondent":"桑村危機管理室長","answer":"私どもの防災会議自体もそういう考え方ですので、それに合わさせていただいているものです。そういったところについてはまた違う考え方はあろうかと思いますけれども、２３区ではそういう考え方でいきたいというふうに思ってあります。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問・要望","question":"陸上だけで大丈夫だというのは、あまりにも危機感がないんじゃないですか。せっかくですから、会長が区長なんですから、３つの自衛隊にぜひ参加していただきたいと思うんですけれども。","respondent":"桑村危機管理室長","answer":"都道府県の段階ではいわゆる３自衛隊が入っているわけですし、また実際上、私どもの防災会議とまた違う構成にならざるを得ないと思うものもあります。１つの避難誘導あるいは救援といった活動についてのご意見を伺うという、この委員構成にさせていただきたいと思ってあります。","id":"exchange-019"},{"speaker":"塚本委員","kind":"意見","question":"問題の背景はそれなりに承知しておるつもりです。結論ですけれども、本日結論を出すべきでありますし、私どもは不採択が適当であるというふうに考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"山路委員","kind":"意見","question":"私のほうは、国民保護協議会条例を品川区も成立されたわけですので、その点と、この協議会は７月５日からスタートする、この中に含まれている、それからスタートするのではないかと思いますので、不採択でとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"国際的に信頼をされない国になってきているのではないかというふうに思っています。国民保護法に基づいて今行われている計画全体を凍結をし、見直すということが必要だというふうに思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"山村委員","kind":"質問・要望","question":"そういうことの話を特にこういう協議会で実際はどうなのか、一番区民が安全な方法で避難できる方策を探してほしいと求めました。私自身は、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"須貝委員","kind":"意見","question":"私はそのような意見を述べて、本日結論を出していきたいと考えています。私の意見としては不採択ということでお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-02","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"１つだけ教えてもらいたいんですけれども、これは小規模多機能型ということなんですけれども、これは予定価格に対して補助金というのがどの程度の割合でどういうふうに出てくるのか、ちょっと教えていただけますか。","respondent":"新美企画部長","answer":"その３件とも今度申請されます地域・介護福祉空間整備交付金、従来の補助金が交付金化されますので、そちらの交付金対象になっております。","id":"exchange-025"},{"speaker":"山村委員","kind":"質問","question":"３ページにある関連別途工事、給排水と電気設備工事、これも両方とも今回の場合は山田建設ということなのかどうか。別なんか尋ねました。","respondent":"中島経理課長、日下部企画財政課長","answer":"機械設備につきましては、太洋テクニカ株式会社というところで、これは契約金は３,２０２万５,０００円となっております。それと、こちらの業者が東陽電気工事株式会社となってございまして… 国の補助金の関係ですけれども、新しく申請されました交付金がございまして、それで６,０００万円ほど見込んでいるところです。申しわけございません。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"は個別でやりますのでちょっと教えていただきたいんですが、支店が品川区にあったりするわけですから、区内業者と考えるんか尋ねました。","respondent":"中島経理課長","answer":"今回の入札の参加資格ということでは、区内業者で共同格付ＡからＣということになってあります。そういった意味では、支店等で、要するに品川区の中にきちっと事務所を構えているという会社であれば、対象になります。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"それで、そこで１つ疑問に思ったんですが、区内業者を使ってほしいという気持ちは私にもあるんですね。入らないと公の仕事というのはゼロなわけですから、その辺はどうなっているのか、どういうふうにしていくのか。","respondent":"中島経理課長","answer":"そういった意味では、地道にやって実績を上げていらっしゃれば、そういった意味では対象になってくるというふうに考えてあります。あるいは１０億、２０億のものもありますので、品川区内のさまざまな業者が参加してくるようなシステムになってあります。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、そこは要望なんですけれども、必ずみずほ銀行ですよね。業種を細かく分けて、いろんな会社が入れるようにしていただければ幸いなんですけれども、それは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"山村委員","kind":"質問","question":"私も質問になっちゃって申しわけないんですけれども、これとまた違う。そういうのは監視されているのかどうかというのは、もしやられているのだったらやっている、やっていないならやっていないで説明を求めました。","respondent":"宍戸施設担当課長","answer":"下請け関係についてもリスト化して、どういうふうな契約を取り結んでいるかということを台帳にして現場に備えておく必要があります。そういうふうな契約の中で仕事が２次下請け、３次下請けまで含めてやられているかというのを監視するということはできる仕組みになってあります。","id":"exchange-030"},{"speaker":"山村委員","kind":"質問・要望","question":"上の会社からお金をいただけなくてつぶれた会社というのが実際にあったものですから、指導できるというか、何かしらのをしていないと。要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"私も関連して質問をちょっとさせていただきたいと思うんですけれども、３次下請けに流れていったときに、埼玉の業者かもしれない。そういう方たちが勤めている企業にお金を出すというのが基本のような気がするんですけれども、そこら辺のちょっと考え方を説明するよう求めました。","respondent":"中島経理課長","answer":"そういった意味で中小企業の育成というのが品川区としての大きな役割の１つということでございまして、区内業者をまず第一に考えてあります。そこまでの干渉は自治体として難しいのかなと考えてございまして、区内に実態のある会社等を対象とした姿勢というふうに考えてあります。","id":"exchange-032"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとこれは最後に１つ質問なんですけれども、３次下請けがもう完全に品川区外であったとしても、その育成のためということですよね。だから品川区にそのお金が還元しない、区民に還元するとか、そういう意味合いではないというようなことで、よろしいか尋ねました。","respondent":"本間総務部長","answer":"契約を結ぶわけですから、区としても監視ないしは口を出す場面も限界があるということは、ひとつご理解をいただきたいと思います。中小零細企業、自治体を構成する企業にそういうような配慮をしながら仕事を進めていくということでご理解のほど、よろしくお願いいたします。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"逆に効率のいい３階とかそういうふうにして、ここはやはり建ぺい率また高さ制限等々で２階で鉄筋でという形で持っていかれたんでしょうか。それだけ説明を求めました。","respondent":"中島経理課長","answer":"後段の用途の関係だけ申し上げますと、こちらの地域は第一種低層住宅専用地域ということでありまして容積率１００％、建ぺい率５０％ということですので、そんな大きな建物は建てられないということです。","id":"exchange-034"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"山村委員","kind":"質問","question":"どう法律的にあれなのかと、やはり何か今後は考えていかないと、どうしてもいけないんじゃないかと考えています。選挙を盛り上げるように手助けというんですか、そういうことをやっていくべきだと思うので、出させていただきました。","respondent":"石田委員長","answer":"山村委員からもいろいろ連携の話がありましたが、根本的には、このものは区議会議員そのものの信用度の問題だと思います。これも１回どこかでやっぱり調査をするべきかなと考えていますので、柔軟にやっていきたいなと考えていますが、そんな感じでいいかなと。","id":"exchange-035"},{"speaker":"須貝委員","kind":"意見","question":"今委員長がおっしゃったとおり、やはり各議員一人ひとりの意識、そして区民にどう伝えるかということにかかっていると思うんですね。どういうふうに啓発事業を進めるということじゃなくて、調査事項に入れなくていいんじゃないかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"須貝委員","kind":"質問","question":"もう１点いいですか。先ほど入札制度について委員長のご見解もあったんですけれども、最初九十数％の価格が入札率が７０％、８０％というふうに下がってきている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"山村委員","kind":"意見","question":"それを１回見てすごくおもしろかったので、そういうのは総務になるかどうかわからないんですけれども、それを見てみたいなと考えています。あやふやな話で申しわけないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"山路委員","kind":"意見","question":"平和事業、平成１４年度に広島に、この総務委員会で行った状況があるんですけれども。行ってもっともっと深く平和に対する認識を新たにしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"須貝委員","kind":"意見","question":"今回入札制度改革の成果ということで、長野県で入札制度改革の成果ということが出ております。さらにいろいろな中小企業に対してもきめ細かい入札制度を構築したようなんですけれども、ぜひそこを見たいなと思っているところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816536?Template=document&Id=1724#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":33405,"voices":108}},{"id":"h18-20060628-11","meetingId":"h18-cm06","date":"2006年6月28日","dateIso":"2006-06-28","committee":"自治制度特別委員会","time":"午前１０時０２分～午前１１時３５分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"全体的な話を伺いましたけれども、抜けているのがありますよね。いや、そういうプラント更新なんかについては、どういうふうにとらえていると聞いているのか尋ねました。","respondent":"中山資源循環推進課長","answer":"具体的内容は、一般廃棄物処理基本計画であるというふうになっておりまして、ここに建て替えの計画が入ってきておるんです。委員のご指摘があった平成２２年度以降の、更新の計画が含まれておりまして、それについてはここの先ほどの財政フレームの中に入れ込まれております。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"（５）で契約方法の見直し、これが入ると入札価格が下がるという意味なんですか、これ。（５）、真ん中のIIの行財政システムの改革の中の３番の（５）で、低入札価格調査制度の導入、これはどういう入札制度なんか尋ねました。","respondent":"中山資源循環推進課長","answer":"正直、ここの部分についての説明は私も存じあげておりません。従来のいろいろなプラントメーカーによる説明等を入札の中でやっておるんですが、その流れだというふうに理解をしております。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"ずっとこれ、日本鋼管からいろいろな形、ガスまで含めたんだけれども、あそこの会社は２３区にかかわっていないですか。毎年大規模修理をする、どのぐらいのお金がかけられていて、何カ所ずつやっていくのかという資料は一組から出てきますか。","respondent":"中山資源循環推進課長、岩崎環境清掃事業部長","answer":"ちょっと私、実は２３区の中にも相当のメーカー数がここに入ってありますから、過去に当たっているメーカーがあることはございました。今回のところの情報についてはよく存じあげておりません。一組も地方公共団体ですので、基本的には指名停止というようなことで、そういう報道がされた場合には、品川区役所と同じような対応をします。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ですから、最初の３年ぐらいはまるっきり出てこなかった一組の財政問題だけれども、できるだけそういう資料を集めていただきたい。それを今度説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"土井委員","kind":"質問","question":"逆の意味で、それをどこかにはめ込んでこのようにやれと言わない限り出てこないだろうなと思うんですけれども、その辺がどうなるかということが１つ。これらのものに対しては、その辺についての流れ、考え方みたいなものはどのようになっているのかということをちょっとお伺いをしたいと思います。","respondent":"中山資源循環推進課長","answer":"あるいは認識ですけれども、かなり相当１つの計画をつくるにしても、中間的な報告が出たりということは出てまいりました。","id":"exchange-005"},{"speaker":"土井委員","kind":"質問","question":"今のお話を伺うと、また借金が増えたらどうするんだという話のところぐらいにならないと話が出ないよというふうにも聞こえたわけですよ。１０年出ていると、その辺がどうなのかなという思いでちょっとお伺いをしたんですが、逆に我々はそのころいるかどうかわからんけれども。","respondent":"中山資源循環推進課長","answer":"清掃工場の現場で考えます、練馬と有明工場については合意をして、初めていわゆるアウトソーシングによる運営が進められる。こういう整理をしていくわけですから、その中でよりよい合意を得ながらの効果的な方向性を示していくというふうになるかと認識しております。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問・要望","question":"組織にかかわることなどが起こったときに、それについてきちんと協議する、ある意味当たり前なんです。しっかりと話し合い等を進めておいていただかないと難しい部分が出てくるのではないかなという思いがするものですからそのように申し上げているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"私は一般質問で全体的なことはもう伺っているので、きょうはやめて、教えていただきたいというか、勉強させていただきたい項目を。やっぱり売り払いというか、どうせならやっぱり売り払いの計画がこの１５年ぐらいの長いスパンの中であれば、そこら辺の点を教えていただきたい。","respondent":"中山資源循環推進課長","answer":"１点目の財政調整基金の払い出しを単純に当て込むと、財政運営上、多分一定の緩衝を持っていくということであるというふうに認識をしております。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問・要望","question":"もちろん積みながら使っているのはわかるんだけれども、この計画でどうしてどこのだれがということを教えていただきたいんだけれども。一組でやるわけだから、積んでいってこれだけという部分は、どこのだれがというふうに私は理解しておけばいいのかな。","respondent":"中山資源循環推進課長","answer":"それについては、基本的な先ほどの施設整備の方針とか、それを大枠で一廃計画で確認して、それをまた数値化している。中にはそういうデータのつくりは、それぞれのところで積み上げる、こういう状況です。","id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"１つだけちょっと確認をさせていただきたいんですが、話ができる段階なのか、ちょっと教えていただきたい。","respondent":"岩崎環境清掃事業部長","answer":"実は、あした、部長会が予定されておりますが、そこである程度の説明があるというふうには聞いております。ある程度の説明にとどまって、これまで断片的な説明しか受けていませんので、まだだめなようです。","id":"exchange-010"},{"speaker":"沢田委員","kind":"意見","question":"この経営計画と経営改革プランのこの３色刷りのトップに、ベテラン職員が減少する中での安全で安定的な運営という項目をトップに挙げていますね。","respondent":"中山資源循環推進課長","answer":"実施しているというのが、ご説明申し上げたように、日中の部分を多分職員がやっているというふうに思います。運転についても、単に焼却するだけではなくて、いろいろな機械調整、トラブル対応等にはメーカーがいいだろうと。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問・要望","question":"それとあと、もしわかったら教えてほしいんですが、京都議定書でＣＯ２の削減を６％というのを２０００何年までに決めていますよね。部長は専門ですから、ちょっと今回の話とは外れてしまうんですが、わかったら教えていただきたいんです。","respondent":"中山資源循環推進課長、岩崎環境清掃事業部長","answer":"いわゆる事故等の対応という部分で言えば、リスク対応についてはそれなりに安定的にやっているアウトソーシングの実績がありますから、経験者を一定残しながらアウトソーシングしていくというのが現在の段階です。京都議定書の手法を用いて、それが日本のＣＯ２削減の計算にちゃんと繰り入れられるような仕組みになっている、こういう関係だということです。","id":"exchange-012"},{"speaker":"沢田委員","kind":"意見","question":"売買をするのは一体どこなのかと、国以外ないですよね、今の話で行くと。だけど、そこらの詳細は一体どうなのかなということがわからないので聞かせてもらったんですが、とりあえず終わりにしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"三村委員","kind":"質問","question":"先ほどのアウトソーシングのところで、ちょっとお聞きしたいんですけれども、７ページの表によると、７億円ぐらいマイナスというふうに出ているんですけれども、４ページのほうの職員費と工場等運営費のところの差額は、平成１７年度と比較するとどうなんでしょう。","respondent":"中山資源循環推進課長","answer":"これはいわゆる工場部分に特化したものが７ページのほうのアウトソーシングの効果です。特に平成１７年、平成１８年の間で職員が減って、減少の部分と工場の部分とで違いがあるというふうにご理解いただければと思います。","id":"exchange-014"},{"speaker":"三村委員","kind":"質問","question":"済みません、経営改革プラン、カラー刷りのところで、行財政の見直しということで、スラグの有効利用量の拡大と、競争入札による売電などというふうに書いてあるんですけれども、この競争入札によって売電するのはどういったことか尋ねました。","respondent":"中山資源循環推進課長","answer":"非常に電力の関係事業者が増えてまいりますので、こういう部分は今後さらに強化といいますか、競争性を持って取り組んでいきたかったところです。","id":"exchange-015"},{"speaker":"三村委員","kind":"質問","question":"競争入札というところも含めて、これは廃プラを燃やして、その電力を売却するんか尋ねました。","respondent":"中山資源循環推進課長","answer":"いわゆる入札で売却するかどうかというのは、これは売却の方法の問題ですから、廃プラスチックの焼却によるカロリー増による総売電量が伸びるということと、この入札方法とは一致するというか、次元が違うものということです。","id":"exchange-016"},{"speaker":"三村委員","kind":"意見","question":"２３区でどういうふうに各区で取り扱うかというふうに検討していくものだと思うんですけれども、こういう廃プラスチックの焼却を通じてどういうふうなお考えというか、２３区の意向というのはどういうふうに決定されているのかとの意見を述べました。","respondent":"岩崎環境清掃事業部長","answer":"廃プラの熱利用をしましょうというのは、一組ではなしに、２３区の区長会で確認したものです。各部長、課長も、その前提で物を考えているはずです。","id":"exchange-017"},{"speaker":"三村委員","kind":"質問","question":"一般質問でもさせていただいたんですけれども、各区事項として廃プラスチックの有効利用については２３区共通できちんとリサイクルしていくというふうな決定については、その辺についてはどうなんでしょう。","respondent":"中山資源循環推進課長","answer":"廃プラスチックサーマルリサイクルを検討していくとありまして、平成２０年に本格実施するということですから、部長の説明のように。まだステーション回収が２３区そろっておりませんので、これはできるだけ２３区でやりましょうということが区長会の方針の中で出ております。","id":"exchange-018"},{"speaker":"三村委員","kind":"意見","question":"済みません、２３区の清掃一部事務組合に関わってくると思うんですけれども、各区のほうで進めていくというところで、品川区としては、今後検討というさっきのお答えだったんですけれども、どのような今後の方針、方向性としては考えているのかとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"基本的にこれは区民委員会の話になると思いますけれども、いずれにしても可能性について、これは検討していくという考え方であります。マテリアルリサイクルは難しいという中で、今回のような方針になっておりますけれども、その辺は研究をやっていくということです。","id":"exchange-019"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひ拡大の方向で検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"三村委員","kind":"質問","question":"先ほど談合のお話があったかと思うんですけれども、今回、売電をしていこう、廃プラスチックを活用していこうという、その改革のほうだと思うんですけれども、今後の計画というのは、どういうふうに考えているのか尋ねました。","respondent":"中山資源循環推進課長","answer":"その辺については、先ほど申し上げたように、情報のいろいろな確認を当方でもしていって、秋口までに一定の結論をという話を聞いておりますけれども、現状はそのような形です。","id":"exchange-021"},{"speaker":"本田委員","kind":"確認","question":"分担金についての確認ですが、１５年後は１５億円の減額にはなっていますけれども、どういうここは改善を加えるのか。各区の持ち出し分も入ってくるというふうに考えるんですけれども、ごみ減量が進む中で、その辺はどういうふうにお考えか尋ねました。","respondent":"中山資源循環推進課長","answer":"例えば２３区と連携する部分でのごみ量減であるとか、しっかり進めていく中で、維持管理コストも含めた削減が図られていくです。１点だけ、平成１８年度以降の１つの改革として、ごみ量をベースにするということで変更しています。","id":"exchange-022"},{"speaker":"本田委員","kind":"質問","question":"いろいろ２３区の中にはあるわけでして、区の考え方があっていいのではないかというふうに思うんですけれども、その辺はどうですか。的外れなことを言っているのかどうか。","respondent":"岩崎環境清掃事業部長","answer":"ここのところ、多分、問題が大分大きくなってくるのではないかというふうに思っております。","id":"exchange-023"},{"speaker":"本田委員","kind":"質問・要望","question":"環七が海底トンネルが開通していますから、ですから、ものすごい量ですね。先ほど来の説明の中で分担金を何となくさらりと言っているものですから、一組の中でここのところの問題はもっと真剣に煮詰めておいていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/148286?Template=document&Id=5598#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":26963,"voices":78}},{"id":"h18-20060628-16","meetingId":"h18-cm06","date":"2006年6月28日","dateIso":"2006-06-28","committee":"街づくり特別委員会","time":"午前１０時０２分～午後 ２時４５分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"前回、今後の委員会運営について皆さんからご意見をいただきましたが、先日、理事者の意見も伺いながら、正副委員長で調整をさせていただきました。今年度１年間、このような形で進めさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"生活安全フォーラム（大人のための騙されない講座）","agenda":"生活安全フォーラム（大人のための騙されない講座）","exchanges":[{"speaker":"築舘委員","kind":"質問・要望","question":"昨年１年間でかなりの被害が増えておりまして、そういった一連の傾向がありましたら、教えていただきたい。","respondent":"金子生活安全担当課長","answer":"大ざっぱな説明になるかと思いますけれども、例えばオレオレ詐欺という事案に関しましては、被害者の７７％が女性です。犯罪者の傾向につきましては、暴力団が介在して、それぞれ人を使って暗躍しているということがあります。","id":"exchange-002"},{"speaker":"築舘委員","kind":"質問","question":"まずそういった被害にならないようにということで、プログラムですか、講演もされたと思います。町会、自治会、そういった形のどの程度の範囲にＰＲをして動員をしたのかということをお願いしたいと思います。","respondent":"金子生活安全担当課長","answer":"それと広報です。それぞれ直接私どもが赴きまして、それぞれ参加要請をして、被害に遭わないようにという形でご参加をいただいております。","id":"exchange-003"},{"speaker":"大西委員","kind":"質問・要望","question":"この次々契約の昨今の増減というか、それはどういう状態であるのかを、おわかりだったら教えていただきたいんですが。","respondent":"金子生活安全担当課長","answer":"申しわけございません。今の警察等に連絡する中では、ちょっとはっきりしたことは把握してございませんので、調査をしたいと思います。","id":"exchange-004"},{"speaker":"大西委員","kind":"質問","question":"何だかんだ、健康用品のマッサージ機だということになり、およそ１件当たりの被害が１,０００万円近いというものが非常に多く見受けられる。答弁がありましたけど、そのような状態のなか、大体どのくらいの高齢者をお１人の民生委員が携わっておられるのかというのはどうなんか尋ねました。","respondent":"早津区民生活事業部次長","answer":"民生委員の方のほかに介護の関係のケアマネジャーが訪問したりする中で、そういったことが未然に防がれるようにという形での対応をしています。ちなみにケアマネジャーに対しても、こういうだまされないような形での同様の趣旨での情宣活動をしているといった状況です。","id":"exchange-005"},{"speaker":"大西委員","kind":"意見","question":"民生委員の方が３００名程度の方を担当されている。これは介護認定を受けて、民生委員は大体どれぐらいのスパンでこの高齢者世帯とか独居老人に面談をして、そういうところから私は……との意見を述べました。","respondent":"鈴木（ひ）委員長、早津区民生活事業部次長","answer":"民生委員の中身になりますと、この街づくり特別委員会の所管とちょっと違ってきますので、その辺を考えた上でのご発言をよろしくお願いします。 基本的には月１回の訪問をしてくださいという形にしています。お元気であれば、もう少し間遠になる方もあるですが、原則的には月１回の訪問なり接触をしてくださいという形になってあります。","id":"exchange-006"},{"speaker":"堺委員","kind":"質問・要望","question":"ちょっと確認というか、要望というか、先ほどのお話の中で、出席が３０６名でアンケート回収が１４８名ですか。私はこういう事業についてはより細かい単位で実施されたほうが、より効果あるんじゃないかという気がするので、それをちょっと確認しておきたい。","respondent":"金子生活安全担当課長、田村地域活動課長","answer":"１点目の資料の活用の関係について説明を申し上げます。内容を生活安全ニュース等によりまして、各町会長にも紹介をしていきたいと考えています。 今回の騙されない講座の会場は５００人ということなので、どうしても全員が入れるというわけではございません。防犯活動は町会長単位の中で取り組んでおりますので、引き続き１３地区で、ぜひ周知していければと考えております。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問・要望","question":"細かい単位でやっていかないと、なかなか防災というのは出てこない、そんな思いがありましてお尋ねをしました。ひとつ引き続き区民の人が被害に遭わないという意味でも、細かい単位でぜひ実施していっていただきたい、こんなことをお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"昨年１年間で品川区内で１１６件ということですが、１１６件はどのぐらい犯人がつかまったといいますか、解決がされたんか尋ねました。","respondent":"金子生活安全担当課長","answer":"人員について正確な数字は把握しておりませんが、ほとんど検挙されていないのが現状だと思います。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"単純な質問なんですが、何で検挙されないんか尋ねました。","respondent":"金子生活安全担当課長","answer":"そこからまたたどって次のところに行ったところ、また電話機しかなかった。それが何重にもかかってありまして、相当組織立ってやらないと、この１１６件についての捜査ができないというのが実情と聞いております。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"警視庁の幹部として来てくださっているという意味でお伺いをあえてさせていただきたいんですけれども、離れちゃったら注意していただきたいんですけれども、その辺の職員の人数というのも関係があるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"全然満員になっていないじゃないですか。この辺というのはどういう状況なんか尋ねました。","respondent":"田村地域活動課長","answer":"やっぱり初めての事業なので満席にしようということで、想定で割り当て人数を含めて、品川の広報でも一般の方を募集しました。５２０名程度来るという前提だったんですが、当初５２０人で満席で、さっきの生活安全担当課長の言った結果になってしまったという状況です。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"うち子どもいませんとか、主人はいませんといったらばれちゃうわけですから、だまされるということは家族がいるわけですよね。町内に住んでいます、そういう会とかに入っていないけど生きていますという方たちを守っていくシステムというのは、何かないんか尋ねました。","respondent":"早津区民生活事業部次長","answer":"先ほども答弁がありましたけれども、一般の方にこそ集まってほしいという思いは私どもも持っております。引き続きどういった方にどういうふうに声をかけると、より集まっていただけるのかというのは、また検討させていただきたいと考えています。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"最後にしますが、具体的にこれはオレオレ詐欺に遭ったかもしれないというのを３７７７－１１１１に区民の方がかけてきたときには、どこの課に行って、承った課は具体的にどういうふうに動いて、どういうふうに処置していくんか尋ねました。","respondent":"金子生活安全担当課長","answer":"そういった場合については速やかな対応が当然必要だと思います。ただ連絡するのではなくて、その際には一時的な対応等を指示した上で連絡をしたいと考えております。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"もちろんどうしても伝わらないところもあるかと思うんですけど、私思いますに、特に振り込め詐欺ですか。電話でとりあえず押さえるべきことは押さえて、そういうことも区で考えられたらどうかなと思うんですけど、その辺いかがか尋ねました。","respondent":"金子生活安全担当課長","answer":"警察のほうと連携をとりながら、一番いい方法を検討していきたいと思います。ＡＴＭにそういったシールの貼付であるとか、あるいは郵便局に対する指導等は、警察等と連携しながらやっているところです。","id":"exchange-015"}]},{"id":"topic-03","title":"２番目の木造住宅の耐震改修支援事業の概要","agenda":"２番目の木造住宅の耐震改修支援事業の概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"質問したいのは、このままずっと１０年間いっちゃうのかどうかちょっと気になったところなので、そこを伺いたいと思うんですね。区民の皆さんへの周知は２１日後の広報だということで、やっぱりいいことですから、この２つ目も質問させてほしいと求めました。","respondent":"片田建築課長","answer":"できるだけ早い時期に支援制度を進めていきたいということで考えて、東京都との補助金の問題とか要綱等について詰めてきたところがあります。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"しかし、あるいは火災の延焼になって被害が拡大するということだってあるわけですから、私はそこのところを強くお願いしたいなと思っています。その点について改めて見解があればお願いします。","respondent":"片田建築課長","answer":"これは３月３１日末現在ですけれども、それとあわせて補強に向けた対応を検討しているというものを含めると、約２０件の件数があります。この整備地域で今後進めていくうえで効果があると考えており、整備地域を基本的な対象地域としていきたいということで考えてあります。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"しかしながら、また安心感も非常にあるというところでは、一定程度の考慮あるいは配慮というのはしてもいいんじゃないかと私は思うんですね。どの程度これがこの１０年の間に進んで改善されていくかはよく見守っていきたいと考えていますけれども、要望だけさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"そこに税金を投入するのはどうかなと思っていましたが、今の課長のご答弁を伺っていて、もっともだなと思いました。もっと大々的にやればいいと思うんですけれども、なぜたった５棟をということで出してくるんか尋ねました。","respondent":"片田建築課長","answer":"他国あるいは自国での地震被害がございました中で、５棟についても、先ほど申し上げたように整備地域の中での２割が耐震改修までつながる。そういうことを含めると、今後の診断および状況を十分踏まえて、この部分については検討してまいりたいと思ってあります。","id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"改めて聞きたいんですけれども、新耐震基準前の木造建築物が区内全域に何棟あって、この整備地域内に何棟あるのか、その数字について教えてくれますか。","respondent":"片田建築課長","answer":"その３分の１というところでの単純な比較計算はできませんし、２万棟の割合の相当数が整備地域の中にあるのかなということを考えてあります。ちょっと細かい数字については、そこまで内訳は出してございませんので、現況ではそういう状況です。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問・要望","question":"今一緒に聞けばよかったんだけど、忘れてしまいましたけど、さっき平成１８年度から２７年度までが東京都の時限的な措置だということでしたけれども、東京都はどの程度今度のこの施策で東京全体でこの改修を行おうとしているのか、その辺の件数、棟数としてわかれば教えていただきたいんですが。","respondent":"片田建築課長","answer":"これはちょっと古い資料ですけれども、１月の新聞報道等々によれば、東京都が診断改修助成へということで、整備地域で、今後１０年で２万棟強を予定しているという情報が入ってあります。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"東京都が１０年間で２万棟、品川の場合５棟で、１０年間やったとしても５０棟ですか。その辺を考えれば、危険度はそのまま野放しになるのではないかなという感じがするんですけれども、いかがか尋ねました。","respondent":"片田建築課長","answer":"次に、１５０万円を耐震改修にかかる費用の見込みということで想定していますので、トータル７５万円ということが内訳の助成になってあります。","id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"今、最後のほうで、毎年５棟とは考えていないということですけれども、ただ東京都と同じように１０年間に限定だというのであれば、１０年間でどれだけ耐震改修する目標を持っているのかというのを説明するよう求めました。","respondent":"片田建築課長","answer":"これまでも診断の中でも、当初４０棟という中で、１６年度については６０件と１.５倍の数字になってあります。少なくとも啓発に努めて、そういうまたアンケート調査を行いますから、それもよく確認していきたいということで考えております。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"２万棟あって１０年間しかやりませんよといったときに、それはこれから増えるかもしれません。だから、その辺をもう少し考え方としてお聞きしたいんですけど、いかがか尋ねました。","respondent":"片田建築課長","answer":"考え方はこれまでご説明してきた中だと私は考えてありますけれども、それを計画的にやっていくんだということでは私はないと考えております。それを区が支援してくというスタンスで考えてありますから、少なくとも５件という数字については、ご理解をよろしくお願いいたします。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問・要望","question":"先ほど教えていただいた他区との関係で言えば、５棟というのは、非常に少ない数字ではないかなと思うんです。そこもすべて対象にしていくぐらいの体制をぜひつくってほしいと求めました。","respondent":"片田建築課長","answer":"その中で東京都としても、広域自治体として、耐震改修計画の策定を検討していると聞いてあります。これらのことを十分視野に入れながら、必要な対応を考えていきたいと思います。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"それについて１点質問。１５０万円という金額じゃなくて、３００万円なり５００万円なり、ちょっとその辺の見解を説明するよう求めました。","respondent":"片田建築課長","answer":"いわゆる旧耐震ではそれをもとに安全性が検討されていますけれども、震度６の地震であれば、そのような考え方ですすめているものです。だから、お金をかければもっと安全なものにすることは可能ですが、当然これは個人の財産ですから、建主の考えによるものと認識しております。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"１５０万円、２００万円で筋交いを入れて、ある程度傾くけど壊れないよと。もともとの根本の基礎とか構造が問題があるんですから、より安全なような気がするんですけど、その辺をちょっとご見解だけ説明を求めました。","respondent":"片田建築課長","answer":"これまでの診断支援あるいは診断および改修支援は基本的には建物を建て替えるのではなくて、現況を安全なものに補強することを基本と考えています。そこの中では建替えの支援ということも含めて、建替えに対する支援も行っており、事業としても住み分けを行っているものです。","id":"exchange-027"},{"speaker":"堺委員","kind":"確認","question":"今回５棟で７５万円ですから、トータル的にいきますと３７５万円という計算ですね。区の持ち出しは１棟当たり２１万円ですから、１０５万円ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"３番目の小山台一丁目地区防災街区整備地区計画","agenda":"３番目の小山台一丁目地区防災街区整備地区計画","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"この地域にどういう制度がかかっているか、この地域ですよみたいな、もっと重複した資料として出していただけないかなというのが１つお願いなんです。これをもう少し説明をしていただけますかとの意見を述べました。","respondent":"伊勢住環境整備担当課長","answer":"この地域は複層的に事業が重なったりしていますので、大変申しわけございません。資料２の４ページをごらんいただきたいんですけれども、これは既に都市計画で最低限高度地区７ｍ、それから防火地区にも規定されているです。","id":"exchange-029"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう１つだけ教えていただきたいんですけれども、要は敷地と接合部分の関係なんですけれども、この間口率を定める必要性といったらおかしいかな。どんな文章を読んでも１０分の７とかと出ているんですけれども、ちょっと間口率のところだけ。","respondent":"伊勢住環境整備担当課長","answer":"間口率の７割、私もいろいろ調べてはいるんですけれども、不燃化率というのが７割ということで、これになると大体焼け止まると言われております。","id":"exchange-030"},{"speaker":"菊地委員","kind":"質問","question":"それは規定としてこう言われている話で、規定としてそれがあるととらえていいんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"高さ５ｍ以上で間口分１２ｍのエリアを不燃化するといった場合には、１時間から２時間程度、人が移動するまでの時間が確保できる。一番いいのは１００％ですけれども、７割ぐらいあれば大体避難所が確保できるのではないか、こういうふうに考えております。","id":"exchange-031"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今回は品川区内５カ所ということですけれども、大体品川区内にはどのくらいの交番が設置されているのか、空き交番はその中でどのくらいあるのか、ちょっとその辺をまず教えてほしいと求めました。","respondent":"金子生活安全担当課長","answer":"区内には３４の交番があります。ただここにある５つの交番については、この中のさらに幾つかは空き交番と言われるものが含まれております。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"交番がなくなったらどうなるのかなという不安はちょっと感じるので、選ばれた基準というのはどういうふうになっているのかは、知っている範囲で教えてほしいと求めました。","respondent":"金子生活安全担当課長","answer":"わかる範囲でお答えいたします。交通事故の処理件数あるいは１１０番の入電件数、こういったものを勘案して今回、見直しをしているです。","id":"exchange-033"},{"speaker":"南委員","kind":"意見","question":"昨日今日のニュースでは、今は犯罪は場所を選ばず、時間を選ばずというふうになっていると思うんですね。もう少し別の時間をあれして議論していければいいと思いますけれども、今のところ、私の意見だけ述べて終わりにしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"堺委員","kind":"質問・要望","question":"３４のうち５カ所がなくなるわけですから、交番が１つなくなったために、対策を講じていただきたい。そのことを要望しておきます。","respondent":"鈴木（ひ）委員長","answer":"この問題に関しては特定事件調査でもこれからも取り組んでまいりますので、その中でまたいろいろ出していただければと思います。これでその他を終了いたします。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/847285?Template=document&Id=6328#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":32113,"voices":96}},{"id":"h18-20060629-14","meetingId":"h18-cm06","date":"2006年6月29日","dateIso":"2006-06-29","committee":"行財政改革特別委員会","time":"午前１０時１２分～午後３時２４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"細かいところで申し訳ないですが、旧公園出張所の東部が平成１３年の事業部制になって品川大崎土木事務所に来ているのだけど、図のあり方で。ですから、いかがでしょうか、私の見方が悪いのか説明を求めました。","respondent":"日下部企画財政課長","answer":"確かに、今、ご指摘を受けまして、私も初めて気がつきましたが、おっしゃるとおりだと思います。その辺は、また改めて再確認をいたしまして、訂正をさせていただきたいと思います。","id":"exchange-001"}]},{"id":"topic-02","title":"これより、特定事件調査を行います。 公有地等の活用に関すること","agenda":"これより、特定事件調査を行います。 公有地等の活用に関すること","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"というのは、地域的に各地区にいろいろ分けて整理していったほうがいいだろうと思っているので、そのあたりの考え方を教えてほしい。それから、要望があったからそのままいくのか、総体的に品川区全体の地域を見てという考え方になっているのか。","respondent":"日下部企画財政課長、新美企画部長","answer":"今回、これから具体的に詰めてまいりますけれども、この辺はこれからさらに具体的な検討・調整を進めていきたいと考えています。ご要望を伺った上で、本日を一つの皮切りにして… 現在介護保険第３期事業計画をまとめているところですので、今回の学校の跡施設についても活用していくことが適当ではないかということの案です。","id":"exchange-002"},{"speaker":"須藤委員","kind":"質問","question":"２階部分を何室というお話だけれども、ケアホームにしたら２階全体を使っても、どうなのか。民間の方々もいろいろな面でやりいいのではないかと思うので、そういった質問をさせていただいたのですが、その辺はいかがか尋ねました。","respondent":"新美企画部長","answer":"少子高齢化の福祉ニーズへの量だけではなくて質的な面も含めて対応していくということが、一つの行政課題ではないかという認識のもとに。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"ここでは一つだけ確認をしたいのが、避難所施設も入れていくということですが、計画上、地元の２町会の避難所になっているようです。確認したいのは、２町会の避難所になっているわけですが、どのようにお考えか説明を求めました。","respondent":"日下部企画財政課長","answer":"１階に事務室、１階部分が算定対象に入っておりませんで、ごく一部です。ほかのスペースの算定にあたりましても、現在の段階では直ちに避難の見直しとか、そういうことに直結するという心配は私ども持ってございません。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、今の避難所の運営一つを取っても、数字はそうかもしれない。ですから、自動的に避難所に使えなくなるわけですから、そのことを十二分に考えて対処してくださるのでしょうかという確認の答弁をお願いします。","respondent":"日下部企画財政課長","answer":"作業を進めてありますので、そういった意味では、今ご指摘の点も含めまして調整をする。それから、十分にご心配のないような形で整理をするということで、進めてまいりたいと考えています。","id":"exchange-005"},{"speaker":"川西委員","kind":"質問・要望","question":"大変、施設の責任者の方が「これだけの施設ですから、大いに利用してほしい」ということを中を見ながらおっしゃっていたのが記憶にあります。入れないのだったら要望だけでとどめますけれども、それがかわるのかなと思いますけれども、そのように思います。","respondent":"日下部企画財政課長","answer":"基本的に少年野球、その辺をどうするかというのは、これから具体的に調整をさせていただきたいと考えております。ティーンズプラザのような形での機能を盛り込むことについては、今のところ区のほうとしては考えていない状況です。","id":"exchange-006"},{"speaker":"川西委員","kind":"質問・要望","question":"１点だけ要望です。せっかくですから、跡地利用のときには規模のきちんとしたものをつくっていきたいというのが、品川区に対する願望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"事業部ごとにどのような検討をした結果、ここに絞られてきたのかという、経過のところを一つお伺いしたいと思います。地域の方が今まで求めていたこと、今後求めていくことというところでは、ここにどう生かされているのかという点をお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"やはり少子高齢化は避けて通れない状況でありますし、それに対する対応というのは、区としても再重点課題として取り組まなければいけない。これもすべて実施計画の中におきましても、少子高齢化に対応した重点課題ということで、まず１点目です。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今までの区のスタイルではなくて、もっと新しいものを求めていくことも必要ではないかと思うので、ぜひ公募型も盛り込まれないかと思っています。空いた場所をどうするかというより、この案のままいくということではないだろうということも含めて、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"さらに地域にもご説明をさせていただいて、ご意見をいただく。要望をいただいて、そういった意味では、委員のご提案の趣旨に沿っているのではないかと考えているところです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"提案","question":"公募型はどうかという提案をさせていただいたんですけれども、これから八潮の問題とか、次々に検討することが生じてきます。これは要望で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"本当に開放してくれるというなら、少年サッカーにも少年野球にとっても本当に大きいんですね、朝から試合が組めるわけですから。サッカー場の取り合いもないですから、土・日、やはりそれに付随した施設を拡充していかなければいけないと思うんです。","respondent":"日下部企画財政課長","answer":"そういった意味におきましては、委員ご指摘のように、今後学校の機能は伊藤中学校に移る。対外的な試合とか、その辺のご指摘の点も含めまして、これから関係地域なりあるいは関係団体とも調整をしてまいりたいと考えております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"まず伺いたいのは、いつどのような規模なのか、もう少し詳しく教えていただきたい。それはどのように考えているのか、ぜひ行うべきではないかと思いますけれども、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"既に７月上旬、大井第３地区全体の区政協力委員会の会長ということで、まずご説明の機会を持たせていただくということははっきりしております。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が年末に行ったアンケートでも、品川区の進め方に対して、生徒や地域の意見を聞こうとしない品川区の姿勢があるという声もたくさん伺っております。公聴会という形なのか、やることは最低限のことではないのかなと思うんですけれども、ご見解を伺いたいと思います。","respondent":"日下部企画財政課長","answer":"「これから具体的に改めてご提案、ご説明をします」ということも、既にお話しをしています。利用者の皆さん方にもご説明の機会を持つとか、そういう意味ではできる限り幅広く区としての考え方をご説明させていただいて、ご意見。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ関係者の方に伺いますので、時間がなかったら配ってある用紙に書いて帰りに渡していただいてもいいとか、いろいろな形はあるかと思うんです。区内３番目のケアホームの建設がありましたけれども、ケアホームが必要なのかよくわからないので、もう一度ご説明をほしいと求めました。","respondent":"日下部企画財政課長","answer":"組織的にどうのこうのというより、そういった意味では、今回は再三申し上げているような地域への説明をしっかりやってまいりたいと考えております。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"手法はあるかと思うんですけれども、それが載せられているかどうか、そこだけ確認をさせてください。いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"連絡先も、当然掲載しまして、ご意見もざっくばらんにいただくという形を取ってまいります。それから、いろいろ要素は絡んでまいりますので、その辺についてはこれからの課題ということで整理してまいりたいと考えております。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"もう１点、あそこは教育施設ですからスポレク委員会が月１回、そういう調整をしています。従前使っていた方々がスポレク委員会の中で利用調整会議をやっていたけれども、今までどおり使えるのかどうか、どういう形になるのか説明を求めました。","respondent":"日下部企画財政課長","answer":"そういった意味では、利用が制約されるとか、そういう心配は基本的にはないと思います。ただ、学校の部活絡みの関係でいろいろな影響が出てこないとも限らないという話は承知しています。","id":"exchange-016"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、こうするのだというものをしっかり示していかないと、例えば八潮に今度つくります。今、説明すればいいというだけではないだろうと感じているので、その辺を聞かせてほしいと求めました。","respondent":"新美企画部長","answer":"跡施設にしろ、決して少子高齢化とか高齢化対応だけに、何らかの単独のニーズだけに活用するということは毛頭持っておりません。複合的な活用も含め、検討せざるを得ないというのが、具体的な候補地を思い浮かべたところでの対応方針になろうかと考えています。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、学校跡地を利用するという発想自体は、当時は持っていなかったと思います。ここではこれだけのメニューでいいですかと言われても、それは考え方だけで、もう少し議論をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"井上委員","kind":"提案","question":"今回は行政が考える一つの提案として示させていただいたということですから、これ以外に提案があれば、そういう形で進めていくと。出されている以上、ある程度のものは見えているのではないかと思うんですけれども、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"国の調査でも、ここ最近の傾向としてははっきり出ておりますので、そういったニーズにしっかりこたえていこうと。西大井保育園、新しい区民のニーズにしっかりとこたえる形で、新しい施設である幼保一体施設をここに配置していきたいという基本的な考え方です。","id":"exchange-019"},{"speaker":"井上委員","kind":"意見","question":"通勤に行く前に、そこに寄らなければいけない。つくったからいいというものにはならないと思うので、その辺のことを考えると、どの程度の規模を考えていらっしゃるのかとの意見を述べました。","respondent":"日下部企画財政課長","answer":"大体、１,０００m2程度を考えておりますけれども、それでいきますといろいろな基準があります。１人当たり何m2という基準もありますから、それで計算しますとおおむね１００名強ぐらいの規模で整備できると見込んでいるところです。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"今まで子どもたちが自分たちの学校がどう変わっていくのだろう、どう変わったらいいというような要望を受けたことがあるのか。今後、そのようなことをする予定があるのかお伺いします。","respondent":"日下部企画財政課長","answer":"その中にも、やはり子どもたちが自由に遊べ、親同士、子ども、高齢者等が交流できるスペースが欲しいというご意見もございました。この辺を一応踏まえて、基本的な今ご指摘の点は、区の案の中にも盛り込まれているということでご承知おきいただければと思います。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"第３次介護保険制度でも推進していく計画を立てていらっしゃるということですが、全体的に福祉をどうするかというところで、どの程度を見越しているということか尋ねました。","respondent":"日下部企画財政課長","answer":"そうは申しましても、例えば実施計画の中に具体的に盛り込むことはできませんので、絵にかいた餅になってはいけません。全区的に整備していくという基本的な考え方のもとで、それを中長期の視点で実施計画の中に盛り込んで、具体的に整備を進めていくという考え方です。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"一括で貸し付けをされるという方法は、今後指定管理者制度への移行になるのか、どういう形になるのでしょうか。自主管理の方たちはどのように形成していこうと思っているのか、どのような方たちを思い描いていらっしゃるのかというところをお願いします。","respondent":"日下部企画財政課長","answer":"原小学校につきましても、もちろん地域との十分な調整抜きに具体化することはできませんので、これから具体的にその辺の調整をするという考え方です。１点目の施設の運営につきましては、民設民営という考え方を基本にしまして、コストの低減等を図っていきたいと考えております。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"今のところだけ、民設民営ということは、改修の費用は区が改修するのではなく、事業者を選定して事業者の費用で改修していくということか尋ねました。","respondent":"日下部企画財政課長","answer":"この辺は、お互いにどのように負担し合うかというスキームについては、これから具体的に詰めていきたい。今の段階では、そこまではっきりした形は出せませんので、その辺はこれから検討、調整をしてまいりたいと考えております。","id":"exchange-024"},{"speaker":"井上委員","kind":"提案","question":"先ほど、行政に説明をしてほしいと住民の方たちが要望を上げたら、区は説明に出向いていただく場をつくっていただきたいのです。そのような要望があった場合には、行政として説明する予定があるのかないのか、お伺いしますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"そういう意味では、いろいろな意見があるでしょうが、まずはそういう形でこちらからご説明をするということから進めていくのが基本ではないか。そういう手順、ルールをしっかりと踏まえて、進めていきたいと考えております。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから、議会に報告しました、区政協力委員会に中旬、下旬、２回説明します。そこは、きちんと説明をしていただく機会を持っていただけますかということについてのお考えを伺っただけです。","respondent":"日下部企画財政課長","answer":"手順ということでまいりますと、そこに来て説明して、要望を言うよと。きちんとホームページでも何でもご意見をいただく機会はしっかり持っているわけですから、そういうことでご理解をいただきたいと考えています。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"説明不足だったという指摘がいろいろなところでありますので、行政として説明しましたではなく、聞きたい人たちに説明をしてほしい。どういう形であればお話がいただけるのか尋ねました。","respondent":"日下部企画財政課長","answer":"繰り返しで大変恐縮ですが、こちら側からきちんとルール、手順を踏んでご説明をする。それをしっかり受け止めてまいりたいと考えています。","id":"exchange-027"},{"speaker":"藤田委員","kind":"質問・要望","question":"いろいろなグループが使いたいと言っているわけですから、それを拒まないような形で多目的に、どうぞ皆さん使ってくださいと。これだけの施設ですから、何でも使えるわけですから、やはり危険のないような、安心して使えるような、そういう施設を考えていただきたい。","respondent":"日下部企画財政課長","answer":"構造壁とか耐力壁とか、どうしても建物自体の強度に係わるような要素がありますので、簡単に壁を抜くことができない。運営もいろいろな形でできる可能性を持っていると思いますので、この辺は十分に地域のほうともいろいろ意見調整をしてまいりたいと考えております。","id":"exchange-028"},{"speaker":"藤田委員","kind":"質問・要望","question":"その辺の研究をお願いしたい。この辺の管理体制をしっかりとした、これは長期にわたるわけですから、その辺もぜひ研究をしていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"中島委員","kind":"質問","question":"先ほどからいろいろなご意見が出ているんですが、最初にお伺いしたいのは、今回の基本的計画を出されるにあたって、まちの中の声を参考にされたのか尋ねました。","respondent":"日下部企画財政課長","answer":"前回も触れさせていただきましたけれども、ＰＴＡの皆さん方を中心にしまして、事前にぜひともという形で強く要望が寄せられました。その辺も参考にさせていただいた上で、計画の中に盛り込ませていただいたです。","id":"exchange-030"},{"speaker":"中島委員","kind":"質問","question":"地域の声がどれだけ浸透しているのかということが大事だと思うんですが、それだけではすべて最高とは言えません。中にはいろいろな施設をつくるとなったときに、その辺の比較をしていく研究は必要ではないかと思うんですが、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"先ほど藤田委員からもありましたように壁の問題とか、いろいろ制約条件が出てきますので、なかなか難しい面があります。さらにコスト的な面も、それなりにきちんと有利な面があるということを確認した上で、このようなご提案をさせていただいてあります。","id":"exchange-031"},{"speaker":"中島委員","kind":"質問・要望","question":"一つ要望しておきたいのは、地域の声を区政協力委員だけに「皆さんのご意見はどうですか」と聞くだけでは、町会長によっては。今後いろいろなことを開発していく上で、お願いしたいと思うんですが、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"幅広くご意見をいただくという上で、今、ご指摘の点は非常に重要な点だと思いますので、これはしっかりとお願いしてまいりたいと考えております。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１のところで具体的に幼保一体施設、なぜここに絞られてきたのか、データとか検討過程がどういう内容だったのか教えてほしいと求めました。私どもは有料老人ホームだったら、民間で次々とつくっているので、その辺はどのような検討過程でここが選ばれてきているのか説明を求めました。","respondent":"日下部企画財政課長","answer":"検討過程ということでありますけれども、委員からもご指摘がありました、幼稚園と保育園のメリットを融合化している。こういう形で、具体的な提案をさせていただいているものです。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そうかなと思うけど、どのような中身ができるのかという、区のコンセプトがあるのですか。なぜ、幼保一体化のイメージを全然持たないで業者に任せてしまうのでしょうか、その辺はどうか尋ねました。","respondent":"日下部企画財政課長","answer":"幼保一体化につきましては、基本的に事業者についても公募方式で提案を受けて、それをベースにしていろいろ検討していくということです。具体的な諸条件については、ただはっきりしていることは、保育ニーズにしっかり対応していくということが非常に重要な点ですので。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺も踏まえて、そこをどう解消していくのかという道筋を見せてほしいという意味なので、ぜひそこは今後の中でお答えをほしいと求めました。公設民営なのか民設民営なのか、区との関係がどうなっていくのかという心配をされるわけですが、区との関係はどうなるのか尋ねました。","respondent":"日下部企画財政課長","answer":"民間による運営ということでありますけれども、先ほど社会福祉法人のケースを出させていただきましたけれども、基本的には土地と建物はもちろん区の所有でありますので、広い意味では公設民営というとらえ方をしていただいたほうがよろしいかと思います。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公設民営方式になると指定管理者のところより、さらに遠くに行ってしまってチェックができなくなってしまうのではないかという危惧をしています。この辺は、非営利のところでやってほしいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/218784?Template=document&Id=5802#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":38380,"voices":87}},{"id":"h18-20060725-6","meetingId":"h18-cm07","date":"2006年7月25日","dateIso":"2006-07-25","committee":"区民委員会","time":"午後１時０３分～午後２時２８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"の「平成１８年度地区総合防災訓練・職員防災訓練について」","agenda":"の「平成１８年度地区総合防災訓練・職員防災訓練について」","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"具体的な計画をお立てになって、この当日を迎える準備を進めていると思うんですけど、そういう地域特性に応じた内容になっているのか。たぶんなっているんだろうと思うんですけども、その辺の状況というのはどういうふうになっているのか教えていただきたいんですが。","respondent":"久保田防災課長","answer":"今お話に出てまいりましたように、主催があくまでも各地区の防災協議会ですので、当然計画段階からそれぞれ参加して計画づくりをしております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"そういう状況はどうなっているのかというのがなかなかちょっと見えないところなので、ちょっとその辺についても教えてほしいと求めました。ちょっと高度な技術が必要だとか、そういう部分というのは当然ありますので、その点の区の考え方についてちょっと教えてほしいと求めました。","respondent":"久保田防災課長","answer":"地域の方と一緒に上層階から、いろいろそういう形で補助しながら下の階までおろして、学校まで車いすで運ぶというような訓練も行ってあります。そういう中でまた地域のそれぞれの課題を生かした訓練を充実させる方向に今現在区のほうもなってあります。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"最後に聞きますけど、そういう地域の特性を生かした訓練内容になっているという説明で、それは当然のことだと思うんですけど、そういうリードというのは区のほうで一定程度この何年かの間にかけて指導といいますか、援助というのかな、そういうのをしてきているということで理解していいんか尋ねました。","respondent":"久保田防災課長","answer":"はい、おっしゃるとおりです。","id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"事前に調べてこないでこの場でお聞きするのですが、避難所の機能の評価という中の一つに発電機を配布する、これは今どうなったでしょうか。せっかくのいいチャンスですから、こういうのが可能なのかどうなのか、その辺も含めてちょっと進捗状況を。","respondent":"久保田防災課長","answer":"概要だけちょっとお話ししますが、まだこれから発注をかけるという状況でございまして、地区訓練のときにはちょっと間に合わないという状況です。できあがりましたら、街づくり特別委員会に報告する予定です。","id":"exchange-004"},{"speaker":"堺委員","kind":"質問","question":"それぞれ月１回ですかね、こういう訓練に値するかどうかわかりませんが、やっている所があるんですよね。ですから、そこの地区の近くにいる人たちがその訓練にかかわるというんですか、その辺はどうなんか尋ねました。","respondent":"久保田防災課長","answer":"全部の例えば私立の幼稚園とか、あるいは公立の幼稚園とか、保育園も全部総合的に巻き込んでというところまではなかなか難しいところがあります。今後もそういう点から見れば、機会をとらえて、やはり連携の充実については強化していきたいというふうに思っております。","id":"exchange-005"},{"speaker":"堺委員","kind":"質問・要望","question":"それが力になっていくわけですから、そういういわゆる災害が起きた場合に、どうしたって地域の大人の手は必要になってくるだろう。私は何回か指摘しているが、そういうところはまだ見かけないのでぜひそういうところも同じような形でやっていただきたい。","respondent":"久保田防災課長","answer":"今後連携の充実ということで、いろんな工夫をしていきたいなというふうには思っておりますので、今の趣旨を生かした形で検討していきたいと思います。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"やっぱり９月１日に総合防災訓練をよくやっていたんですけど、地域で避難所を一時避難場所として、その辺はどういうふうになっているんでしょうか。地域を挙げて、災害が起こったときには同じように影響を受けるわけですから、今伺いながらそういうふうに思ったので聞いてみようと思ったんですけど。","respondent":"久保田防災課長","answer":"ただ、いろいろ場所の問題とか時間の問題もありますので、やっぱり地区の防災訓練というのが一番適しているのかなというふうには思います。","id":"exchange-007"}]},{"id":"topic-02","title":"２番目の涼しさ回復プロジェクト","agenda":"２番目の涼しさ回復プロジェクト","exchanges":[{"speaker":"大沢委員","kind":"確認","question":"裏の２番目の１８カ所の測定ポイントということで書かれておりますけど、測定ポイントを決めるときの基準は何を基準にして１８カ所を決められたのかということと、確認のために説明を求めました。","respondent":"田中環境課長","answer":"なお、２番目のご質問とのところもあるんですが、全く対策をしていないところも比較上、大井町の駅前の広場のところをはかっております。そういうことで、室外機のそばとかということではなくて、そういう観点で測定ポイントを置いております。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"地域的に、場所的に偏りがない。住宅地ということで、ここを検証する上において、そういう二つの切り口で検証をされることもあるわけか尋ねました。","respondent":"田中環境課長","answer":"ということで、そういう比較できるような形で商店街のところをとっております。中延ですとか小山の商店街等については日光が当たったりするわけではないので、そこのところは測定ポイントを考える上では考慮に入れなかったです。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"ドライミストの濡れない霧ということなんですけれども、機械の大きさにもよると思うんですけれども、戸越銀座に設置してある機械というのは、どれぐらいの面積で、範囲でミストがかかるようになっているんか尋ねました。","respondent":"田中環境課長","answer":"ドライミスト機は発生装置が２本ありまして、それぞれ別の方向に向けて設置してあるんですが、それぞれ３０ｍから４０ｍぐらいドライミストが広がっていくという形になっております。","id":"exchange-010"},{"speaker":"土井委員","kind":"質問・要望","question":"これからずっと維持をしていくとしたらどうなるのかな、わからないのか、少し聞かせていただきたいというのが１点です。これがここに書いてある４００万円というのは、それらを含めたものがどうだったのか、そこら辺をちょっとお伺いしておきたいというふうに思います。","respondent":"田中環境課長","answer":"区のヒートアイランド対策を進めていこうというところで方向性が一致しましたので、いろいろ、ほぼ４００万円ということでやりました。その後もすぐ壊れる機械ではありませんので、できるだけ系統的に運用して、環境教育等を含めて活用していきたいというふうに考えております。","id":"exchange-011"},{"speaker":"土井委員","kind":"質問・要望","question":"実験的な意味では終わりですから実施をどうするかという話になる、学校ですから、そういうことも含めてご検討いただければありがたいと思います。やっぱりせっかくやるんですから、ちょっと宣伝もしてあげないとかわいそうかなという気持ちなんで、どうなっているんか尋ねました。","respondent":"田中環境課長","answer":"それから、ホームページ上等のそれぞれの建材について、詳しい説明がそれぞれの会社のホームページに飛ぶようになっております。なお、明治大学のローカルエリアコミュニティシステム研究所という協同の部分では、そういう取り組みをするということになっています。","id":"exchange-012"},{"speaker":"本田委員","kind":"意見","question":"１,０００万円ぐらい増えているわけですが、これはどういうことなのかというのが１点と、大変新規事業としてすばらしい事業だと思うんですよね。これは２３区とか、東京全体をどう涼しくするかと、あわせてお尋ねしたいと思いますとの意見を述べました。","respondent":"田中環境課長","answer":"平成１８年度から行われておりまして、この８月１日からも第２回の屋上緑化と遮熱塗料の公募が始まるということになっております。ということで、全体としていろいろな形を組み合わせながら全都的にヒートアイランド対策を進めていこうということになっております。","id":"exchange-013"},{"speaker":"本田委員","kind":"質問","question":"財調関係は何か関係しているのかどうかが１点と、実際どういうすばらしい効果があらわれたということになれば、そういう先のことはどういう議論になっているんか尋ねました。","respondent":"田中環境課長","answer":"建材等の場合の検証後の対応ですが、まだ遮熱塗料については技術革新が非常に進んでおりまして、まだ検証段階です。普及啓発の部分でもっと取り組んでいきたいというふうに、ホームページ等を含めていろいろ取り組んでいきたいというふうに考えております。","id":"exchange-014"},{"speaker":"本田委員","kind":"質問・要望","question":"こういう新しい塗料や建材の効果が直接にあらわれれば、非常に幅広く役に立つ材料として使い道があると思うんですよね。大変お金のかかる話でもあるし、裏づけを深めながら要望をしていくということで、そういう要望をしていっていただきたいということをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"２カ所ぐらいやっぱり保水性の舗装だとか、中間のまとめ的なものがあれば、ちょっとあわせてこの機会に伺いたいなというふうに思うんですけど。自治体として区民の生活に非常に影響のある問題ですから、そのあたりの決意みたいな思いをちょっと伺っておきたいなと思ったんですけど、その２点。","respondent":"田中環境課長","answer":"手元に資料がありませんが、遮熱塗装のほうは効果があるのかどうかというようなところで、所管の管理工事課のほうで検討した上で。効果がはっきりすれば普及啓発に取り組むということですので、全部が実験ということではありませんので、よろしくお願いします。","id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"ちょっと改めて確認したいんですけど、実際の生活、品川の事業として積極的に取り組んでいただけるように改めてお願いをしておきたいと思います。","respondent":"田中環境課長","answer":"資料のゆたか商店会の下のところにあります「平成１７年度保水性舗装と遮熱舗装の実証実験を区で行い、八潮での実証実験のことですので、これを踏まえましてゆたか商店会の保水性舗装の本格的な整備が行われたということでご理解いただきたい。","id":"exchange-017"}]},{"id":"topic-03","title":"の打ち水大作戦","agenda":"の打ち水大作戦","exchanges":[{"speaker":"南委員","kind":"質問","question":"説明会で出た意見というのは全然なかったんでしょうか。どんな内容のご意見があったのか、ちょっと説明を求めました。","respondent":"中山資源循環推進課長","answer":"私どもと、清掃工場の説明をやるのを基本のパターンにしておりますが、基本的にはよく理解できたというふうなお声が出ていました。いわゆるごみとして出すのかというような、品目について、分別変更後どういう形になるのかというご質問が結構多く出ております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"それから、モデル地区では全世帯の方々に２回されたということ、今までに比べると、すごく精力的にやっておられるなということはよくわかりました。そういう関係のご意見というのは、されていなかったんでしょうか、ちょっとあまり考えられないんですけど。","respondent":"中山資源循環推進課長","answer":"清掃工場の対応というのはどうなのかというふうなこと、特に最初のころにリサイクル関係の団体の方だとか収集団体の方々にご説明している際には。いろいろと考え方、収集面をかなり丁寧に説明しているので、それらを聞いて。","id":"exchange-019"},{"speaker":"南委員","kind":"意見","question":"中身が変わったり、区民の生活に関連して一部変わったりするときは、ある程度大変かもしれないけども、そういう説明会に出向いて区民の皆さんにわかっていただくという、理解というのかしら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247239?Template=document&Id=2464#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":20173,"voices":66}},{"id":"h18-20060725-7","meetingId":"h18-cm07","date":"2006年7月25日","dateIso":"2006-07-25","committee":"厚生委員会","time":"午後１時０４分～午後４時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の説明で、この辺のところがイメージできないので教えてほしいと求めました。介護サービス情報にかわっていくにあたって、どのような形になっていくのかというところを教えていただけないか尋ねました。","respondent":"上山介護保険担当課長","answer":"調査員養成研修につきましては、東京都での対応になるかと思います。今回の制度化された介護サービス情報を活用しながら、区のサービス向上の仕組みを本年度も引き続き検討するというのが今の流れの中です。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"介護サービス情報の公表は東京都がやるということですけれども、調査員２名というのは区内の調査をすることに対して２名ということになるのか。事業者に年に１回義務づけということになっているので、中身も含めて、わかるように説明をお願いできないか尋ねました。","respondent":"上山介護保険担当課長","answer":"介護サービス情報の公表ですけれども、まず公表の内容が２点大きく分けてございまして、基本情報と調査の情報になります。介護サービスを利用される利用者とか家族の方々が選択しやすいようにということで、介護サービス情報の公表の制度が今年度からスタートしたものです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５３ページの別表第一に項目が載っていますけれども、その後も含めてなのか、この辺の中身がわかったら教えていただきたい。介護サービス情報の公表に移していくという形になっていくのでしょうか、その辺のところが決まっているようでしたら教えてほしいと求めました。","respondent":"上山介護保険担当課長","answer":"こちらでつかんでいるところですと、調査の予定月が報告を受けた後の１カ月後ぐらいで、公表の予定月とすれば平成１９年３月と聞いているところです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、私もいろいろな施設にお伺いしてお話をお伺いするにつけ、本当に現場の皆さんは頑張っているなという感じがするんです。現場では、今の現状を改善させていくというところでは、区としてその辺のところはどのように考えているのかお聞かせほしいと求めました。","respondent":"上山介護保険担当課長、木下福祉高齢事業部長","answer":"介護サービス情報の公表の目的については、私からお答えいたします。被保険者あるいは利用者がよりよいサービスあるいは事業所等を比較検討しながら、適切に選択することを支援するために設けられたものです。 経営側でよりよいサービスをするためにどうすればいいかということを常に見直しと改善をしながら、その部分については鋭意努めていく必要がある。区内の法人については、そのことについての認識はあると理解しています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、職員はそういう中でも必死に頑張っているという状況がありますので、賃金を下げるわけにいかないけれども経営は厳しい。現場の努力だけではどうにもならないという状況があるのではないかと思いますので、その辺のところを国に対して言っていただいて、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"「サービス」というのはどういう定義を持ってサービスの向上と言っているのか確認させてほしいと求めました。１２ページに在宅サービスを中心にと書いてありますが、もしくは本人を含めた周りの環境の調査も入るのか、その辺を教えてほしいと求めました。","respondent":"上山介護保険担当課長","answer":"若干説明を省略させていただいたところがありますので、仕組みの考え方で四つほど掲げてあります。家族もある程度視野に入れつつ、かといって質問は多くはできませんので、そういった中での検討になるかと思います。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"逆に、あれもやってほしい、これもやってほしい、家族がいるのにやらなければいけないという、在宅サービスもいろいろな意味合いがあると思うんです。そこまで考えた中で、どういうことがサービスなのかということは、きちんと品川区の考えがあるのかどうか、その辺をお聞きしたいと思います。","respondent":"西島障害者福祉課長","answer":"二つ目は、自らの努力だけでは自立した生活を維持できない場合、社会連携の考えに立った支援が必要です。そういう考え方が自立支援という考え方ですので、その中で連携した福祉サービスを提供していくという考え方で、品川区は進めているところです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"もう既にわかっているということでやっているのではないかと思うんですが、意外とそうではないような気がするんです。１８ページに一部の意見の中にも、その辺を今後品川区としてはどのように進めていかれるのか、最後にお聞きしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"やはり本来あるべき求めている姿の部分についての認識を、啓発あるいはケアマネジャーのお知らせを含めて確認していくことが非常に大事かと思います。そこのところで、利用する側とサービスを提供する側の共通認識を打ち立てる。","id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１２ページの介護サービス情報の公表のところで、障害者の福祉の関係がこの中にどう含まれているのかというのが１点。１３ページに品川区標準の見直しの終りのほうに、どの部分が改善されて盛り込まれていくのかお聞かせほしいと求めました。","respondent":"西島障害者福祉課長","answer":"障害者についても、障害者自立支援法が軌道に乗っていく中で、こういった考えが将来出てくるということは予測されるところです。１７年度にセルフチェックを行いまして、このセルフチェックを進めてきた中で構築していきたいというのが平成１８年度の一つの進めて方です。","id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問","question":"介護サービス情報の公表には、障害者のところまでは公表が至っていないというところでは、品川区内の施設サービス向上委員会の役割という意味で、引き続き同じような状況で公表されるということなのか尋ねました。","respondent":"西島障害者福祉課長","answer":"実施している側、それから利用する側というのは、必ずしも受ける情報はイコールではないということもあります。プライバシーの問題がありますけれども、その辺を十分配慮しながら必要な情報については、できるだけ出していきたいと考えているところです。","id":"exchange-010"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"三村委員","kind":"質問","question":"今の報告の中で、子宮がんとか乳がんの検診率が若干下がっているというお話があったのですけれども、原因についてはどのように把握をされていますか。ここのところよく聞くのですけれども、なかなか受けにくい仕組みもあるのではないかと思うんですけれども、その辺のところについてお伺いできますか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"一つは、受診間隔として２年に１回という形で、検診方法が変更されたということ。今後、受診率を高めていくことが課題と考えております。","id":"exchange-011"},{"speaker":"三村委員","kind":"質問・要望","question":"２年に１回という間隔についてですけれども、２年に１回に変わった理由とか背景とか、その辺について教えてほしいと求めました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"そもそも１年に一度という間隔自体が、がんを発見するのに最適な間隔かどうかというのは、検討を要する事項でございました。最近の医学的見地からわかってまいりました関係で、２年に一度という間隔に変更された経緯があります。","id":"exchange-012"},{"speaker":"三村委員","kind":"質問","question":"その傾向というのは、詳しく年齢別だとか大くくりの平均値ということですか。高齢者になればなるほどがんの進行がゆっくりになっていくから２年に一度で大丈夫でも、若い人が２年に一度だと、その辺についてはどうか尋ねました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"ただし、これは発見されたがんが進行がんで、死亡までに至る期間が短いといったときによく使われる話です。数年間進行がんになるまでに猶予があるだろうという意味合いで、例えば２年程度間隔を置いて検診しても、十分に早期発見ができるという意味合いです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今年から３４歳からということになったのでしょうか。その辺の年齢の変更をされた背景、また今回下げられた背景、そこのところについて教えていただけないか尋ねました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"医学の検診方法の発達とか専門家の研究を待って、それについての対応を決めようということで４０歳ということで始まりました。今回、今後成果をよく検討いたしまして、今後さらに若い世代の検診を実施すべきかどうか検討していくべきだと考えております。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"若い方は発症すると早いですから、命にもかかわる問題で、前は２５歳以上ということでされていたので、今回若干下げたということでは評価できる問題だと思うんですが、さらに年齢を下げて、多くの方が受けられるような検討をぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"三村委員","kind":"質問・要望","question":"先ほどの質問に関連してですけれども、厚生労働省が４年に１回、ぜひ委員会に資料として出してほしいと求めました。以前のデータを見ると、３０歳代の女性でも死亡原因の１位ががんですので、ぜひがん検診の年齢の引き下げなども検討してほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"成人病が生活習慣病と名前が変わってきた経緯と、不健康な生活習慣をしたため生活習慣病になるという、この辺の定義ですか。増加しているという、その辺をどう見て今後の対策をされていくのか、大きなところでお聞かせほしいと求めました。","respondent":"川口品川区保健センター保健サービス課長","answer":"一番最初のところでご説明していますけれども、まず背景としましては、年齢にしたがって起こる病気ということで三大成人病という概念がございました。","id":"exchange-017"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"自分がどのような状態にあるのか、なるべく早い期間に健診を受けて知らせてもらうということが大事だと思うんです。実際に区民健診を受けてデータが出た段階で、注意を喚起するような手立てはどのように取られているのか、具体的に教えてほしいと求めました。","respondent":"川口品川区保健センター保健サービス課長","answer":"どのようなフォローをしているかですけれども、当然受けられた方には健康相談事業を行ってありますので、健診に基づいて個別に指導をしています。","id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問","question":"保健所で健診を受けて、指導を受けていらっしゃる方は安心と思うんですけれども、概要の１２０ページを見ましたら、４０歳以上の区民で勤務先等で受診機会のない者と書いてありますけれども、勤務先で受診していない方は把握されているのか、その辺の方たちは全然把握されていないのか尋ねました。","respondent":"谷田部健康課長","answer":"私どもの対象人口率で割返していきますと、純粋に対象者の人が区民健診を受けているのは５割前後です。私どもは数値の上では把握していますが、私どもは対象としてつかんでございませんので、それについては数字の把握はできません。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど、最後のページの「健康日本２１」における代表目標項目ということで、いろいろ数値を出していただきながら説明をいただきました。それを具体的に減少させるために、データも含めて、その辺のところが出されているかどうか教えてほしいと求めました。","respondent":"谷田部健康課長","answer":"国の「健康日本２１」と違いますのは、私どもは数値目標でどうのこうのではなくて、具体的な施策の中で区民の健康管理を着実にやっていこうです。当然、毎年度実施計画をローリングする過程の中で、効果的な施策を展開していくということをあわせてやっているです。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"国の段階では目標数値を持っているということであるにも係わらず、なぜ品川区ではその辺のところを持たないかということ。循環器病、健康診断を受ける人の増加というところでは、どの辺に書いてあるか教えていただけたらと思います。","respondent":"谷田部健康課長","answer":"食の健康で言えば、従来にも増して食育に重点を置いた事業も随分力を入れてまいりましたので、一定の効果が出てきていると思ってあります。それから、２点目の質問の意味がわからなかったので、もう一度質問をしていただければと思うんですが。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"例えば二次予防の循環器病の健康診断を受ける人の増加のために、具体的にどのようなことを計画しているかというところでは、具体的に具体化されているか教えていただけたらということです。","respondent":"谷田部健康課長","answer":"数値として、例えば５年後に区民健診受診者を７０％達成とか、８０％達成という形での計画は載せてございません。健康増進法に基づく区の健康増進計画ですので、このプランに従ってさまざまな具体的な施策を、予算ですとか実施計画の中で具体化しているです。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"対策を取られているということは評価しますし、ますますそのようなところは充実をさせていただきたいと思うんです。それは品川区がどうのこうのという中で、単純に解決できるものはないですけれども、そのような背景に関しては、どのようにとらえていますか尋ねました。","respondent":"谷田部健康課長","answer":"私ども一般保健衛生行政を担っている分野です。効率的にやっていくということで、私ども区民の一人一人の健康の維持増進にこれまでも努めてきましたし、これからも努めていくという考えです。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"中断をさせないという取り組みがすごく大事になると思うんです。その後も継続した治療が大事になると思うんですが、今の事業についてはどのような実態になっているのかお聞かせほしいと求めました。","respondent":"谷田部健康課長","answer":"保険者が行う特定健診、特定保健指導との関係が出てまいりますので、現在の健診と保健指導を含めた組み立て直しの検討が始まった段階です。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本人も問題意識を持ちやすいですから、必要な制度であれば、使いやすい制度に変えていくようにしてほしいと求めました。その辺のことについて方向が出されたときには、ご説明をいただけたらと思いますけれども、どうか尋ねました。","respondent":"谷田部健康課長","answer":"と言いますのは、保険者と言いますと区で言えば国民健康保険の保険者が国保年金課が所管になります。保険者として考えれば区民委員会所管、今まさしく検討をしている最中ですから、今後の議会に対する報告も検討をさせていただきたいと思ってあります。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"事務事業概要の１３７ページの健康学習に関してですけれども、数多くやっていただいている中で、例えば高脂血症予防教室はなくなったのですか。平成１７年は６,４０９人、これからどのように考えていくのか、その考え方だけ。","respondent":"川口品川区保健センター保健サービス課長","answer":"１点目の高脂血症予防教室ですけれども、ただいまご指摘のように平成１６年から実施してございません。先ほどもご説明をさせていただいてありますけれども、老人保健法の６事業の中の健康教育ということで、高脂血症はこの年度から終了しています。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"何か理由をつくって行かないという状況があると思うので、その辺はこれから場をつくって啓発していく形をお願いしたいと思います。骨折予防教室、これは介護保険絡みの健康のほうに徐々に移行していくのか、それともこのまま続けていくのかとの意見を述べました。","respondent":"川口品川区保健センター保健サービス課長","answer":"ただいまの介護保健法との絡みですけれども、今年度から６５歳以上の骨粗鬆症予防教室は高齢事業課の事業ということで、区としてはすみわけをさせていただいてありますけれども、一部保健センターに執行委任ということで今年度実行しています。","id":"exchange-027"},{"speaker":"西本委員","kind":"意見","question":"それをいかに啓発していくかということだと思うんです。今、こういう病気になると家庭がこうなってしまうとか、後遺症が残るから早期発見が必要だというようなリーフレットなどをつくったことがありますかとの意見を述べました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"「健康日本２１」とか、「プラン２１品川」もそうですけれども、あまりマイナスの面を出すという形のものは数が少なくなっております。","id":"exchange-028"},{"speaker":"西本委員","kind":"意見","question":"もう少し自己管理をしなければいけない、やはり２年に１回か２回は自分で健康管理してみようというものができたらいいと感じました。申し上げておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"三村委員","kind":"質問・要望","question":"それから、学校で子どもたちにも家庭でどういった食事をとっているのか、短期間でもいいですけれども調査をしてみてはと思うんです。それから所管がまたがるかもしれないので連携ができるかどうかわからないですけれども、ぜひ検討していただきたいと思うんですけれども。","respondent":"谷田部健康課長","answer":"品川地区と荏原地区では、食の相談会も栄養士会の皆さん方がいろいろな相談を受けてやっていただいているわけです。今、そういったことも食が健康にいかに大事かという一つのきっかけになるとすれば、そういうことも事業の中に生かせるかと思ってあります。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者自立支援法が４月から始まりましたけれども、その対策についての説明は厚生委員会にされていないのです。通所の場合は３,０００円とか、その制度について委員会に報告を次回でもしていただけたらということで希望させてほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"今、先般本会議の中でご質問をいただきまして、ホームヘルプの３％の拡大と通所施設について一律３,０００円の減額ということで答弁をしています。その内容が基本的に現在の品川独自策のすべてになりますので、それでご理解をいただければと考えています。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285470?Template=document&Id=3152#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":34677,"voices":75}},{"id":"h18-20060725-8","meetingId":"h18-cm07","date":"2006年7月25日","dateIso":"2006-07-25","committee":"建設委員会","time":"午後１時０３分～午後５時１４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件整理しています。","topics":[{"id":"topic-01","title":"平成１８年請願第１１号、「（仮称）中延６丁目新築工事」建設に関する請願","agenda":"平成１８年請願第１１号、「（仮称）中延６丁目新築工事」建設に関する請願","exchanges":[{"speaker":"井上委員","kind":"質問","question":"この請願事項に対しての区の考え方はお聞きしたわけですが、結構この施設は大きいところですから、区はこの辺ではかかわられているのかどうか。その辺のところはどういうふうに、先ほど日にちを追って説明をされましたけれども、この辺の状況はどうなっていますか。","respondent":"齋藤住宅課長","answer":"説明が足りなくて申しわけございません。あるいは我々も立ち会いますので、任意の話し合いの場として話し合いを継続されませんかと提案をさせていただきまして、こういうことです。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"工事が本当にできるのでしょうかという、３時間の時間がかかるというのでは、どういうふうに区としては道路交通も含めて区民への生活に及ぼす影響というものを考えているんか尋ねました。","respondent":"齋藤住宅課長","answer":"基本的には、道路の管理につきましては警察署所管となります。時間、条件づけされて許可をされる、こういうことです。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"だから、そのことに対して品川区としてはどういうふうに考えていらっしゃるんか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"きょう視察で通っていただいた道路は、ちょうど道路中心線が区界になっています。道路法の規定によりまして、大田区と池上署、交通警察のほうとで許可をおろしたというふうに我々は聞いております。","id":"exchange-003"},{"speaker":"井上委員","kind":"意見","question":"そういうところは大田区の池上署と大田区であるという縦割りというか、自分たちの権限が及ぶところではないということではなくて、そういうことをどういうふうに考えているのかなということを説明するよう求めました。","respondent":"岩田まちづくり事業部次長","answer":"その権限がない者が権限のある者に対して口を挟むということは、これは基本的にできません。一番小さな施工可能な杭打ち機で、こういう規定になっておりますから、その規定の中で交通警察によって許可されたというふうに聞いております。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"こういう道路に関しての許可とかというのは、敷地は品川区ですから、そういうことの問い合わせなどのやりとりなんかはされているのか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"ただし、それには通過交通や、あるいは歩行者への影響が最も小さくなるように、そういう配慮が当然必要となってまいります。何時ごろ、これは施工業者の使命ですから、品川区としても周辺住民へのＰＲと理解を十分得て施工するようにという行政指導はしています。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"建築主のところでちょっと確認したいんですけれども、東京建物株式会社と中延開発特定目的会社というところで建築主が２者ということなんですけれども、説明責任のところを改めて教えていただきたいんですけれども。","respondent":"齋藤住宅課長","answer":"中延開発特定目的会社のペーパーカンパニーについて実態はありません。要するに、東京建物株式会社が出資会社になっておりますので、事実上も１社です。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問・要望","question":"わかりました。ペーパーカンパニーということですから、建築主が説明をどこまでされているのか、把握している範囲で教えていただきたいと思うんです。","respondent":"齋藤住宅課長","answer":"風の問題については、何度か住民説明会で説明があったというふうに聞いております。このデータも説明しております。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"説明会を何度かされたようですから、当然その辺の一番の、区としてどこまで把握しているのかというのを確認をさせていただきました。ぜひその辺は充実した説明をやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"第２種高度地区、容積率が２４０％という、建ぺい率が７０％のところ約半分ぐらいですよという数値というふうに読み取れます。それは１つの会社、１社ですから、区とか都による補助金等々は一切受けていないということでよろしいのか尋ねました。","respondent":"片田建築課長、齋藤住宅課長","answer":"その場合に、建物の周囲に空地を設けて、空地の評価をいたしまして、通常よりも大きくといったような事例もあります。建築審査会等で地域住民への事前の説明を含めて、今回の計画については… 補助金のほうもないというふうに聞いております。","id":"exchange-009"},{"speaker":"松澤委員","kind":"意見","question":"普通は東京都と品川区と同時に出されたりするんですけれども、そんな意味でちょっとまどいがあるんですよね。既存建物よりも悪くないという説明を受けましたし、どうも私どもの会派から２人の紹介議員が出ていますから、いろいろ困っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう違法行為がそこであったのかご説明いただいたのと、それに対して区はどういうふうに対応したのか、あわせてご説明いただきたい。","respondent":"齋藤住宅課長","answer":"平成１７年度に池上署が交付をした許可証そのものを持っていなかったというふうに聞いております。その許可証を持っていなかったことについて区として指導申し上げることはありません。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"直接の監督は大田区になるのでしょうか、警察なんでしょうか、常識を超えている本当にひどい行為だなと思うんですよね。私は絶対許されるべきことではないと思うので、許可証を持たずに工事を入れるという行為に対しては、区はどういうふうに対応するのか尋ねました。","respondent":"齋藤住宅課長","answer":"先ほど次長も申し上げましたが、警察の権限でございまして、区としては何か物を申したり、直接言うようなこと、命令するような権限はございません。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"５ページ目の評価結果のこのシミュレーションの結果、この濃い緑のランク３というのは、どのぐらいの風の強さを指すのでしょうか。歩行者に対してどういう影響を与える風の強さがこのランク３に当たるのか、ちょっとそこが、そこを教えていただけますか。","respondent":"齋藤住宅課長","answer":"ランク２のエリアであれば、さっきの強疾風という日が２日ほどありますが、ランク３は５日以内です。ここだけ濃く出ていますので、ちょっとわかりにくいんです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"それに対して区はどのように考えているのか伺いたいんです。僕が言いたいのは、とても今までない風が吹くということをこれは示しているのではないのかと思うんですけれども、その点はいかがか尋ねました。","respondent":"齋藤住宅課長","answer":"３のところがありますが、ここで風の影響で転んだり、骨折の方がいるのかということになります。ですから、風害は基本的にはないというのがこのデータの評価です。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"日照のことを伺いたいんですけれども、特段悪くなるわけではないというお話があったかと思うんですけれども、それは面積で見たんですか。どこからどういうふうな、数値の説明があれば教えていただきたいと思うんです。","respondent":"齋藤住宅課長","answer":"日中の１０時から１４時まではむしろ影の部分が小さい、前後で上下を比較しますと、いわゆる直射日光が当たらない時間はそんなに変わりません。直射日光は当たりませんが、陽光採光上は支障はない程度のものだということがこのデータからわかるということです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"８から７になる、その辺を教えていただきたいのと、「寝たきりの母にとってお日様がどれほど嬉しいか。この問題は利用者の問題とともに、特養ホームは区の財産ですから、品川区にとっても財産を左右しかねない問題だと思うんです。","respondent":"齋藤住宅課長、片田建築課長","answer":"ちょっとこれも難しいんですけれども、直射日光が入らない時間は８時と１６時の時間に若干増えます。そして、電気をつけないと生活できないということではない。 その隣地の境界線から５メートル、１０メートル、それが基本的な法規制の中で十分クリアするという状況で今認識しております。そこにおける８時から夕方の継続的な日当たりの状況を調べた、こういうような判断です。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここの施設がどういう性質のものかとか、そこをどう理解しているのか、そこだけちょっと教えていただきたい。ただ、そこに暮らしている人の気持ちを、利用者の気持ちをどう理解しているのか、そこだけ最後に聞かせていただきたいんです。","respondent":"岩田まちづくり事業部次長","answer":"この請願を出された地域の方のお気持ちというのは、非常にそれはありがたい、温かいご支援だとは思っております。したがって、私どもとしても、こういった施設配置に配慮していただいたというふうに理解しています。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"確認","question":"先ほど説明にあったのかよくわからないんですけれども、ちょっと確認したいんですが、これの実態がどうなのかということを確認しておきたいんですが。通常いろいろ工事が始まる前は、この場合どうだったのかということを確認したいんです。","respondent":"齋藤住宅課長","answer":"事業者のほうが工事を焦ったか性急に進めてしまいまして、因果関係を証明できないから、これで信頼関係が損なわれたのは事実です。そして、補修が済んだら、建築協定を結んで重機を搬入する、これが今の状況になっています。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっとやっぱり工事を始めるときのいわゆる常識ですか、ちょっとないかなという感じがするんですけれども。ランク２だとか、緑色のランク３のあたりは、実際は何メートルになるのかということがわからない。","respondent":"齋藤住宅課長","answer":"ちょっとこれも説明しづらいんですけれども、無印は今のところランク１なんです。１２階のビルが建ったがために、考えがそういう、ちょっと難しいんです。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"なかなか風のほうがどういうふうに証明するのかというのは非常に難しいんですよね。3)のところの資料で、よく私も経験があるんですけれども、そういう状況が実際にこの資料からわかるのか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"それを防ぐために２階、３階の部分を少しボコッと張り出して、そういう意味ではかなり精度を上げたものだと思います。５日程度出現する可能性が出る、ランク３のところがここで出ますよということですから、一般的な評価の仕方だろうと考えています。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ある意味ではそれで終わりということになるわけですから、じゃあ、このお墨付きというのはどうなってしまうのでしょうか。何かあった場合に責任をとるようになるのか、それとも大成建設のほうが責任をとられるということになるのか、そこら辺のところはどうなんか尋ねました。","respondent":"齋藤住宅課長","answer":"説明会でのご質問で、東京建物が日本で権威のある大成建設のエコロジー本部に風環境に関する調査を依頼したということです。風が吹いたからけがをされたからといって、当然には東京建物に損害賠償ということは、そういう関係にはありません。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問・要望","question":"これで責任をとってくれるわけ、それがなければ、やっぱり何だかよくわからない。せっかくそういう要望にこたえたんだったら、そこまでやっぱりしっかりかみ合った資料じゃないと話にならないんじゃないかと私は思うんです。","respondent":"岩田まちづくり事業部次長","answer":"現行法では、もし将来こういうことが起きた場合に、ます業者側もきちっとまじめに住民の方にうそ隠し事なくきちっと説明をして誠意を見せてくれと。それから、住民の方も、門前払いみたいな形ではなくて、説明はまずちゃんと聞く。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問・要望","question":"もうこれは住民感情としては当然ですから、それ以上の努力を東京建物がしないと、やっぱり東京建物にしっかり言っていただきたいなと思います。これは要望として終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"藤田委員","kind":"質問","question":"ですから、区もやっぱりこの建物については神経を、所管がこれは福祉のほうになるわけですね。ですから、区も地域住民の１人なんだということで、やっぱり話し合いにきちんと応じる必要性があるのではないかなと私は思います。","respondent":"齋藤住宅課長","answer":"工事協定が整えば、重機を搬入して、山留め、土留めの工事をして、それからだんだん上げていって、２年８カ月ぐらいで上げたいというふうな意向を持っておりました。","id":"exchange-024"},{"speaker":"藤田委員","kind":"質問","question":"相当な車が、このマンション建設に携わるそういった車が入ってくるわけですから、非常に住民の皆さんに不安がある。この行政指導をしていくというふうに一番最初にありましたけれども、これは現時点では、区としてはどのような対応をされているんか尋ねました。","respondent":"齋藤住宅課長","answer":"先ほどお示しした資料の３枚目にありますように、このような形で３７％しか容積率を使っておりませんので、この部分が緑地になります。高さの上限がありますので、いろいろ考えながら、今のお話をしていきたいと考えています。","id":"exchange-025"},{"speaker":"藤田委員","kind":"質問・要望","question":"これはどういう対策をとればいいのか、植林がいいんだというような現時点の判断ですので、ぜひその辺も含めて対応していただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"大西副委員長","kind":"質問","question":"今度建てた場合は南側に寄るので、およそ日照については変わりがないという解釈でよろしいでしょうか。こういった部分、この高齢者施設の方々が車いす等で行って日向ぼっこをしてとか、そういう形のことにできるのかという点に関していかがか尋ねました。","respondent":"齋藤住宅課長","answer":"開放するということならあれですけれども、中は敷地内ですので、こっちの緑地のところは入れません。ただ、連関しておりますので、オープンスペースになっているということです。","id":"exchange-027"},{"speaker":"大西副委員長","kind":"質問・要望","question":"日照という問題についてのことは、随分ここでは改善され、この部分ではほとんど影響はそんなにないという説明をされているのでしょうか。区の仲介というのかな、その部分での事業主と住民との間の中で、この説明はきっちりとされているのか尋ねました。","respondent":"齋藤住宅課長","answer":"区が立ち会った話し合いの場ではこういう話はしませんでした。この資料で事業主は説明をした、説明が難しいのと、こういう説明をしたんだけれども不十分だと。","id":"exchange-028"},{"speaker":"大西副委員長","kind":"質問・要望","question":"あの部分を私も１周回ってみて思いましたが、およそ１２階が建つということで、いろいろな部分があろうかというふうに感じます。私は品川区ですから品川区住民の安全、両者がよく理解されて、合意形成がなされることに品川区として努力していただくことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"井上委員","kind":"確認","question":"済みません、ちょっともう１つ。先ほど確認申請を出し直してほしいということで確認審査請求が出されていて、これは継続している間に工事というのは進んでしまうものなんか尋ねました。","respondent":"齋藤住宅課長","answer":"建築確認の申請を取り消す審査請求があったとしてもとまりません。やめようとすると、裁判所に仮処分か何かをして認められない限りは工事をとめる権能はありません。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"建築審査会が進んでいるときに訴訟にはできないんですか。これが継続していたら、とめるために裁判ということは、これを取り下げかなんかをしない限りできないということか尋ねました。","respondent":"片田建築課長","answer":"通常、前置主義という言葉を使っておりますけれども、行政訴訟のためには審査会の判断を受けてからでなければ行政訴訟をすることはできないと。","id":"exchange-031"},{"speaker":"松澤委員","kind":"質問","question":"さらに１点お聞きしたいんですけれども、不調に終わったあっ旋の中で、１階を削るという話がありまして、それは当然、日影にかかるもののところを削るという解釈でよろしいんか尋ねました。","respondent":"齋藤住宅課長","answer":"６階にしてしまうと事業採算が整わないので、下げられるぎりぎりのところを下げてみせたというのが事業者の提案です。住民の要望による最低限の対応、住民の方も納得がいかなかった、こういうことです。","id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"まだまだ業者側のほうでも解体工事の補修が済んでから工事協定を結んでから重機を搬入したいという話を伺っていますし、そんなことを勘案すると。今回は継続にしていただければいいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"藤田委員","kind":"意見","question":"私も、今、住民の皆さんと業者の方との中に話し合ってというのがいいのかどうかわかりませんが、きょうのところは、もう少し成り行きを見守ってみたいということで、継続ということで話がありますので、私もそれでいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"やっぱりこれは結論を出していくべきではないかというふうに私は思います。議会の態度というものをしっかり出す必要があるのではないかと思いますので、私はきょう結論を出すということで主張したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"ここは駐車場８４台を設置することで、高さも１２階という、結論を出していただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"大西副委員長","kind":"意見","question":"要するに、風害は特養についてはなくなりました、そして随分外れたところに発生しますということがまず理解いただいているか。１カ月半も、私ども委員会の判断をすべきではないかというふうに考えますので、継続するべきであると考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"}]},{"id":"topic-02","title":"の区営自転車等駐車場の指定管理者募集","agenda":"の区営自転車等駐車場の指定管理者募集","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"第一次選考委員会、第二次選考委員会、それぞれありますけれども、第一次と第二次と、主に何を重点に審査をするかということ。審査の中身をちょっと教えていただきたいのと、この外部委員というのはどういう方なのか、あわせてご説明ほしいと求めました。","respondent":"松嶋交通安全担当課長","answer":"ヒアリングを実施いたしますけれども、最終的にそういったものをひっくるめ合わせて、指定管理者候補者を選考するというものです。これも最終決定をしているわけではございませんけれども、一応、公認会計士の方にお願いをするつもりで予定しております。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"１人は、それはわかると思いますので教えていただきたいのと、その次に議会の議決になるわけですよね。指定管理者事業計画書、ありますけれども、これは議会に出されるのかどうか教えていただけますか。","respondent":"松嶋交通安全担当課長","answer":"１点目の選定委員会、確かに全く真っ白の状態、そういうことは現在のところでもございません。当然、第４回定例会のときにいただくようになるかと思いますけれども、その審議にわかりやすいような最小限のものは当然資料として出すつもりです。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"私、同じ資料が提出されなければ、公平かつ適正な議会の議決とは言えないのではないかということを伺いたいんです。私はやっぱり議会としても公正、そして適切な判断を下すに値する資料を議会に出すべきだと思うんですけれども、いかがか尋ねました。","respondent":"福田まちづくり事業部長","answer":"このことに必要な資料をお出しをするということでございまして、二重の審査をするということは法律の予定しているところではございません。これは当然でありますけれども、委員会にご提案をし、審査のための資料としてご提出をする予定です。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"議会として独立して議決として求められている以上は、議会が評価するわけですから、きちんと資料を出すべきだと思います。最後に、それぞれの委員が十分に審査ができるだけの資料をぜひ出してほしいと求めましたけれども、その点だけご答弁ほしいと求めました。","respondent":"福田まちづくり事業部長","answer":"それと、先ほど申しましたように、選定等に関する審議に必要な経過とか対応については、この当該委員会に提出をするというふうに考えております。それらの資料をもとにしてご審議をいただき、議決いただければ大変ありがたいと考えています。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"どういう選考でしたんですかと区民の方に問われたときに、私たちは説明責任を果たせないわけですから、要望に当たっては。そういうことからも、ここの部分についてはぜひ出していただきたいなというふうに考えていますが、いかがか尋ねました。","respondent":"福田まちづくり事業部長","answer":"委員会の意思として執行機関に提出の要請があれば検討します。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"これがまた５年後にはどこかの業者に変わるときには、そういうふうにするよりも１社にしたほうがとてもメリットがあるというふうに、そこのところの確認をちょっとさせていただきたいんです。","respondent":"松嶋交通安全担当課長","answer":"確かに委員ご指摘のとおり、これを１社にするのか、それとも施設ごとにやるのか、そういった検討は十分にやってまいりました。そういったところと比較をすればいいわけであって、そういった面も考え合わせますと、メリットのほうが大幅にあったということで１社にしています。","id":"exchange-043"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ぜひ議会で議案として出てきたときには審議できる内容ということで要望しておきたいんですけれども、要望がありますけれども、あわせて私は。ホームページで公表するというふうにしてやっておりますけれども、ちょっとそこのところを考えてお伺いしておきたいんですが、どうか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"公表内容につきましてですけれども、これは基本的には指定管理者として指定された業者、そこがどのような提案を行ったのかというところの部分の公表をする予定です。","id":"exchange-044"},{"speaker":"宮崎委員","kind":"提案","question":"Ａ社はこういう提案だった、Ｂ社はこういう提案だった、もう一度ちょっと確認させてくださいとの意見を述べました。","respondent":"松嶋交通安全担当課長","answer":"これは先ほどご説明いたしましたとおり、ただ１つではなくて、そういったものを公表していきたいというふうに考えております。","id":"exchange-045"},{"speaker":"宮崎委員","kind":"質問","question":"２つほど聞きたいんです。もう１つ、７名か８名くらいで、同じ方になる可能性というのはあるのか尋ねました。","respondent":"松嶋交通安全担当課長、岩田まちづくり事業部次長","answer":"続きまして、選定委員会の公認会計士ですけれども、私はちょっと申しわけありません。公認会計士協会を通じて、そこから推薦をしていただいて、その方を外部委員として受け入れるです。 現在、取り締まり業務は区は直営で、委託業務ですけれども直営で行っております。駐輪場の収益が減るという、こういう経緯になっておりますので、今回はこの利用料金制度をとらないということにした経緯です。","id":"exchange-046"},{"speaker":"宮崎委員","kind":"質問","question":"それだと実際に１回受けてしまうということになると、期限が切れて次を選ぶとき、どういう基準で行くのか。もありますけれども、その代替施設というか、そういうものはどういうふうに考えているのかということを最後に聞いておきたいのですが。","respondent":"松嶋交通安全担当課長","answer":"したがいまして、これは近くに民間の東急の有料駐輪場があります。第二、第三のほうへどのようにしてやっていくか、そういったところも検討の１つとして考えているところです。","id":"exchange-047"},{"speaker":"井上委員","kind":"確認","question":"こっちの業務のほうには入っているのか、確認していないですが、そこを移行されるような心づもりがあるというふうなことはあるのでしょうか。ちょっとその辺を。","respondent":"松嶋交通安全担当課長","answer":"放置自転車の撤去活動、それを指定管理としてやらせることができるかというと、それはなかなか即時強制部分がございまして難しい部分があります。これは今いろいろなところに聞いているところですけれども、明確な回答が返ってきておりません。","id":"exchange-048"}]},{"id":"topic-03","title":"平成１８年８月都営住宅入居者募集","agenda":"平成１８年８月都営住宅入居者募集","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"ちょっと伺います。そこをお願いします。","respondent":"齋藤住宅課長","answer":"事業再建者というのは、中小企業を区内で３年以上経営していて、事業が立ち行かなくなってしまった。そのような方に、事業再生に向けて家を貸していく、こういう制度です。","id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、定期使用というと、そうすると何年ぐらいに決まっているのか尋ねました。","respondent":"齋藤住宅課長","answer":"詳細はいろいろな状況によって違うようですが、５年、１０年までです。","id":"exchange-050"}]},{"id":"topic-04","title":"の（株）品川宅建管理センターを区民住宅および区営住宅の指定管理者に指定すること","agenda":"の（株）品川宅建管理センターを区民住宅および区営住宅の指定管理者に指定すること","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ここを選定にするにあたっても、きちっと公募をするということは、ちゃんとプロセスとして私は踏むべきだというふうに思うんですね。それはあるべき姿ではないと思うので、これはやっぱり報告ということでしたけれども、これはやっぱりおかしいんじゃないか尋ねました。","respondent":"齋藤住宅課長","answer":"人材を確保できないんです。宅建管理センターと区とつき合いがあるからというのではなくて、最大多数、最小コストを実現するという行政目標にかなうです。","id":"exchange-051"},{"speaker":"井上委員","kind":"質問・要望","question":"ここは改善を求めるとか、そういう資料の出し方をしていただきたいというふうに思うのと一緒に、何かしっくり来ない。こういうやり方は私は問題があるということを指摘をして、皆さんのご意見があるのかもしれないですからお聞きしたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"宮崎委員","kind":"意見","question":"選定のそのものの考え方がどうなんだと、やっぱりそもそもおかしいなと、やっぱりおかしいなとつくづく感じるところなんですけれども。そういうことを言うつもりはないんですけれども、これだと全く理屈に通っていないんじゃないかということをあえて言いたいということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"大西副委員長","kind":"意見","question":"ちょっと１点、そのうちその回収のほう、これはどうなっていますかとの意見を述べました。","respondent":"齋藤住宅課長","answer":"回収は裁判所を通さないとできない、こういう関係になっておりまして、財産調査がまず前提です。現在のところ、保証人に請求しても、なかなか裁判費用をかけても回収できていないところはあったということです。","id":"exchange-054"},{"speaker":"大西副委員長","kind":"質問・要望","question":"区民住宅にかかわっているのか、およそ２つのことを言っているのかというふうに想像するんですけれども、その辺はどういう具合なんですか。そして、在籍を確認した場合には、そのこと自体はやっておられるかどうかお伺いします。","respondent":"齋藤住宅課長","answer":"それで、５年、１０年続けますと、大体親御さん、親戚の方なので、滞納されたときには高齢になっております。財産の簡単な調査をしますが、裁判費用をかけてまで保証人から請求して保証人から債権の回収ができそうなところは、今のところ見つかっておりません。","id":"exchange-055"},{"speaker":"大西副委員長","kind":"質問","question":"そうすると、それは募集要項の要件は著しく不適格なものを採用しているということにならないですか。２４０万円というものに対してなさないという、その者がどうして入居できたのかということになって、どうか尋ねました。","respondent":"齋藤住宅課長","answer":"住宅施策の中では、そこまで厳しくは、賃料をその方に出していただくことについてはやることは考えておりません。６カ月以上滞納があるような場合には、先ほどもお話が出てまいりましたように、区としても努力しています。","id":"exchange-056"},{"speaker":"大西副委員長","kind":"質問","question":"ついに入ってから１回も払っていないということなので、１０年とか、その案件についてのことをお尋ねしているんです。引き継ぎはされていないんか尋ねました。","respondent":"齋藤住宅課長","answer":"名前を言うと支障がありますので。この方は退去していただいています。","id":"exchange-057"},{"speaker":"大西副委員長","kind":"意見","question":"その後の請求はどうなっていますかという話です。裁判所を通じてやっているかという話との意見を述べました。","respondent":"齋藤住宅課長","answer":"裁判所を通じて請求しているということは、最低限、四、五十万円かかります。四、五十万円回収できるほどの資力は見つかっていない、こういうことです。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"都市景観、かなり広い概念で、ちょっと伺いたいのは、いわゆる建物の高さの問題とかも含めているのか、それとも観光的な要素に絞っているのか、かなり広い領域なので、ちょっともしお考えがあれば、その辺を含めてご説明いただきたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"私たちの会派のほうでは、再開発、まちの問題、また広町の問題、そうした意味では、都市景観という分野でくくると僕は思うんです。そういう理解でいいのかなということなんですけれども、今のお話だといいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問","question":"その辺のもう少し、私はバリアフリーの視点で出しましたので、ここに入れました。ほかに何かここへ絞っていただくに当たって、出されたことというのはあるんか尋ねました。","respondent":"伊藤委員長","answer":"それから案としては３１日から２日までの行政視察の日程を当て込む中で、案としては、九州を考えました。","id":"exchange-061"},{"speaker":"井上委員","kind":"提案","question":"こういう項目が出た中で、場所を絞らないといろいろなところへ飛べないのでこういう形になったということですね。とてもただ話を行政の方に聞いてどうなんだろうというところがあるので、この辺はどういうところで提案をされているのか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"井上委員","kind":"意見","question":"規模とか、そういうのは、この辺はどうなんでしょうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"中塚委員","kind":"提案","question":"これだけよくわからないんです。施設を見るのに提案した方に聞いてみないと、どういう具合にこれを提案されたのか、今の区政の視察においてそういうふうな必要があるのかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"大西副委員長","kind":"提案","question":"これは私も提案させていただいた１人です。私ども委員会の者にしてみても、学ぶ部分が大変多いというふうに感じており、その部分を私どもとしては意見として申し上げたという経緯がありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問","question":"かなり特殊な契約というんですか、どこが売れているんですかね、運営形態が特殊なんですよね。品川区が学ぶべきものがあると言われればそうなのかもしれませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"中塚委員","kind":"意見","question":"やっぱり肝心なことですけれども、所管事務調査の中で、やっていこうということであれば、いろいろお話も学ぶこともあるでしょうけれども、どうもここだけ行政視察の中で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"藤田委員","kind":"意見","question":"その事業を運営するにはそれぞれどういう苦労があるのかというのを、園長が出てきて、１時間講演したんです。きょう決めないといけないというのであれば、ある程度の枠を正副委員長で決めてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/965541?Template=document&Id=3856#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":53287,"voices":179}},{"id":"h18-20060725-9","meetingId":"h18-cm07","date":"2006年7月25日","dateIso":"2006-07-25","committee":"文教委員会","time":"午後１時０３分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"八潮地区小中一貫校設置の経過報告","agenda":"八潮地区小中一貫校設置の経過報告","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"区側からは八潮での一貫校に早急に取り組んでほしいという声が多数だったということを受けて、改めて読ませてもらって、同時に不安を持っていて。それから、これをもって全体の合意が一貫校でまとまっているというのはちょっと無理なんじゃないかと思うんですが、どうお考えか尋ねました。","respondent":"古里学務課長","answer":"この説明会が終わった後、あるいはそれに至る過程についてるるご説明申し上げたところ、参加者の皆さんから納得をいただいております。その点につきましては、教育委員会としても受けとめ、小中一貫校の中でそういうものを実現していくということを申し上げたところです。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"だけど結果的には五校の統廃合は決定したという上での説明会ですから。第３の八潮地区のようなことが出るんじゃないかと非常に心配をするんですけれども、その辺はどう考えていらっしゃるんか尋ねました。","respondent":"古里学務課長","answer":"品川区が進める教育改革の現在の最先導役としての小中一貫教育の展開のために、それから力強く進めていく必要があろうかと考えております。この辺は今後そうした状況をしっかり見ながら、対応をそれぞれしていきたいと考えております。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"第２、第３の八潮が内陸部のほうで出てくるんじゃないかというのが本当に心配なんですけれども、その辺に対してはどうなんでしょうか。ないと断言できるんか尋ねました。","respondent":"古里学務課長","answer":"こうした現象を注意深くとらえながら見ていくということを考えてあります。それぞれ一貫校ができるところにつきましては、現在の時点からさまざまな分析をし、それから学校と連携して対策をとるということを今検討しています。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"私はあまりこういうことが広がるのは好ましくないと思うんですが、いかがですか。それはそれとして生き残る学校があり、整理されていく学校があるのはやむを得ないのだということなのかどうなのか、そこのところを聞いているんです。","respondent":"長田教育次長","answer":"そういう意味では、小規模校にないよさを選んでいただける親御さんと子どもさんもいらっしゃるだろうとは思ってあります。次の報告になりますけれども、そういった検証の中で、検証と合わせた上で判断をしていくべきなんだろうと考えているところです。","id":"exchange-004"},{"speaker":"築舘委員","kind":"質問","question":"ですから、５月３０日がスタートになったわけなので、それはいろいろな意見があって当然だと。地域は区は一緒だという感覚なわけですから、そういう連携を今後とっていくということは必要なことだと思うので、その点についてどう考えているか。","respondent":"古里学務課長","answer":"教育委員会が考えている今の状況についてできるだけ説明をしていくということが、そのようにしていきたいと思ってあります。それとその過程の中で、９月の前半に予定をしていますが、第２回目の地元それからＰＴＡの説明ということをやりたいと考えていますが。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"人口動向というのはどういう、マンションでの空きとか、八潮に人が集まってくるということも考えに入っているんだろうと思う。子どもさんたちも自然と増えるのではないかという想定もできるのではないかなと思うんだけれども、その辺をどうとらえているのか説明するよう求めました。","respondent":"古里学務課長","answer":"八潮地域の活性化策ということがどのように検討されるかということもありますけれども、そのようなことが起ころうかなとは考えてあります。いずれにしても、その辺は全庁的なプロジェクトの中できちんと論議を、新将来的な展望をつくられるものと考えています。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"いろいろな側面から教育委員会として考えをはせておかなきゃいけないところをきちんと考えておいていただきたいと、つけ加えておきます。生徒の数、１校温存型の学校になりかねないということもあるわけですから、その辺についてどう考えているのか説明するよう求めました。","respondent":"吉村小中一貫教育担当課長","answer":"そのことを小中一貫教育の中で実現してもらえるのであれば、例えば部活動が人数が集まらなくてなかなかできないということも八潮の課題です。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"あるいは地域の方々が把握した上で、こういう学校づくりをしていくんだというものを持って、僕は新しい学校をスタートしてほしいと思うんですよ。教育委員会は教育だけを考えているということではなくて、きちんと区のそういう方針、その辺の対応策として何かお考えがあったら説明するよう求めました。","respondent":"古里学務課長","answer":"現役のＰＴＡ、なおかつその先の八潮地区全体の地域づくり、そういう視点も視野に入れながら進めてまいりたいと考えています。実際に八潮の皆さんとどういう協議を進めていくのかというのは、いずれにしても、八潮地域の活性化というものが検討されていくものと考えています。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そういういろいろなことを踏まえてやっていただきたい。これだけ八潮から八潮地区外の学校を選択した子どもがいるということですから、ぜひその辺も十分に考えてやっていただきたいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"武内委員","kind":"質問","question":"今回この２日間、３０、ある程度これで一貫校としていくんだよという結論としての報告ということでよろしいんですか。それから９月に第２回目の説明会を行いますという先ほどのお話がありましたけれども、そういうふうに受け取ってよろしいんか尋ねました。","respondent":"古里学務課長","answer":"実は２０年４月に向けて八潮地区小中一貫校とすべきいろいろな改修工事をしていくためには、さまざまな具体的な検討にはいる必要があります。","id":"exchange-010"},{"speaker":"武内委員","kind":"質問","question":"一応説明会の前にいろいろな形で説明をやってこられて、今日報告いただいたのは、この一貫校としていきますよということでよろしいか尋ねました。","respondent":"古里学務課長","answer":"委員のおっしゃるとおりです。","id":"exchange-011"}]},{"id":"topic-02","title":"の文部科学省「新教育システム開発プログラム」事業の受託","agenda":"の文部科学省「新教育システム開発プログラム」事業の受託","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"裏面の検証すべき仮説の中に(2)の3)に施設一体化による子どもたちの学校生活と書かれているんだけど、ここだけ子どもたちの部分が入ってくる。その辺についての検証は行わないのとの意見を述べました。","respondent":"吉村小中一貫教育担当課長","answer":"連携校についても、特に５・６・７年生を同じフロアで生活させるということの動きを見て、ここにはあえて入れました。当然連携校についても、連携校、そのことについては調査をするつもりです。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"ですから、これをやることは大変結構なことだけど、それを忘れないてほしいと思うのを１つ伝えておきます。その品川区の予算面でのこの検証委員会の部分はどういうふうになっているのか、わかっている範囲で説明するよう求めました。","respondent":"吉村小中一貫教育担当課長","answer":"１点目の件ですけれども、私の説明の仕方がちょっと悪かったのかもしれません。そういったことを検証していくことを考えておりますので、連携校についても十分に検証する、そのことが重要であると考えています。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"３番のこういうことをやっていくわけだけれども、よそからのいろいろな先生も入っていただいて、検証委員会という中でやっていくわけでしょう。そうすると、品川区の予算も検証委員会の中に入っていくわけじゃないんか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"この検証については、一切品川区の予算ということではなくて、いただいた国の予算の中で進めていただくです。","id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問","question":"非常に難しいのは、こういうことが入ってくるのかどうかわからないけど、例えば４・３・２という仕組みを義務教育の中で品川は打ち出していく。そういうことまでも検証できるんか尋ねました。","respondent":"吉村小中一貫教育担当課長、市川庶務課長","answer":"まさに私どもは９年間をつなげるという考え方ですけれども、最後の２年間としたときに、本当に最初の４年間の時期に基礎学力がどの程度ついたのか。それは当然その中で検証して、その効果をきちんと報告していくことになると思います。 １点目のお尋ねに私のほうからもお答えします。これについては国が認める必要経費については、基本的に１０分の１０充当という性格のお金です。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"意見","question":"まだ決まっていない段階であれだろうけど、品川としてこれをどう品川の教育に生かしていくかという考え方も合わせて聞かせておいてください。それから、我々に対しての報告みたいなものもどうオープンにしていくのか、それだけ最後に聞かせてくださいとの意見を述べました。","respondent":"吉村小中一貫教育担当課長","answer":"先ほどの説明の中でちょっと申し上げたことなんですが、当然新しい教育の考え方ですので、さまざまな面で検証は進めていこうと思っていました。それについてはあわせて議会、もちろん区民、保護者の方にも報告をしていくということを考えております。","id":"exchange-016"},{"speaker":"沢田委員","kind":"質問","question":"この開発プログラムの目的のところに将来の制度改正を見据えとあるんですけど、将来の制度改正とは何を指すんですか。今言ったことの。","respondent":"吉村小中一貫教育担当課長","answer":"４つテーマがありますので、それぞれのところに絡んでくる法律ですけれども、私どもとしましては、特に今、教育長が説明した、いわゆる義務教育学校の設置ということについて、自治体の裁量でできるということについての法改正、その制度改正についてここでは考えております。","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"一貫教育が４番目のテーマとして手を挙げて指名されたということなんですけど、一貫教育が将来の制度改正として見込まれているんですか。もしそういう背景があれば説明願いたいんですが。","respondent":"吉村小中一貫教育担当課長","answer":"義務教育学校の設置に向けて検討していくということが文言で正式に出ておりますので、国もその方向はにらんでおります。今、制度改正をしていこうと考えておりますので、そういったものを活用していくということになっております。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"そうしたら、フィンランドは１９９８年のときに、それまで入れていた習熟度別学習を完全になくしたというんです。だから、それからすると、ちょっと無謀と思いますが、いかがお考えか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"全国のいろいろなモデルケースを十分に検討しながら法制化に踏み出すわけで、前倒しでやるのがどうということではないと考えています。１点だけ、小中一貫教育は９年間を通して、そういった意味ではちょっと誤解をされているのかなと考えています。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"それから、今のままの教育基本法によれば、教育行政というのは教育条件の整理ですからね。教育内容まで踏み込んで、ああでもない、こうでもないということを実際にやっているわけですから、教育基本法に抵触すると思います。","respondent":"吉村小中一貫教育担当課長","answer":"さまざまな学識経験者を交えた検討会の中で、義務教育学校の設置ということの可能性を考えていくということがきちんと打ち出されているわけですね。その上で、それに応じた教育をしていこうと言っているのであって、全く競争教育というものには当てはまらないと考えています。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問・要望","question":"ある不動産会社なんかを見ると、品川の学力のトップの位置にできたマンションですと、それを宣伝しているわけですから。これは学力格差がますますつくじゃないか尋ねました。","respondent":"若月教育長","answer":"目に見えないところで競争教育は行われているというのが、私の認識であります。私はあえてそこを申し上げたいと考えています。","id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"最後４残ったのが２になり、０になったということ、私は弊害でなくて何だろうと思わざるを得ません。この問題のあれについては、この後の質問でちょっとまた別の件でしたいと思いますので、とりあえずこれで終わっておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"先に質問しておけばよかったんですけど、この内容についてお聞きしたいんですけれども、この実施委員会というのはどういうことをされるのかというのと、検証を進める検証委員会との関係について、どういう位置づけにあるのかというのを説明するよう求めました。","respondent":"吉村小中一貫教育担当課長","answer":"それともその検証結果から見えてきたこととしてどんなことが言えるのか、そういった大もとのところを話し合うのが実施委員会。その実施委員会で話し合ったことをもとに、実際に調査・検討で動いていくのがこの実施協力機関とお考えいただくといいのかなと思います。","id":"exchange-023"},{"speaker":"武内委員","kind":"質問","question":"そうすると、文部科学省から委託されているので提出すると思うんですが、最終的にまとめる際にこの実施委員会の方たちが加わってまとめていく。実施委員会の中に入っているいわゆる外部的な位置づけの方にお墨付きというか、検証してもらったものを表に出す、そういう流れなんか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"最終的にこの実施委員会の中で整理をしてある程度文章化していくと思うんですけれども、当然その中で。今、委員のおっしゃったとおりです。","id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"前回の当委員会でも言ったんですが、６月に発表された公立小学校の学力テストの状況について聞きたいと発言したんですが、改めてわかる範囲でいいですから、品川の状況と全国の状況とか、試験の中であらわれた問題点、克服すべき課題などについて説明願いたいんですけれども。","respondent":"中島委員長、河野指導課長","answer":"本件については、前回の委員会でも沢田委員より発言がありましたが、理事者の方でお答えできればお願いします。 ６月に発表された東京都の学力調査の結果ですが、達成率ということで報告されております。中学校では微増という結果をいただいております。","id":"exchange-025"},{"speaker":"沢田委員","kind":"質問","question":"全教科平均点が７０点を超すという評価を朝日新聞がしているわけですけれども、例えば品川区教育委員会として、これからなんですか。前回より１位上がったというのが、都教育委員会の見方も非常に難しくなっているので、ちょっとその状況について説明願いたいと思います。","respondent":"河野指導課長","answer":"今年度４月から他の区市とは違う、基本的には同じてすけれども、独自のカリキュラムで推進しております。従来どおりの区の調査で実施をしますけれども、平成１９年度以降については、つけさせることができたのかということについて検証していく予定です。","id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"こういうふうにやれば当然なっちゃうんだけれども、品川区はそういうふうにあえて公表しているならば、この問題に対する考え方を聞かせてほしい。どうしたってそこのところに、比較対照して、うちの子は何位になったというふうにならざるを得ないわけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問・要望","question":"専門的って、その他ありませんかと言うから、前回も私はこの点に関心があるので準備をしていただきたいということを言った上でね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"沢田委員","kind":"意見","question":"資料要求ではないけれども、関心があるので、非常に聞きたいということを言ったので聞いているので、答弁がなければないで結構なんですけど、もしあるならば言ってほしいと、改めて別の機会も決算や何かもありますから。","respondent":"吉村小中一貫教育担当課長","answer":"小学校４０校を全部並べて、その結果を一覧表にして出すとか、そういうことは一切していないんです。その２つを示して、そのことを考えてくださいと言っているわけですので、その辺はぜひご理解いただきたいと考えています。","id":"exchange-029"},{"speaker":"沢田委員","kind":"提案","question":"今はもうインターネットでスパンと見られるわけですから。それはぜひ検討していただきたいということを要望して終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"宗像市はどこか学校を見に行くということなのか、宗像市教育委員会で話を聞くということなのか、それだけ聞かせてほしい。教室なの、これとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"子ども教室というと、教育委員会が何かやっていたり、学校の延長線上にあるような感じなんだけど、地域なんだからと思うんです。教育委員会がやっている施設を見に行くのか、地域が積極的に運営してくれているのか、その辺を確認させていただきたいと思って聞いています。","respondent":"中島委員長","answer":"１点目の宗像市のこれは日の里東小学校とか、この学校現場に行って、特別支援教育。ここで小中一貫教育もやっているということですね。","id":"exchange-032"},{"speaker":"林（宏）委員","kind":"質問","question":"この宗像市立日の里東小学校で特別支援教育の何か見るべきものがある、それから小中一貫教育もやっている、そういうことなんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/670410?Template=document&Id=4578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":32052,"voices":109}},{"id":"h18-20060726-11","meetingId":"h18-cm07","date":"2006年7月26日","dateIso":"2006-07-26","committee":"自治制度特別委員会","time":"","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"この状況をもう１回教えていただきたいなというのと、その中で、なかなかそれはできなくなっちゃうんじゃないかなという心配があるわけですよね。その考え方はどういうふうに思われているのかというのを、改めてまずお聞きしたい。","respondent":"岩崎環境清掃事業部長、中山資源循環推進課長","answer":"そのところの思いが非常に強くて、確かにああいう巨大なプラントを動かす技術というのは、結構技術者が不足している。引き抜く方は「現給を保証するから５年間来てくれないか」とか、かなり深刻な状況があるということ… そのこととは直接リンクをするものではないというふうには考えておりますが、当分の間、基本的には人も増員しない中でアウトソーシングを進めるという方法論で出てきたことであるということです。","id":"exchange-001"},{"speaker":"石田委員","kind":"意見","question":"各区からどういうふうにそれに対して意見を言っていけるのか。この一組の意見を言っていく部分と、各区の意向をどのように伝えていくかというのは、それはどういうふうに我々は理解すればいいのかとの意見を述べました。","respondent":"中山資源循環推進課長、岩崎環境清掃事業部長","answer":"そういう、一組としてかかわりの出ている部分については、速やかに区の議会にも情報を報告できる形になってくると思います。当然歩調をあわせていくわけですから、各区で出された意見… 今回のこの問題をめぐりまして、全員協議会で、たびたびに渡っていろいろな資料が出されていろいろ説明を一組としております。それよりも、その議長の皆さん方の中でも、引き続きいろいろなご議論がされるのではないかと思います。","id":"exchange-002"},{"speaker":"石田委員","kind":"確認","question":"そこを今度はアウトソーシングしたままそれらしい人になるのかどうなるのかというのは、それというのは、なり得るんですかね。私はなると思っているんですけれども、行政の皆さんはどうなんか尋ねました。","respondent":"中山資源循環推進課長","answer":"それから各区のモデル工場設置が可能であるかという状況の中で、自区内処理という前提を外した形で考えていくという検討をやったわけですが。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"最終的には解散だと思っているわけですから、全体のものと言っていたら、いつまでたってもそれが進んでいかないような気がするんですけど。だから、これが一つの項目のクリアになるのかという、そこの見解を教えてほしいんですけど。","respondent":"岩崎環境清掃事業部長","answer":"それ次第だとは思うんですが、この技術力も、こうやって確実に確保していければ、条件がどんどん整備されてくるなというふうには思うんですね。少なくとも、それに依存せざるを得ないという状況からは、どんどん変わっていくんではないかというふうに思っています。","id":"exchange-004"},{"speaker":"土井委員","kind":"質問","question":"その結果として、別会社という形の会社がつくられていくわけですから、あるいは今後どうしようとしているのかということを伺えたらと思います。その辺は、そういうことということで、全体協議会に進んでそうなったという形になっているのかどうかということを、まずもって聞きたい。","respondent":"中山資源循環推進課長","answer":"組織上さまざまな検討をする中で、今回は１８年度から、２工場で始まったです。第２弾として、基本的なアウトソーシングの流れの中では、そういうものをいろいろ検討して議論してもらった流れの中で進んでいるということです。","id":"exchange-005"},{"speaker":"土井委員","kind":"質問・要望","question":"そして、そのことは一部事務組合が技術確保ということについて十分、その辺はどうなんでしょうかということですね。そういうものとの関係等は、ご議論の中で参考にされたのかどうか、聞かせていただきたい。","respondent":"中山資源循環推進課長","answer":"そうすると、一定の年齢も、単純に言えば６０歳からの職員がプラントメーカーに行ったりする動きの中で確保していこうというのが一つ。上下水道の情報を入れながら検討したかということについては、申しわけないんですが、ちょっとわかりません。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問・要望","question":"お伺いしましたように、どういう形になるか、これは未来永劫というふうにはならないわけですね。別会社の言うとおりですということになっちゃってもどうしようもないものですから、ぜひ、詳細にお知らせをいただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"三村委員","kind":"質問","question":"寡占状態を回避するためというところを最初に言われているんですけれども、そういう寡占状態が起きると、どうしたデメリットが起こるのか。新会社で安くするというようなお話も出ていたんですけれども、委託料はどのぐらいの差があるんですか、その辺のところを説明するよう求めました。","respondent":"中山資源循環推進課長","answer":"正確なデータを持っているわけじゃありませんけれども、補修経費等々はどんどん上がる傾向が、委託プラントにおいては出てきている。それは、年間数千万の誤差だと思いますけれども、削減効果が出てくると、運営だけでもコストが下げられるというふうに考えています。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"確認","question":"確認しておきたいんですけれども、どういう影響が出、私たちの話はどういうふうに伝わっていくんですか。そこを説明するよう求めました。","respondent":"中山資源循環推進課長","answer":"直接に答えていないかもしれませんが、関心というか、いろいろな方針を９月に向けて出しているという状況です。一組という組織の中で、その辺の議会の意向を紹介していく、提案していくことになろうかと思います。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"電力会社としての立場を確保するために、この８,０００万、４０％というのが必要だということになっているんでしょうかね。２枚目に話があったんだけど、ごみの中間処理に対する区の本来の責任が明確になると書いてあるんだけど、この意味をちょっと説明を求めました。","respondent":"岩崎環境清掃事業部長","answer":"これは何としてでも各区議会が何らかの形で議決するように進めたい、そのために３案なんだというような決着を見たということなんですね。この文言の説明ですけれども、何か意味不明の文章であるということは、これはそのとおりであります。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"基本的なところで行くんですけれども、１ページ目をちょっと説明していただきたいんです。「現員不足により」と書いてあるんだけど、現在、一組ではどのぐらいの職員数で、どのぐらいの職員が足りないというふうに理解されているんですかね。","respondent":"中山資源循環推進課長","answer":"その後の対応ですとか、あとは選択の自由になってきますから、どこまで確実に確保できるか。ちゃんと処遇を含めて、しかしながら、現状のやり方でも必ずメリットがあるやりかたという線引きを設定して運営していくです。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"じゃあ、これは品川区がつくったレジュメなんですか。一組がつくったレジュメなんでしょう。","respondent":"中山資源循環推進課長","answer":"一組でつくった想定資料で、あくまでも、繰り返しになりますが、その３枚目は、運転業務の委託に伴う人件費に主に着目した収支のことです。売電収支は別です。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"各議会、区の議会がどうやってかかわりを持ち得るのか、それをもう少し考えていきたいというふうに思うんですよね。品川区としては、清掃事業ともっと強い絆を持っていたいなというのを要望して、長くなりましたから終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"三上委員","kind":"質問・要望","question":"そこら辺をちょっと教えていただきたいということと、聞いていると、そんな雰囲気にもとれるような話にも受けとめられるような話ですね。そこをお聞かせいただけますか。","respondent":"中山資源循環推進課長","answer":"２年目からはまた契約を見直しして違うところでやれるかということは、そのプラントがある限り、単年度の契約が続いていっているというのが実態です。ご質問２点目の役員構成等については、申しわけありませんが、その辺まではまだ伺っておりません。","id":"exchange-014"},{"speaker":"三上委員","kind":"質問","question":"１８、１９年度の新規施設の稼動が、この一つの会社にすべて持ち込もうというところまで考えているのかどうか。そういうのは明確に見えているんか尋ねました。","respondent":"中山資源循環推進課長","answer":"今のスキームで言っても１５工場ぐらいを委託していかなきゃいけないようになっていますから、ここを積算していても乖離が生じております。","id":"exchange-015"},{"speaker":"三上委員","kind":"意見","question":"先ほど来、林（宏）委員がいろいろと言っていた中から、２３区の中で区議会が特別委員会をつくっているというのはどのぐらいあるかわかりますか。まず、私どもも認識しておかなきゃいかん話になってくるから、わからなければわからないで調査していただくけどとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"２３区の中で、流れとしては、包括されていく流れになっているように伺っています。","id":"exchange-016"},{"speaker":"三上委員","kind":"質問","question":"そこらあたり、もう少し各区の状況を調べていただけないでしょうか。そこらあたりの説明、されたのかどうか覚えていないものですから、ちょっと簡単に。","respondent":"中山資源循環推進課長","answer":"通常、東京電力からその場合は供給してくださいという形をとるのが基本なんですけど、その場合は通常料金よりも上がってしまうという形なんですね。ここに書いてある、組むことによるメリットというのは、そういう面もあるようです。","id":"exchange-017"},{"speaker":"原委員","kind":"意見","question":"この寡占状況がなくなるのかどうかという話もあったんですけれども、１回か２回、各区がそれなりに意識を持って話をされていた。そこについて現実に来たらどうなのというところがあると思うんですが、意識のちょっと違ったところが多分あると思うんだけど、その辺どうでしょうとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"今、そういうご指摘を踏まえた資料を、また検討して示そうとしている。経営計画、認識の上でいろいろ詰めなければいけないことがあるのではないかというご指摘が出ているというふうに、私どもは認識しているところです。","id":"exchange-018"},{"speaker":"原委員","kind":"質問・要望","question":"３年目以降は黒字に転換をするということ自体も、ほんとうにそうなのかどうかというのも、これでいいのかどうかという意見も出されていますからね。その辺のところ、この中で指摘してもどうということでもないかもしれませんが、関心を持って、ここの中で資料を出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"本田委員","kind":"確認","question":"一部事務組合に２３区は分担金を出して、先ほども確認として聞きましたように、区は金を出すけれども。その辺は、今は見当違いのような受けとめ方なのかお尋ねしておきたいと思います。","respondent":"中山資源循環推進課長","answer":"この新会社へのかかわりという面で言えば、２３区が等しい意識を持ってやっていくという形での負担になっていると思います。考え方としては、ここの出資に対する考え方というのは、区の規模にかかわらず等しいかかわりを持っていくという形で示されていると思います。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"２３区のコントロールとか発言権というのは、上で決めてきたことではありますけれども、どうなんでしょうか。４割は東京ガスが入ってくるわけで、２３区が意見を言い、その辺に対しての見解はいかがか尋ねました。","respondent":"中山資源循環推進課長","answer":"方針をどうするかみたいな、これは２３区の一部事務組合で考えていくべきものと、特に説明を生ずる部分について。２４時間運営する中で、ここで関係が途切れたり、委託主体である区側がきちんと把握できるようにする仕組みは重要になってくると思います。","id":"exchange-021"},{"speaker":"沢田委員","kind":"意見","question":"ところが、出ている資料というのは人件費に着目した３枚目の資料なんだけれども、じゃあ、売電の問題でどうなるのか。そういうのを出すなら全部トータルで出して、「こうなんだ」という論理にしてほしいなと、私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"石田委員","kind":"確認","question":"確認だけさせてください。確認だけお願いします。","respondent":"中山資源循環推進課長","answer":"平成１８年度から始まった工場と、そういう形で随意契約になるという可能性が考えられます。直営と、プラントメーカーの場合と、新会社に委託した場合との試算の資料を含めてお諮りするような形になろうかと思います。","id":"exchange-023"},{"speaker":"石田委員","kind":"意見","question":"５年目というと、２３年まで行っちゃうわけだから。そう思いますがとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"１９年度からいきなり入札をやろうかという中で、そしてまた実績なりあわせて見ていく中で、競争する段階が出てくるということではないか。最初のところでは、ある種の政策的な判断という部分があるんじゃないかということで、想定ですけれども。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/148286?Template=document&Id=5600#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":31389,"voices":56}},{"id":"h18-20060726-16","meetingId":"h18-cm07","date":"2006年7月26日","dateIso":"2006-07-26","committee":"街づくり特別委員会","time":"午後１時０２分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"安心・安全のまちづくりに関すること」のうち、「公園整備における安全面での考え方について","agenda":"安心・安全のまちづくりに関すること」のうち、「公園整備における安全面での考え方について","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"ここに１ルクス以上の確保としてあるということだけれども、これは全部の公園でそれだけの確保がされているんでしょうか。していると書いてあるけれども。","respondent":"松代管理工事課長","answer":"造成時には１ルクス以上の照度が保てるように設計をしますし、そういった１ルクス以上を保てるように照度測定を定期的にやっていますし、一定の明るさは確保するように努めているところです。","id":"exchange-001"},{"speaker":"林（和）委員","kind":"質問","question":"だから、やっぱり公園の近くの人がよく言うんだけれども、夜の場合、うっそうとしているので公園に入るのも怖いと言うんだね。ですから、それだけ確保されているのかどうなのか、その点はひとつよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"４カ所案内をしていただいて、つくっていただいたこの防犯対策という部分ですか、これは上４点が公園としてのイメージなんだと思うんですけれども。見せていただいた西霧ケ谷公園ですか、どの公園をイメージすればいいのかがよくわからなかったので、ちょっとその辺をもう少し教えていただきたい。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"そういったことから、今、４カ所ほどご覧いただきましたが、これは安全面で基準が劣るとか、危険であるというような認識はございません。公園をつくる際には全体の公園面積の３割以上の植栽等を設けたい、広場型にしてほしい… これは、そういった夜間パトロールあるいは早朝のパトロール等も行っておりますけれども、そういった警備会社に頼んで実施をしています。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"ここに書かれているのは、通常やっている安全パトロールのことなんか尋ねました。","respondent":"松代管理工事課長","answer":"防犯対策の地域の監視パトロールということで警察官ＯＢというような記述のものは、生活安全パトロールとしているものをここに記載したものです。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"原っぱ公園ですか、周りに垣根的に大きな木がなければ、大体見通せるのかなというような気がしているんです。ですから、防災広場は防災広場としての機能が必要ですから、もう少し考えていくべき部分なのではないかなと思うんです。","respondent":"藤田道路公園課長","answer":"夜間に例えば中学生、高校生ぐらいの人たちが遅くまでサッカーをやっているとか、そういったような公園等もあります。それをピックアップして、スケジュールを組んで、委託の警備会社に回ってもらっているというような形で行っているものです。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"今、あわせて聞けばよかったんですけれども、そこの予算の部分というのはどこから出てくるんか尋ねました。","respondent":"藤田道路公園課長","answer":"私どもの公園維持の費用の中から行っているものです。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"時季ですから旺盛にわーっと伸びちゃうのは当然で、抜いたりとか、ちょっとどういう状況なのかなというのが１つ聞きたいところなんです。大井だとか、その辺が委託との関係でどういうふうな状況になっているのかをあわせて教えていただきたいし、教えてほしいと求めました。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"私どもにとっても非常にありがたいことだと思っておりまして、そういったものに対しては、すぐにできるところから対応してまいってきております。地域によっては変わってはありますけれども… 最初の、地域との連携といったような視点だと思いますけれども、私どもは今年度から実施をしようということで、今、準備を進めています。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"明るさが届くということが大事ですから、安全ですから、安全確保をしていただきたいと。そこはバス道路から１段高くなっていて、よく学校とこっちは道路ですから、全然人目のないところなんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"今日、公園を４つ見せていただきましたが、公園は区の施設ですが、これは２４時間、中に入っていい、そして遊んでもいい施設だと区は考えているんか尋ねました。","respondent":"松代管理工事課長","answer":"おっしゃるように、基本的には、今つくっている公園はすべて２４時間対応型の公園として設計し、管理をしているものです。それに池田山公園の２カ所を含む全部で７カ所となります。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"やっぱり２４時間管理するのは、それは行政の責任だと思うという観点から質問しますが、たった１つだけ個室がありますよね。そういう意味において、便所は個室なので、あの便所というものの安全面というのはどのように考えているんか尋ねました。","respondent":"藤田道路公園課長","answer":"委員がご指摘のとおり当然本当に個室になってするような施設ですから、それを開放してしまうということはやはりできないと考えています。ちょっと説明をあまりしなかったんですけれども、改めてしますけれども、公園の中で遊んでいる子どもに声をかけた人がいたと。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"どうしても便所という中において、不審者等によって、もし連れ込まれたならという思いがどうしても消えないんです。あるじゃないですか、自分の肉声だけじゃなくして、知らせる方法みたいなというのはできないんか尋ねました。","respondent":"松代管理工事課長","answer":"実は庁内検討会を設けまして、現在、検討をしています。そういった役割等も含めて、今、検討をしているところです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"次は安全対策で伺いたいんですけれども、アメリカだったんですけれども、公園がすごく高齢者の憩いの場所になっているんだなとものすごく感じました。特に高齢者に対しての安全とか、あと公園のあり方みたいなものというのは、これから担当の課としてどのように考えているんか尋ねました。","respondent":"松代管理工事課長","answer":"実際、公園をつくるにあたってのいろいろと地域の方に話を聞く中でも、そういった意見があります。今あります既存の公園の中でピックアップしまして、ケア的に改修等を行って、対応しています。","id":"exchange-012"},{"speaker":"築舘委員","kind":"意見","question":"大体その３つがあったわけですけれども、この具体的なもし何かがあれば、挙げてほしいと求めました。","respondent":"松代管理工事課長","answer":"委員がご指摘のとおり、３種の神器といいまして、砂場と滑り台とブランコというような形でつくってまいりました。好まれる、喜んでいただける遊具かなと、このように考えておるところです。","id":"exchange-013"},{"speaker":"築舘委員","kind":"質問","question":"そういった落下時の衝撃を吸収する舗装というんですか、あと、そういうことでの安全のための新しいものを取り入れをしていると思うんです。その点で何かありますか。","respondent":"松代管理工事課長","answer":"これは昭和５０年代、６０年代、これを多く設置した例があります。は日常の管理をそういった木製遊具の場合にはさらに頻度を高めて、見回って管理をしていこうと、そういった工夫にかえてきたところです。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから、それとセットで専門家というのはどういうことでしょうか、こうなっているんですね。何ていうんですか、その辺の連携の度合いというんですか、その辺も含めてちょっと教えていただけますか尋ねました。","respondent":"藤田道路公園課長","answer":"これからは、一応毎年実施をしていきたいと考えているものです。違うご意見をいただけるかなと考えてございまして、そういった中で連携を図りながら進めていきたいと考えています。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"お尋ねしたいのは、夜間パトロール、それが公園の中まできちんと入っていってやっていただいているのかどうかです。そういう広い公園なんかについての夜間パトロールというのは、どういうふうなパトロールの仕方をされているんか尋ねました。","respondent":"藤田道路公園課長","answer":"基本的に巡回をするということではありませんので、しながわ区民公園等については、閉鎖をすることで安全性を保っていると考えているところです。問題がある場所を中心に巡回しながら回っているです。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"その辺というのはどういうふうに実態をつかんでおられるのか、公園のその３時から５時の時間帯、その辺を伺いたいと思うんですけれども。つまり子どもが、私たち大人が想像しないような、その辺の見解というのはどうか尋ねました。","respondent":"金子生活安全担当課長、藤田道路公園課長","answer":"恐れ入ります。公園あるいは時間帯、そういったものの特筆してデータ的なものを出しているものというのについては、今のところちょっと承知しておりません。 まず事件、事故の報告はございませんので、そういったことはございません。今、８・３運動とかいろいろありますので、地域のいろいろな目の中でお子さんを守っていくということが大切なのかなと考えています。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"なきゃないに越したことはないわけですから、私は子どもの直接的な声というのを聞く必要がむしろあるんじゃないかなと思うんです。そういうことはこれからも含めてあり得ないことだと思うので、その辺の見解を教えていただいて、終わりにしたいと思います。","respondent":"松代管理工事課長","answer":"我々は、先ほどから申しましたように、安心してご利用いただけるような公園づくりというところで整備をし、管理をしています。管理をしていく、そういったものも今後続けていきたいと、このように考えておるところです。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"子どもの角度から安全を確保できるような、そして品川で育つ子どもが１人もこういう危険な目に遭わないようなまちづくり、公園づくりを目指していただきたいということを強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと見解なんですけれども、そして広場が欲しいという要望があるので、やはり今後も推進していってほしいと。何か要望がありましたら、いろいろ何か問題点があったのかどうかちょっとわからないんですけれども、その辺のご見解を説明するよう求めました。","respondent":"藤田道路公園課長","answer":"ただ、大きな公園についてはそういったような記載をしているような公園もあります。品川区にご連絡をいただければ、そういったことで声はきちんと伝わってきますので、そういった中で声を寄せていただければなと考えております。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"なかなか一般の方が３７７７－１１１１というのはちょっととっさに皆さん出てこないということがあるので、公園を利用なさっている方が気軽にちょっとご要望、取り組んでいただければありがたいなという要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"大西委員","kind":"確認","question":"１点だけ確認というか、私もちょっとど忘れしているかと思うんですけれども、利用者の面からした安全ということで尋ねたい。座る部分のところでのものというのは、もう今は既にその木製のかたいものから全部交換というか、それはなされているんか尋ねました。","respondent":"藤田道路公園課長、松代管理工事課長","answer":"あるいは少しやわらかいゴムの帯状のもの、そういったような形のものがついているケースが多いかと思います。私どもの公園、基本的にはどこにもすべてついておりますので、そういった面の安全は配慮されているかと考えています。それで、ランクを５段階つけまして、危険と思われるものについては速やかに直しました。","id":"exchange-022"},{"speaker":"大西委員","kind":"質問・要望","question":"私はすごいその強度というんですか、交換がなされているかなされていないか、できれば確認をしていただければと。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"空き交番の関係でちょっとお尋ねしたいんですけれども、いいですか。そして、若干方向が変更している部分があるみたいなので、その後の状況をちょっとわかっている範囲で教えていただきたいと思うんですけれども。","respondent":"金子生活安全担当課長","answer":"前回ご報告して以降、特に大きな動きといいますか、情報に関しましては、この間申し述べた以上のことは特に入ってきておりません。８８カ所、まだ地元と調整する中で今後変更する可能性もあるということで、いまだはっきりしたものが出ていないというのが現状と聞いております。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとよくわからないので確認をさせていただきたいんですけれども、新聞報道以外の情報は全くつかんでいないということなんでしょうか。それの確認を改めてしたいのと、改めて伺いたいし、そのこともわかっていたら教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"５カ所を全部廃止するのかどうかということはこれからの検討だと思いますけれども、この間の発表はそのままずっと続いているということですから。１４人の町会長の連名で廃止をしないでくれという署名が取り組まれつつあるというふうにも聞いているので、ちょっとそこを伺いたいと思います。","respondent":"早津区民生活事業部次長","answer":"対応につきましても、この施策を決めました警視庁において、まず一義的には対応するというのが基本であろうと考えております。これは前回の報告のときにも簡単にご説明いたしましたが、検挙率、件数の相対的に低いところが対象となったというふうに報告を受けているところです。","id":"exchange-026","title":"町会・自治会支援"},{"speaker":"南委員","kind":"質問・要望","question":"今、そういう立場での区としてのそういう役割を果たしていただきたいと私は思っているんですけれども、その点についてはどうでしょうか。それを聞いて終わりにしたいと思いますので。","respondent":"早津区民生活事業部次長","answer":"事態を注視しているというのは、区としてもどういうようなことをするかということの検討を今後してまいりますと前回も申し上げました。その形に変わりはございません。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/847285?Template=document&Id=6330#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":26175,"voices":66}},{"id":"h18-20060727-14","meetingId":"h18-cm07","date":"2006年7月27日","dateIso":"2006-07-27","committee":"行財政改革特別委員会","time":"午後１時０３分～午後３時０２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"民間委託等に関すること","agenda":"民間委託等に関すること","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"人材派遣の人数とか、これはどういうふうな関係で決められているのかということを、ちょっと大まかに教えていただきたい。答えは、もしいただければお願いしたいんですが、特別支援保育というのと保健業務というのがわかればお願いしたいと思います。","respondent":"榎本人事課長、堀越行財政改革担当課長","answer":"７時間で入っている人材派遣と、ティーンズプラザのほうに入っているのが５名ということで、そういう形で従事しています。病気休業代替が６名、オアシスルームのほうで２０名とか、全部で１１２名という形で入っています。 特別支援保育のところで、障害児の保育に対応するという形の部分に、人材派遣の方も補助として入れているです。ちょっと細かいところまでは承知しておりませんけれども、そのようなことで聞いております。","id":"exchange-001"},{"speaker":"川西委員","kind":"質問","question":"シルバーセンターなんですけれども、受付業務はシルバー人材センターがやっていたのを覚えているんですが、この実態について、清掃業務との関係を。どういうところに、どういうふうに委託されているのか説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"シルバーセンターの委託なんですけれども、これはシルバー人材センターのほうに委託をしております。業務委託の内容ですけれども、受付を含めて、清掃等、そういったものについて包括的に近い形で委託をお願いしているというものです。","id":"exchange-002"},{"speaker":"川西委員","kind":"質問","question":"続きで申しわけないんですが、児童センターの清掃業務は、シルバー人材センターだけではなくて、西大井にある障害者施設に委託していると思うんです。その清掃業務の分担はどうなっているんか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"概括的になろうかと思いますけれども、清掃等の業務委託については、シルバー人材センターにもう１社、民間の会社と、品川総合福祉センターにもお願いしていると聞いております。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"確認といいましょうか、まず、直営の施設はこれだけでしょうかという、単純な質問が一つ。例えば年度を区切ってやっているでしょうから、その契約の見直しをどういうふうにされているかということを、説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"常日ごろから見直しに努めておりまして、また、サービスを維持しながら経費の削減ができるようなという形で運営しているものです。今年度より検討を始めておりまして、現行の民間委託の進め方がどうなっているのか、その中身を分析して検討を進めていく予定でおります。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"むしろ、その契約のところについて、要は見直しをしているんですかということをお伺いしたわけです。残っている直営施設についてどういうふうに考えて、将来は、それをにらみながらどう対処していくのかということを説明するよう求めました。","respondent":"堀越行財政改革担当課長","answer":"新しい設備ですとか、送迎のサービスですとか、事業者のほうから提案を受けた形で実施していただいているという部分もあります。これからの考え方につきましては、今までの区が委託をしている業務とか、あり方というものを検討していきたいと考えているところです。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうしないと、プロポーザルで業者がＡ、Ｂ、Ｃと出た中で、これがいいと決められないわけですから。最後に確認したいのは、今までの公務と違った素質が相当求められてくると、最後に説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"今、それから余計に経費がかかるといったような弊害も出てきてしまうことも考えられますので、そこら辺はしっかりとやっていかなくてはならない。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問・要望","question":"直営施設一覧の中で、児童センター、保育園、図書館、過去の行財政改革特別委員会の中でも、相当個別にいろいろな議論があったところなんです。保育園は６２７人、図書館は７１人という数字が出されていますけれども、その数字を明らかにしてほしいと求めました。","respondent":"榎本人事課長","answer":"図書館については、平成８年度当時１３５名おりました。１７年度と窓口業務委託を拡充してきましたので、平成１８年度現在、７１名という形になります。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"保育園で一番問題になるのが、よく言われる０歳児、あるいは産休明けの１人当たりの単価がどうかと。その辺もつかんでいるのかということもお聞きしたいと思います。","respondent":"堀越行財政改革担当課長、榎本人事課長","answer":"年齢別のデータは持ってないんで申しわけございませんが、児童１人当たりの平均の運営経費、平成１７年度で１８万２７８円です。ちょっと０歳児については、手元にございませんので、申しわけございません。 基本的には、保育士等につきましても１００％、パソコンは最低限の操作はできる。それからあとパソコン研修も毎年継続してやっておりますので、その中でスキルアップを図っているという状況です。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"若干基本的なことを伺いたいんですけれども、人材派遣のことについて、区とどういう契約になっているのか、教えていただきたいんです。ないのか、これだけなのか、あわせてちょっと総合的に教えていただけますか。","respondent":"榎本人事課長","answer":"人材派遣ですけれども、平成１７年度から実施しているのが現状です、平成１８年度は２年目という形です。人材派遣会社のほうに頼んでスキルの高い職員を使っておりまして、平成１７年度につきましては、３名ほど使っております。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"これ見ますと、非常勤の方が０になっていると書いてあるので、その関係がよくわからないんですけれども、そこをちょっと教えていただきたい。人材派遣の人がいると伺ったんですけれども、それは人材派遣ではないのかどうか、もう少し教えていただけますか。","respondent":"榎本人事課長","answer":"非常勤職員が３４名おりまして、平成１８年度になってそれが０という形になりましたので、職員と人材派遣という形になっているものです。その下に業務委託、運営委託業務を受けているところは、そういう外部の人材が来ているという形になります。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの話ですと、年間契約ということになるんでしょうか。児童センターは２６人、保育園１１２人とありましたけれども、教えていただけますか。","respondent":"榎本人事課長","answer":"実際にそのとおり入るかどうかということがありますので、欠員に応じて入れた段階で、月ごとに金額を払っているという形になります。大体、何月で幾らという形で、実態上、進めているところです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"もう一つ別の角度で伺いたかったんですけれども、非常勤職員が０になって、人材派遣会社のほうで穴埋めすることにした理由を教えていただけますか尋ねました。","respondent":"榎本人事課長","answer":"非常勤職員だけで１,０００名を超えるような形がありまして、それは少し是正したほうがいいだろうということで区の方針を決定いたしました。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"１,０００人を超えるのは是正するという話の中には、結局は区のコストを下げるということが一番の理由ということで、よろしかったんでしょうか。よく伺うんですけれども、どうか、そこだけ説明を求めました。","respondent":"榎本人事課長","answer":"毎年その手続を全部、人材派遣のほうが、そういうコストはかからないだろうという形の部分が一つあります。そういう継続雇用するんであれば、継続的に仕事があるんだったら、このような形に進めてきたところです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"窓口業務２１館というご説明があったんですが、運営業務の４館が、その点を１点。なかなか難しいと思っているんですが、ここのところの人材派遣を取り入れている基準がどうなっているのか、ちょっと具体的に説明を求めました。","respondent":"堀越行財政改革担当課長、榎本人事課長","answer":"運営業務等の中身のお話ですけれども、運営業務は４館で行っていまして、こちらについては児童センターの業務の委託という形になります。今、在宅子育ての支援といった施設もつくっておりますので… 人材派遣なりという形で、役割分担をしてやるのが一番効率的に施設が運営できるのではないかということで、こういう形に進めてきているところです。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"言ってみたら、それこそ経費のところで決まるんですかね。どういう中で派遣をされているのかというところまでチェックができているのか、どうか、ちょっと中身も説明を求めました。","respondent":"榎本人事課長","answer":"実際に片方で、きちんと自分が何をしたいのかというところを考えるという意味でいくと、こういうちょっと試しでやってみる。要は、そういった意味での考え方というのも、一つはあるのかなと感じております。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"区と同等ということですが、私はさっき、労働条件で、賃金を含めたわけですけれども、社会保障のところも同等なんか尋ねました。","respondent":"榎本人事課長","answer":"労働時間という意味では同等ですけれども、社会保険等につきましては、人材派遣会社のほうでやるというのが人材派遣法の基本になっておりますので、保険等社会保障の関係につきましては、人材派遣会社のほうで、きちんと法にのっとった形で保証されていると考えています。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、相手の会社の条件の中で、こちらが求めているだけですという部分では、なかなか収まらない。その辺については、さっきも言いましたけれども、自治体としての社会的責任という部分で問われていくものだと思うんですが、この辺はどうでしょう。","respondent":"本間総務部長","answer":"そういう意味で、労働者は保護されているです。ただ、どういう条件で働くかは、労働者個人が自分の意思で決めるということが基本になっているということで、ひとつご理解をいただきたいと思います。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"意見","question":"費用対効果と言いますけれども、財政面だけで見るのではなく、広く見ていかないといけない問題であると思います。これは意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"須藤委員","kind":"提案","question":"議会からいろいろ提案させていただきましたことで、それぞれの結果、努力をされていることには敬意を表したいと思うんです。極端に言えば、保護者たちがそういうところがいいというような提案をされるぐらいの時間をかけて整理をしていかなきゃいけないだろうと思うんですとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"いろいろな子育て支援や、介護予防ですとか、何が住民のために結びつくのかということを考えながらやっていきたいという思いでおります。個人的な考えになるかもしれませんけれども、やはり、サービスの向上と経費の削減と両方を維持するような形で進めていきたいと考えています。","id":"exchange-019"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、やっぱり理事者のほうはよくそういうことをとっていきながら、区民ニーズというものをつかんでいただきたいと思うんです。やはり区民ニーズにほんとうに合うかどうかということに照らしていってもらうというような考え方をしてほしいと求めましたが、いかがか尋ねました。","respondent":"新美企画部長","answer":"高年齢の方の利用者への対応と、かなり幅広い層に、引退後の地域活動の場というのを考えています。シルバーセンターだけで対応というわけにもいきませんが、団塊の世代対応を考える中で、これから検討し。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"この指摘をきちんと品川区は受けとめるべきだと思うんです。そこをどう受けとめているのか、そこだけちょっと伺いたくて質問いたします。","respondent":"新美企画部長","answer":"そういう意味では、従来のコアの基本的なサービスの部分を単純に非正規化をしているということを、品川区としてとっているわけではない。","id":"exchange-021"},{"speaker":"中島委員","kind":"質問・要望","question":"先ほど、今、自分の職場ができたということで喜んでいらっしゃる方がたくさんいるということも認識をしておいていただきたい一つかなと思うんです。どうしてこうなって、今の窓口のところとどういう違いがあるのかということが、。","respondent":"榎本人事課長","answer":"少し経つとやめて、そこまで教えるとまた次の人にかわってという部分がありまして、なかなか継続的な形ができないということが１点ございました。窓口の受付業務を平成１６年度４館やりまして、平成１７年度に全館に広げたという形で、そういう形に切り替えてきたという状況です。","id":"exchange-022"},{"speaker":"中島委員","kind":"質問","question":"こちらの施設の概要の中で、いろいろ事業が出ていますけれども、こういった中にもまだまだ民間活用ができる部分があるんじゃないかなと感じるんです。団塊の世代の活用ということで、探し出せばもう少しあるのかなと思うところなんですが、その辺のところはいかがか尋ねました。","respondent":"榎本人事課長","answer":"そういった意味で、こういったものは、今後、いろいろな地域の方々の協力を得てやっていく必要があるのかなと考えています。この中で、地域の中の図書館という位置づけにして、そういうサービスをしていきたいと考えております。","id":"exchange-023"},{"speaker":"中島委員","kind":"質問・要望","question":"ここにレファレンスなんかがありますけれども、６０歳代というのは学べばまだまだ開けるし、いろいろな脳の活性化もできると思います。そういったこれからの方たちに希望が持てるような、そういった施策もいろいろ取り入れていただきたいと要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"藤田委員","kind":"質問","question":"小さいことと、大きいことと２点、お伺いしたいと思います。非常勤、常勤の人で対応して十分なのか、その辺を、まずお伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"それから、常勤職員が４名で、非常勤職員については、館長が１名と、学芸員が３名という形になっております。今のところは、そういうような形と聞いております。","id":"exchange-025"},{"speaker":"藤田委員","kind":"質問","question":"品川文化振興事業団があるわけですから、そこから派遣をするとか、何らかの方法があるんではないかと思っています。ですから、シルバー人材センターの中で一つの人材派遣部門というものを設けても、私はいいんじゃないかと思います。","respondent":"日下部企画財政課長","answer":"状況もこれまでと変わってまいりますので、これからさらにまた具体的に検討し、実現をしていくということが非常に重要になってくると思います。品川区といたしましても、その辺の検討につきましても、これから視野に入れて取り組んでまいりたいと考えているところです。","id":"exchange-026"},{"speaker":"藤田委員","kind":"質問・要望","question":"仕事としてつながるような方法も考えていく、大事な柱ではないかなと思いますので、これについても要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"西本副委員長","kind":"質問・要望","question":"まず教えていただきたいんですが、おそらく１年ごとにチェックが入りということで、その契約金は変わらないという形なんでしょうか。指定管理者制度ですから、その辺はどういうふうに、区としては考えておられるんか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"事業の計画案と、話し合いの中で変える部分があれば、当然サービスアップのために変えていくということも考えられます。それに伴って、指定管理の料金についても変わってくるという形になると認識しております。","id":"exchange-028"},{"speaker":"西本副委員長","kind":"質問","question":"例えばぷりすくーる西五反田の例で言いますと、５年間契約があったとしたら、職員はそこでずっと働いているわけですね。その辺の絡みはいかがなんか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"そういったところも見込んで、５年間の計算をして事業の計画を立てて、こちらのほうに申請をしてくるということが一つ。それからもう１点、ある程度の調整ということも考えられるかとは思いますけれども、事業者のほうで運営をしていくであろうと認識しております。","id":"exchange-029"},{"speaker":"西本副委員長","kind":"質問","question":"話し合いの場につくのかもしれませんけれども、あくまでも、指定管理者のほうの責任においてということになるんでしょうか。その辺の管理はどうなのか、指定管理者のほうですべての判断をしてしまっていいのかというところは、いかがか尋ねました。","respondent":"新美企画部長","answer":"５年間の中で一定の人件費を見込み、そこの社の昇給等も含んだ見込みの中で、私ども思っております。自由、それとしかるべく区側の対応策をどうするかということは、個別にちょっとご相談をしていく事項ではないかと考えております。","id":"exchange-030"},{"speaker":"西本副委員長","kind":"質問・要望","question":"もう一つ確認したいのが、それから民間を活用して、さらに区民のニーズにこたえていくんだというお話があったと思うんです。つくり上げていく、示していく手立てをしていく必要があるんじゃないかなと考えるんですが、その辺のお考えはいかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"それをなぜ職員で継続していかないのかというお話かと思いますけれども、それを、民間の市場がある程度成熟してきたという部分も言えると思います。さらにサービスの底上げを図るというような部分も総合的に含めまして、施設の運営を図っているという考え方でやっているものです。","id":"exchange-031"},{"speaker":"西本副委員長","kind":"質問・要望","question":"ですから、品川区のノウハウというものを非常に大切にしていただきたいし、できれば常勤という形で、それを継承していただきたい。民間に頼むべきものなのか、自分の力で何をしなきゃいけないのかということを深く考えていただきたいと、要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"中島委員","kind":"質問","question":"区民住宅のファミーユ西五反田西館がベニーエステートサービス(株)で２年で、東館が３年と、違いがあるのはどうしてなんでしょうか。何か理由があるのか、またコスト的にどうなのか、その辺のところを説明するよう求めました。","respondent":"堀越行財政改革担当課長","answer":"こちらにつきましては、基本的には５年という形で考えておりましたけれども、これまで業務委託をやっておりました期間がありましたから、それを考慮いたしまして、残存期間を指定管理の期間として定めたものです。","id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問","question":"ほかの指定管理者もこれからは見直しをしていくわけですから、じゃあ、具体的にどれだけのメリットがあるかという数字の説明は全くなかったんですよ。ですから、そういう共通の評価の仕組みと、低廉されたコストの明示はしたほうがいいと思うんですが、いかがでしょうかという質問です。","respondent":"堀越行財政改革担当課長","answer":"数字の説明という部分も含めまして、とりあえず基本方針は定めてありますけれども、所管ごとの対応であった部分というものもあります。整合性をとれたものをつくろうと考えておりまして、委員ご指摘の部分も含めまして、検討を進めていきたいと考えています。","id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私たち議員も理解が進むと思いますし、できればそれを、全庁統一された形の中で基本的なものを押さえていく。所管の事情がさまざま違うでしょうから、評価をつくってくださいという要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"はいそうですかと判断をする根拠が何も示されていなかったという意味では、原則、協議をしていってほしいと求めました。現場はそういう事業部になるかと思うんですけれども、そういうふうな連携とか、考え方を示していただきたいんです。","respondent":"堀越行財政改革担当課長","answer":"いろいろな手法を使いまして進めていく。コストだけではないということを認識していただければなと思います。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"どういう環境がいいのかということも、きちんと把握をして、協議をしてほしいと求めました。こういう経過があって、行財政改革特別委員会で随分話し合われてきたんだということを言われていたので、その資料提供をお願いできればと思います。","respondent":"堀越行財政改革担当課長","answer":"７月７日に施行されましたので、民間委託に関する国の動きについて、同法の概要ということでご説明します。簡単ではありますが、資料に沿って説明をさせていただきました。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"おそらく国の審議会のものなのか、ちょっと教えていただきたい。ちょっとご説明いただきたいのは、どのようなものがあったのか、あわせてご説明ほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"施行前にもいろいろな資料がホームページ等で公開されておりましたけれども、施行後の概要という形で公開されているものを利用させていただいたです。そのほか経済財政運営及び経済社会の構造改革に関する基本方針ですとか、そういったところで、検討されてきたと認識しています。","id":"exchange-038"},{"speaker":"中塚委員","kind":"確認","question":"むしろ、社会の問題とされている中、こうした格差社会を、ワーキングプアの実態を、品川区はどう見ているのか、お考えを伺いたい。そこを、まず伺いたいんですけれども、。","respondent":"本多委員長、堀越行財政改革担当課長","answer":"法律の概要についての説明をいただき、それで地方公共団体にとってこれからの課題ということですので、その辺を踏まえて、質疑のほう、答弁のほう、両方よろしくお願いします。先ほどの直営施設のところでご説明させていただいたとおり、特にそれを推進するのが目的とか、そういうことではございません。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、派遣の問題を少し伺いましたけれども、ＮＨＫスペシャルで映し出されたワーキングプアの実態を、よく受けとめていただきたいと思うんです。区がどういうふうに理解しているのか伺いたいんですけれども、これは、国民の立場に立っていると思いますか。","respondent":"堀越行財政改革担当課長","answer":"本日、この資料を出させていただきましたのは、７月７日に施行されたということで、今回の法案について、参考までに説明をさせていただいたというものです。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"そうすると、月の収入がどうなるかというと、１０万円を切っちゃうんですよ。そもそも生活保護基準以下の労働者をつくり出している、この責任をどう感じているのか、率直なお考えを伺いたいと思います。","respondent":"榎本人事課長","answer":"その求人広告というのは、それをやりたい人がそれに応募するということであって、それだけで生計を立てるとか、そういう前提でやってものではありませんので、そういう時間帯で、自分のやりたい仕事をやるという形になっていると思います。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"そのことに対する区の見解というものが出されていましたけれども、そういう形で進められていく予定があるのかどうかの確認を、ちょっとここでさせていただきたいなと思います。","respondent":"日下部企画財政課長","answer":"ホームページ、確かに８月１５日までにご意見やご要望をいただくということで、今現在、受付けをしています。内容等についても、区としての基本的な考え方も含めまして、ご報告をさせていただきたいと考えています。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"見解を公開しなければならないと、私たちは認識をしているので、そのことについてどういうふうに考えているのかと。そういうことを参考にしていただいて、区の見解として資料としていただければということを要望したいと思いますので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"たしかトピックスの中にあったので、新しいトピックで順送りになるのかもしれないんですけれども。トップページに残っていないと、大きな意見を募集する姿勢が感じられないんで、ぜひトップページに残していただきたいのですが、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"したがいまして、これにつきましては、ずっと最上段に残るようにという形で調整をしてやっておりました。８月１５日までは最上段にそのまま残るようにということで、確認、調整をします。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/218784?Template=document&Id=5804#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":36732,"voices":101}},{"id":"h18-20060803-5","meetingId":"h18-cm08","date":"2006年8月3日","dateIso":"2006-08-03","committee":"総務委員会","time":"午後１時０２分～午後４時４２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"山村委員","kind":"質問","question":"今後、大学はこれ以上増やすということがあるかどうか、説明を求めました。","respondent":"榎本人事課長","answer":"大学なんですが、区内の大学としては清泉女子大学、立正大学ということで、首都大学東京は若干関連校が区内にあるということでやっておりますけれども、多分、区内にはほかに大学はあまりないと思いますので、今後、増やしていく予定はございません。","id":"exchange-001"},{"speaker":"山村委員","kind":"意見","question":"そうすると、要するに区内以外の大学から受け入れるということは、今後、考えないのか。私が出ているからというわけじゃありませんが、とにかく今後、区内以外の大学というのは考えられるのかどうかとの意見を述べました。","respondent":"榎本人事課長","answer":"どういうふうに実現可能かというのは考えたいと思いますけれども、相談には応じて、大学側と区側と双方にメリットがあるような形で検討はしていきたいと思います。","id":"exchange-002"},{"speaker":"山村委員","kind":"質問","question":"受け入れの人数というのが、結局、現時点よりあとどのぐらい増やせるのかというのと、インターンを受け入れるにあたって、金銭的なことというのは全く発生していないんか尋ねました。","respondent":"榎本人事課長","answer":"受け入れ先等で、人数をある程度増やすというのは可能かなと思いますけれども、どこにねらいを置くかによってその辺も考えていきたいと思っています。それから費用については、就業体験ということなので、一切費用等の部分はかかっておりません。","id":"exchange-003"},{"speaker":"山路委員","kind":"質問・要望","question":"将来の品川区の人材づくりという視点から大きな効果を生むんじゃないですかということで、そういうものがあったら聞かせていただきたいことと、逆に意見というものがあったら聞かせていただきたいんですが。","respondent":"榎本人事課長","answer":"就業に対しての意欲とか、なるべく説明をしながら一緒にこういう仕事でという形で、その辺は十分所管と詰めながらいかざるを得ないと考えています。","id":"exchange-004"},{"speaker":"山路委員","kind":"質問","question":"まだ歴史は浅いですからもっともっと時間がたたないと判断はつかないと思うんですが、この職場は私には合わないとか、そういうことは全くないですか。どうでしょう。","respondent":"榎本人事課長","answer":"実際上、それで評判が悪いとか、そういう話は聞いておりません。要は、かなり実際上、就職ということに対しての関心がものすごく高まっているというふうな話で聞いています。","id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"公務員という体験ですから、ある程度掌握して見守っていく必要性があるんじゃないかと思いますので、その辺をよろしくお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"せっかくの機会ですから、せっかく品川と縁ができたんですから、そういうものを大事にしていっていただきたい。それからもう１つ、いろいろな人がいるわけで、品川の場合はどうなっているのかということを簡単に説明するよう求めました。","respondent":"榎本人事課長","answer":"なかなか高校生となると時間的な制約、その辺の受け入れ態勢は難しいんですけれども、子育てボランティアという形でやっている事例はあります。高校生ですと、ボランティアの中で実際にそういう就業なり、介護に関するものの体験は受けているです。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"すまいるスクールのようなところがあるわけですから、福祉というものを体験するという仕組みをもう一歩踏み込んでつくっていっていただきたい。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"２番のインターンシップの目的で、品川区として職場の活性化になると書いてあるんですけれども、インターンシップのこの制度があって、何で職場が活性化するんか尋ねました。","respondent":"榎本人事課長","answer":"要は大学１年生ですと１９、２０歳ということで、公務員の仕事を全然わからない人にきちんとわかりやすく説明をしなきゃいけないという意味で。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"もう一回質問したいのと、ほかの委員からの質問への課長の答弁を伺っていますと、追跡調査って私はしたほうがいいと思うんです。受けたけれども受からなかったとか、いろいろそのパターンってあると思うんですけれども、いかがか尋ねました。","respondent":"榎本人事課長","answer":"やはり係の数で考えれば、実際上、それなりにきちんとわかりやすくどういうふうに説明しようかというところがありますので。１４名のうちどれぐらいの方が実際上、今後、そういうことが教えてもらえるのかどうかというものも踏まえて検討していきたいと考えています。","id":"exchange-010"},{"speaker":"藤原委員","kind":"意見","question":"あのときインターンシップに行ったことが機会になって、私は公務員になろうと思いました」と、やっぱりうれしいと思うんです。その辺というのはちゃんと押さえておいたほうがいいと思いますので、今後、検討していただければ幸いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"一般企業では本当にそれぞれ大変さはありますけれども、２カ月、３カ月、さらには半年というところももちろんあります。何とかそういう将来いい人材を品川区も採用しようということで望んでいるわけですから、発掘できるわけですから、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"１点だけ。植栽工事がありますけれども、大体幾らずつかかっているか、大ざっぱでわかったらお願いしますとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"非常に大ざっぱな言い方ですけれども、面積的に５,３５０m2ございまして、平米単価が３万円程度というふうな金額になってあります。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"それぞれごとにはないですか。じゃあ、後でもしわかったら説明するよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"学校の境界が後退するのかどうか、植栽のところがどうなっているのかということと、これは面積としては広くなっているんですか。それから運動場は、これは絵で見るとある種囲われているのかな、植栽と一緒になっているのか、その辺のところをちょっと説明を求めました。","respondent":"宍戸施設担当課長","answer":"それらの木、１３０本程度あったんですけれども、そのうちの４５％程度は保存するというふうなことでやっています。グラウンドとしましても、今回、今までよりは長い距離の１４２ｍのトラックが確保できます。","id":"exchange-015"},{"speaker":"塚本委員","kind":"意見","question":"それを一番知りたい。塀の中に緑があるのか、道路に面している場合は、そのあたりに校庭と区切ってあるのか、随分感じが違ってきますのでとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"フェンスは道路沿いに作りますが、なるべく目立たない色のメッシュフェンスを使うことにより、道路に面して植樹帯が広がって見えるよう工夫いたします。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"道路占用料ですか、今の特殊桝ですか、大きなトランスが載っかっていますよね。ある程度、何か植樹帯のところに分岐盤みたいなものがついているようなものしかイメージが出てこないんですけれども、その辺を教えていただけますか。","respondent":"中島経理課長","answer":"構造物そのものは区のものですから、そこから占用料はございませんけれども、建設負担金という形で企業者に負担していただくです。照明に使うとかという場合、そういったものは今回、柱の上のほうにそういった小型の変圧器がつくような全体の構造になってあります。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問・要望","question":"建築負担金というのは今度の契約金額の中で何％ぐらいを占めるのかを教えていただきたいのと、管理は全くなしということはあり得ないでしょうから、管理費云々というのはどうなっているのかを説明するよう求めました。","respondent":"中島経理課長","answer":"２５年ごとに買いかえる必要が生じるだろうという基本的な考え方がございまして、地中化した場合、この電線は大体５０年もつと言われております。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"区の帰属物ということですから、ここに書いてあるトラフそのものは区の帰属物になるわけですよね。これそのものが破損をしたりとかということがあれば、これは区がそのための負担をしていくという考え方になるんか尋ねました。","respondent":"中島経理課長","answer":"トラフそのものは半永久的なものとして考えてありますので、具体的には、要するに、例えば震災等で破損したという場合はまた全く別の問題ということになりますが、通常、１０年２０年ぐらいで破損するということは全く想定していないと聞いてあります。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"せっかく東京都で電子入札、東京都の方式を採用しているわけですから、ほかの区ではメートル幾らぐらいなのかなというのを載せられないでしょうか。どうか尋ねました。","respondent":"中島経理課長","answer":"品川区のこの契約の入札状況調書の中に他区のそういったもので載せるのはいかがなものなのかなというふうには考えてありますけれども、所管にそういう数字の手持ちがあるのかどうかは後ほど確認させていただきたいと思います。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"契約金額がせっかく出ているんですから、他区ではこういう感じで出ていますよという参考価格みたいなのがあると非常に審議もしやすいのかなと思ったもので、意見を述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"電柱を地中化したいという要望はそれぞれのまちにあると思うんですけれども、１００ｍなら１００ｍ単位で、見当がつかない部分があるわけです。何かいろいろなことをするでしょうけれども、そのときにはこれだけかかるんだよということがわかれば、大づかみで教えてほしいです。","respondent":"中島経理課長、日下部企画財政課長","answer":"今のメートル幾らとかですけれども、予算ベースのお話で言いますと、今回の１工区と５工区につきましては、すべての経費ということになりますけれども、全体で約１億２,８００万円ぐらいの経費と、これは予算上なっております。先ほど説明があったような形で埋設できるようなものをつくる、ただ、例えば北品川については総額で大体１３億円かかります。","id":"exchange-022"},{"speaker":"須貝委員","kind":"提案","question":"３つの提案がされましたけれども、傾くことは傾く、もう耐震しか持っていけないと思うんです。その辺、今日は時間がないので、ちょっと意見だけ言わせていただきましたとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"それは非常に大きな誤解でございまして、いずれにいたしましても、阪神淡路大震災並みの大きい地震が来ても、きちっと防災の中心的な役割を担う施設ですので、そういった機能がしっかり果たせるような補強法を考えてありますし、それはもう実現可能だと考えています。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816536?Template=document&Id=1726#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":22185,"voices":68}},{"id":"h18-20060828-6","meetingId":"h18-cm08","date":"2006年8月28日","dateIso":"2006-08-28","committee":"区民委員会","time":"午後１時０４分～午後４時１２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"１番目に、大崎第二地域センター移転計画","agenda":"１番目に、大崎第二地域センター移転計画","exchanges":[{"speaker":"土井委員","kind":"質問","question":"いわゆる無償で提供をされるのは、床面積というか、敷地面積というか、それだけというふうに理解してよろしいんですよね。ということは、いただいてしまうわけですから、後々の管理費等々は区のほうがずっとやっていくということになるのでよろしいんですね。","respondent":"田村地域活動課長","answer":"今、土井委員がおっしゃるとおり、無償譲渡というのは、床面積ということで、その後の管理については、区のほうで管理は行うという形になります。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"今のところは、狭いけれども２階に区民集会所を開放する施設がありますよね。そこのところというのは、これからの検討なのかもしれないけれども、基本的な考え方を説明するよう求めました。","respondent":"田村地域活動課長","answer":"それと、同じく３階に定員１０名の和室が１８m2です。３年先になりますけれども徐々に検討して、同程度の規模のものは確保したい、このように考えております。","id":"exchange-002"},{"speaker":"南委員","kind":"確認","question":"あそこは地域センターとあそこの住宅の方々との共同使用ではなかったですか。その辺を確認したいんですけれども。","respondent":"田村地域活動課長","answer":"今回の大崎第二地域センターの移転先については、そういうような話は特にございません。集会所はそれぞれの建物が２つに分かれていますので、特にその旨を、区民集会所を入居者の集会所として利用するという話は特に聞いてございません。","id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"そういうことが可能になってくるのかどうかということも含めて、どう対応されるおつもりなのか、いわゆる話としては交換という形になるかもしれない。３年先のことですから、ちょっとその辺はどうなのか尋ねました。","respondent":"田村地域活動課長","answer":"まだ３年先で、町会長方の受けとめ方も３年先かという話で終わっていますので、今後どうするのか検討していこうという形になっています。今後の話かなということです。","id":"exchange-004"},{"speaker":"堺委員","kind":"質問","question":"今までもそういうことはなかった。これに関連して今までなかったんか尋ねました。","respondent":"田村地域活動課長","answer":"特にそれに当たっての話は現在のところ具体的にはございません。","id":"exchange-005"},{"speaker":"堺委員","kind":"質問","question":"ほかの地域でもそういうようなことはなかったんか尋ねました。","respondent":"田村地域活動課長","answer":"ご指摘のように、ほかの地域でもそういう話は特にございません。","id":"exchange-006"}]},{"id":"topic-02","title":"の（２）番となります。医療制度改革","agenda":"の（２）番となります。医療制度改革","exchanges":[{"speaker":"南委員","kind":"質問","question":"今の説明で１つ、予防、予防というふうにおっしゃっていますよね。半分以上減らして１５万床にしてしまうとか、区の認識というのはどういうふうにとらえておられるのか、そこのところをまず伺いたいと思います。","respondent":"原国保年金課長","answer":"それから２点目の負担の部分ですけれど、今回また条例のほうで提案するわけですけれど、確かに負担は増える形になります。自己負担の２割から３割ですと、ここの部分についてはご理解をいただいて努めていきたいというふうに思っているところです。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、実態などもとらえて緩和できるような、中止を求めるような内容での行動が必要なのではないかなというふうに思っています。言いたいことはいっぱいあるんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問・要望","question":"というのは、その区民への周知で「広報しながわ」に掲載するときに、どういう表現でこの件について周知をされるのかということが僕は大事だろうと。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと確認なんですけれども、条例審査というのは、国保の条例改正の部分ですよね。そういうふうにしていただきたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"要するに、今度の審査は条例改正の部分ですから国保の部分だけですよね。担当会議のところで、ぜひ意見交換なり質疑をしたいというふうに思っているので、そういう意見を述べる時間を確保していただきたいというお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"１点だけ確認させていただきたいんですけれども、１番の（３）の現役並みの所得というのと、先ほど同じ説明の中で一定以上所得者という表現が出てきたんですけれども、これは事務事業概要の５ページにある説明書きでいいわけか尋ねました。","respondent":"原国保年金課長","answer":"今まで一定所得以上という表現で来ておりましたけれど、これからは現役並みの所得ということで、内容としては同じ内容ではありますけれど、呼び方がそういった形で統一されていくような形になると思います。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247239?Template=document&Id=2466#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":14174,"voices":56}}]);
